const entryListEl = document.getElementById('entryList');
const sectionTitleEl = document.getElementById('sectionTitle');
const sectionDescEl = document.getElementById('sectionDesc');

function excerptOf(text, len){
  if(!text) return '';
  const flat = text.replace(/\s+/g,' ').trim();
  return flat.length > len ? flat.slice(0, len).trim() + '…' : flat;
}

function buildTodayPanel(){
  const today = new Date();
  const matches = observancesFor(today).filter(o => o.type !== 'Season');
  const season = liturgicalSeason(today);
  const panel = document.createElement('div');
  panel.className = 'today-panel';
  const dateStr = today.toLocaleDateString(undefined, { month:'long', day:'numeric' });
  const label = `<div class="today-label">Today, ${escapeHtml(dateStr)} <span class="today-season" style="--season:${season.color}">${escapeHtml(season.name)}</span></div>`;
  if(matches.length){
    panel.innerHTML = label + matches.map(m => `<div class="today-item${m.saintId?' linked':''}" ${m.saintId?`data-id="${m.saintId}"`:''}><span class="today-dot" style="background:${CAL_TYPE_COLOR[m.type]||'var(--wine)'}"></span><strong>${escapeHtml(m.name)}</strong> <span class="today-type">(${escapeHtml(m.type)})</span></div>`).join('');
  } else {
    panel.innerHTML = label + `<div class="today-item">A weekday in ${escapeHtml(season.name)} \u2014 open the Calendar tab to see what\u2019s coming up.</div>`;
  }
  panel.insertAdjacentHTML('beforeend', `<button class="today-daily-link" type="button">Open today’s saint, prayer, and readings →</button>`);
  panel.querySelector('.today-daily-link').addEventListener('click', () => { dailyDate = startOfToday(); goToSection('daily'); });
  panel.querySelectorAll('.today-item.linked').forEach(el => el.addEventListener('click', () => openReadModal(el.dataset.id)));
  return panel;
}

