function cardArt(key){
  if(isEastern() && (key === 'budcross' || key === 'cross')) key = 'eastcross';
  if(isTraditional() && key === 'budcross') key = 'tradcross';
  return `<svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${CARD_ART[key] || ''}</svg>`;
}

function buildPrayerCards(list){
  const wrap = document.createElement('div');
  wrap.className = 'prayer-cards-wrap';
  wrap.innerHTML = `<div class="prayer-cards"></div>`;
  const grid = wrap.querySelector('.prayer-cards');
  const prayers = list || library.filter(e => e.category === 'prayer');
  prayers.forEach(e => {
    const id = e.id;
    const c = PRAYER_CARDS[id] || { art:'cross', accent:'var(--wine)' };
    const card = document.createElement('button');
    card.className = 'prayer-card';
    card.style.setProperty('--accent', c.accent);
    card.innerHTML = `
      <span class="pc-frame">
        <span class="pc-corner tl"></span><span class="pc-corner tr"></span><span class="pc-corner bl"></span><span class="pc-corner br"></span>
        <span class="pc-art">${cardArt(c.art)}</span>
        <span class="pc-title">${escapeHtml(e.title)}</span>
        <span class="pc-rule"><svg viewBox="0 0 64 64" fill="currentColor" aria-hidden="true"><path fill-rule="evenodd" d="${crossPath()}"/></svg></span>
        <span class="pc-line">${escapeHtml(excerptOf(e.content, 90))}</span>
      </span>`;
    card.addEventListener('click', () => openReadModal(id));
    grid.appendChild(card);
  });
  return wrap;
}

