let dailyDate = startOfToday();

function dayNumber(d){ return Math.floor(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / 86400000); }

// A fixed shuffle per list, so each day gets a different item and nothing repeats until the list runs out
function seededOrder(n, salt){
  const idx = Array.from({ length:n }, (_, i) => i);
  let s = (salt * 2654435761) >>> 0 || 1;
  const rnd = () => { s ^= s << 13; s >>>= 0; s ^= s >>> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; };
  for(let i = n - 1; i > 0; i--){ const j = Math.floor(rnd() * (i + 1)); [idx[i], idx[j]] = [idx[j], idx[i]]; }
  return idx;
}
const dailyOrders = {};
function dailyPick(list, salt, d){
  if(!list.length) return null;
  const key = salt + ':' + list.length;
  const order = dailyOrders[key] || (dailyOrders[key] = seededOrder(list.length, salt));
  return list[order[((dayNumber(d) % list.length) + list.length) % list.length]];
}

function mysterySetFor(d){
  if(isTraditional()) return {0:'glorious',1:'joyful',2:'sorrowful',3:'glorious',4:'joyful',5:'sorrowful',6:'glorious'}[d.getDay()];
  return {0:'glorious',1:'joyful',2:'sorrowful',3:'glorious',4:'luminous',5:'sorrowful',6:'joyful'}[d.getDay()];
}

function massReadingsUrl(d){
  const p = n => String(n).padStart(2, '0');
  return `https://bible.usccb.org/bible/readings/${p(d.getMonth() + 1)}${p(d.getDate())}${String(d.getFullYear()).slice(2)}.cfm`;
}

function goToSection(cat){
  navigate(ROUTES[cat] ? cat : (CAT_ROUTE[cat] || 'home'));
}

function renderDaily(){
  entryListEl.innerHTML = '';
  const d = dailyDate;
  const isToday = sameDay(d, startOfToday());
  const season = liturgicalSeason(d);
  const obs = observancesFor(d).filter(o => o.type !== 'Season');
  const byCat = cat => library.filter(e => e.category === cat);

  const feastIds = obs.flatMap(o => o.saints || []);
  const saint = feastIds.length ? library.find(x => x.id === feastIds[0]) : dailyPick(byCat('saint'), 11, d);
  const onFeast = feastIds.length > 0;
  const prayer = dailyPick(byCat('prayer').filter(p => p.id !== 'p10'), 23, d);
  const verse = dailyPick(DAILY_VERSES, 37, d);
  const book = dailyPick(byCat('book'), 41, d);
  const event = dailyPick(byCat('history'), 53, d);
  const bibleBook = dailyPick(byCat('bible'), 67, d);
  const topic = dailyPick(byCat('theology'), 79, d);
  const mysteryKey = mysterySetFor(d);
  const mysteries = MYSTERIES[mysteryKey];
  const card = PRAYER_CARDS[prayer.id] || { art:'cross', accent:'var(--wine)' };

  const head = document.createElement('div');
  head.className = 'daily-head';
  head.style.setProperty('--season', season.color);
  head.innerHTML = `
    <div class="cal-nav">
      <button class="cal-nav-btn" data-step="-1" aria-label="Previous day">‹</button>
      <div class="daily-date">${isToday ? 'Today, ' : ''}${dayLabel(d, d.getFullYear() !== new Date().getFullYear())}</div>
      <button class="cal-nav-btn" data-step="1" aria-label="Next day">›</button>
      ${isToday ? '' : '<button class="cal-nav-btn cal-today-btn" data-step="0">Today</button>'}
    </div>
    <span class="cal-pill"><span class="dot" style="background:${season.color}"></span>${escapeHtml(season.name)} · ${escapeHtml(season.colorName)}</span>`;
  head.querySelectorAll('[data-step]').forEach(b => b.addEventListener('click', () => {
    const step = Number(b.dataset.step);
    dailyDate = step === 0 ? startOfToday() : addDays(dailyDate, step);
    renderDaily();
  }));
  entryListEl.appendChild(head);

  const feast = document.createElement('div');
  feast.className = 'daily-feast';
  feast.style.setProperty('--season', season.color);
  feast.innerHTML = `
    <div class="daily-kicker">The Church celebrates</div>
    ${obs.length
      ? obs.map(o => `<div class="daily-feast-item"><span class="dot" style="background:${CAL_TYPE_COLOR[o.type] || 'var(--wine)'}"></span><strong>${escapeHtml(o.name)}</strong> <span class="today-type">${escapeHtml(o.type)}</span></div>`).join('')
      : `<div class="daily-feast-item">A weekday in ${escapeHtml(season.name)}.</div>`}
    ${dayNotes(d, obs).map(n => `<div class="cal-daynote">${escapeHtml(n)}</div>`).join('')}
    <div class="daily-links">
      ${isEastern() ? `<a class="daily-link" href="https://masstimes.org/" target="_blank" rel="noopener">Find a Divine Liturgy near you (MassTimes.org lists Eastern Catholic parishes) ↗</a>` : isTraditional() ? `
      <a class="daily-link" href="https://www.divinumofficium.com/" target="_blank" rel="noopener">The Mass and Divine Office of the day in Latin and English (Divinum Officium) ↗</a>
      <a class="daily-link" href="https://masstimes.org/" target="_blank" rel="noopener">Find Mass and Confession times near you ↗</a>` : `
      <a class="daily-link" href="${massReadingsUrl(d)}" target="_blank" rel="noopener">Read the Mass readings for this day (USCCB) ↗</a>
      <a class="daily-link" href="https://universalis.com/" target="_blank" rel="noopener">Pray the Liturgy of the Hours (Universalis) ↗</a>
      <a class="daily-link" href="https://masstimes.org/" target="_blank" rel="noopener">Find Mass and Confession times near you ↗</a>`}
    </div>`;
  entryListEl.appendChild(feast);

  const grid = document.createElement('div');
  grid.className = 'daily-grid';
  grid.innerHTML = `
    <article class="daily-card daily-saint" data-open="${saint.id}" tabindex="0">
      <div class="saint-portrait large" data-sid="${saint.id}">${portraitPlaceholder(saint.title)}</div>
      <div class="daily-body">
        <div class="daily-kicker">${onFeast ? 'Saint of the Day · Feast today' : 'Saint of the Day'}</div>
        <h3>${escapeHtml(saint.title)}</h3>
        <div class="byline">${escapeHtml(saint.author || '')}</div>
        <p class="daily-saint-life">${escapeHtml(excerptOf(saint.content, 320))}</p>
        <p class="daily-quote daily-saint-prayer"${saint.intercession ? '' : ' hidden'}>${escapeHtml(saint.intercession || '')}</p>
        <span class="daily-more">Read the full life →</span>
      </div>
    </article>

    <article class="daily-card daily-verse">
      <div class="daily-kicker">Verse of the Day</div>
      <blockquote>“${escapeHtml(verse.text)}”</blockquote>
      <cite>${escapeHtml(verse.ref)} · RSV-CE</cite>
      ${isEastern() ? '' : `<a class="daily-more" href="${massReadingsUrl(d)}" target="_blank" rel="noopener">Today’s full readings ↗</a>`}
      <button class="text-link verse-image" type="button" data-verse-image data-text="${escapeHtml(verse.text)}" data-ref="${escapeHtml(verse.ref)}">Share as image</button>
    </article>

    <article class="daily-card daily-prayer" data-open="${prayer.id}" tabindex="0" style="--accent:${card.accent}">
      <div class="daily-kicker">Prayer of the Day</div>
      <div class="pc-art">${cardArt(card.art)}</div>
      <h3>${escapeHtml(prayer.title)}</h3>
      <p class="daily-prayer-text">${escapeHtml(prayer.content.length > 420 ? excerptOf(prayer.content, 400) : prayer.content)}</p>
      <span class="daily-more">Pray it in full →</span>
    </article>

    ${isEastern() ? `<article class="daily-card daily-rosary">
      <div class="daily-kicker">The prayer of the heart</div>
      <h3>The Jesus Prayer</h3>
      <p class="rope-prayer small">${escapeHtml(JESUS_PRAYER)}</p>
      <button class="btn primary" id="dailyRosaryBtn">Pray with the prayer rope</button>
    </article>` : `<article class="daily-card daily-rosary">
      <div class="daily-kicker">The Rosary · ${WEEKDAY_NAMES[d.getDay()]}</div>
      <h3>${escapeHtml(mysteries.name)}</h3>
      <ol>${mysteries.list.map(m => `<li>${escapeHtml(m.name)}</li>`).join('')}</ol>
      <button class="btn primary" id="dailyRosaryBtn">Pray the ${escapeHtml(mysteries.name)}</button>
    </article>`}

    <article class="daily-card daily-book" data-open="${book.id}" tabindex="0">
      <div class="saint-portrait shape-book" data-sid="${book.id}">${portraitPlaceholder(book.title)}</div>
      <div class="daily-body">
        <div class="daily-kicker">Book of the Day</div>
        <h3>${escapeHtml(book.title)}</h3>
        <div class="byline">${escapeHtml(book.author || '')}</div>
        ${book.notable ? `<p class="daily-quote">${escapeHtml(book.notable)}</p>` : `<p>${escapeHtml(excerptOf(book.content, 200))}</p>`}
        <span class="daily-more">About this book →</span>
      </div>
    </article>

    <article class="daily-card daily-history" data-open="${event.id}" tabindex="0">
      <div class="saint-portrait shape-history" data-sid="${event.id}">${portraitPlaceholder(event.title)}</div>
      <div class="daily-body">
        <div class="daily-kicker">From Church History · ${escapeHtml(event.author || '')}</div>
        <h3>${escapeHtml(event.title)}</h3>
        <p>${escapeHtml(excerptOf(event.content, 200))}</p>
        <span class="daily-more">Read more →</span>
      </div>
    </article>

    <article class="daily-card daily-bible" data-open="${bibleBook.id}" tabindex="0">
      <div class="daily-kicker">Book of the Bible · ${escapeHtml(bibleBook.author || '')}</div>
      <h3>${escapeHtml(bibleBook.title)}</h3>
      <p>${escapeHtml(excerptOf(bibleBook.content, 220))}</p>
      <span class="daily-more">Study notes →</span>
    </article>

    <article class="daily-card daily-theology" data-open="${topic.id}" tabindex="0" style="--accent:var(--purple)">
      <div class="daily-kicker">Know Your Faith · ${topic.group === 'belief' ? 'Core Belief' : topic.group === 'fathers' ? 'The Faith of the Fathers' : 'Defending the Faith'}</div>
      <h3><span class="row-art">${cardArt(topic.art)}</span>${escapeHtml(topic.title)}</h3>
      <p>${escapeHtml(excerptOf(topic.content, 260))}</p>
      ${(topic.objections || []).length ? `<p class="daily-quote"><strong>Q:</strong> ${escapeHtml(topic.objections[0].q)}</p>` : ''}
      <span class="daily-more">Learn and defend it →</span>
    </article>`;
  entryListEl.appendChild(grid);
  grid.querySelectorAll('.saint-portrait[data-sid]').forEach(el => observePortrait(el));
  if(saint._t) withFullText(saint).then(() => {
    const life = grid.querySelector('.daily-saint-life'), prayerEl = grid.querySelector('.daily-saint-prayer');
    if(!life || saint._t) return;
    life.textContent = excerptOf(saint.content, 320);
    if(saint.intercession){ prayerEl.textContent = saint.intercession; prayerEl.hidden = false; }
  });

  grid.querySelectorAll('[data-open]').forEach(el => {
    el.addEventListener('click', () => openReadModal(el.dataset.open));
    el.addEventListener('keydown', ev => { if(ev.key === 'Enter' || ev.key === ' '){ ev.preventDefault(); openReadModal(el.dataset.open); } });
  });
  document.getElementById('dailyRosaryBtn').addEventListener('click', () => {
    rosarySet = mysteryKey;
    rosarySequence = null;
    goToSection('rosary');
  });
}

/* =========================================================
   THEOLOGY
   ========================================================= */
const THEOLOGY_GROUPS = [
  { key:'belief', name:'Core Catholic Beliefs', desc:'What the Church teaches, following the order of the Creed, with the Scripture and Catechism passages behind each teaching.' },
  { key:'fathers', name:'The Faith of the Fathers', desc:'What the Church Fathers of the first centuries believed and taught, in their own words, with the sources so you can read them in full.' },
  { key:'defense', name:'Defending the Faith', desc:'Apologetics: the reasons behind the faith, and charitable answers to the questions and objections Catholics most often hear.' },
  { key:'simple', name:'The Faith in Simple Words', desc:'The big words of the faith explained plainly: transubstantiation, consubstantial, infallibility, grace, and more.' }
];
let theologyGroup = 'all';

function renderTheology(){
  entryListEl.innerHTML = '';
  const entries = library.filter(e => e.category === 'theology');

  const chips = document.createElement('div');
  chips.className = 'patron-filters';
  chips.innerHTML = `<div class="patron-filters-label">Show:</div>
    <div class="patron-filters-row">
      <button class="patron-chip${theologyGroup === 'all' ? ' active' : ''}" data-group="all">Everything</button>
      ${THEOLOGY_GROUPS.map(g => `<button class="patron-chip${theologyGroup === g.key ? ' active' : ''}" data-group="${g.key}">${escapeHtml(g.name)}</button>`).join('')}
    </div>`;
  const groupRoute = { all:'learn/theology', belief:'learn/theology/beliefs', fathers:'learn/theology/fathers', defense:'learn/theology/apologetics', simple:'learn/theology/simple-words' };
  chips.querySelectorAll('.patron-chip').forEach(b => b.addEventListener('click', () => navigate(groupRoute[b.dataset.group])));
  entryListEl.appendChild(chips);

  THEOLOGY_GROUPS.filter(g => theologyGroup === 'all' || g.key === theologyGroup).forEach(g => {
    const section = document.createElement('section');
    section.className = 'theology-group';
    section.innerHTML = `<h3 class="list-heading">${escapeHtml(g.name)}</h3><p class="theology-group-desc">${escapeHtml(g.desc)}</p><div class="theology-grid"></div>`;
    const grid = section.querySelector('.theology-grid');
    entries.filter(e => e.group === g.key).forEach(e => {
      const row = document.createElement('div');
      row.className = 'entry-row theology-row';
      row.style.setProperty('--row-color', 'var(--purple)');
      row.style.setProperty('--accent', 'var(--purple)');
      row.innerHTML = `
        <div class="row-top">
          <h3><span class="row-art">${cardArt(e.art)}</span>${escapeHtml(e.title)}</h3>
          <span class="cat-badge">${g.key === 'belief' ? 'Belief' : g.key === 'fathers' ? 'Church Fathers' : g.key === 'simple' ? 'Simple Words' : 'Apologetics'}</span>
        </div>
        <div class="excerpt">${escapeHtml(excerptOf(e.content, 200))}</div>
        <div class="theology-meta">
          <span>${e.scripture.length} Scripture passages</span>
          <span>CCC ${escapeHtml(e.ccc)}</span>
          ${(e.objections || []).length ? `<span>${e.objections.length} common ${e.objections.length === 1 ? 'objection' : 'objections'} answered</span>` : ''}
        </div>`;
      row.addEventListener('click', () => openReadModal(e.id));
      grid.appendChild(row);
    });
    entryListEl.appendChild(section);
  });
}

// Extra reading-view sections for theology entries
function buildTheologyBlocks(e){
  const frag = document.createDocumentFragment();
  const block = (title, html) => {
    const div = document.createElement('div');
    div.className = 'intercession-block theo-block';
    div.innerHTML = `<h3>${title}</h3>${html}`;
    frag.appendChild(div);
  };
  if(e.points && e.points.length){
    block(e.group === 'defense' ? 'The Case' : 'Key Points', `<ul class="theo-points">${e.points.map(p => `<li>${escapeHtml(p)}</li>`).join('')}</ul>`);
  }
  if(e.scripture && e.scripture.length){
    block('In Scripture', `<div class="theo-refs">${e.scripture.map(s => `<span class="theo-ref">${escapeHtml(s)}</span>`).join('')}</div>`);
  }
  if(e.ccc){
    block('In the Catechism', `<p class="theo-ccc">Catechism of the Catholic Church, paragraphs ${cccLinksHtml(e.ccc)}. Tap a number to find it in the Catechism.</p>`);
  }
  if(e.objections && e.objections.length){
    block('Common Objections', e.objections.map((o, i) =>
      `<details class="theo-objection"${i === 0 ? ' open' : ''}><summary>${escapeHtml(o.q)}</summary><p>${escapeHtml(o.a)}</p></details>`).join(''));
  }
  return frag;
}

