const SAINTLY_DESC = /saint|martyr|pope|apostle|bishop|priest|nun|friar|monk|archangel|theolog|mystic|abbess|abbot|virgin|evangelist|missionary|hermit|deacon|jesuit|franciscan|dominican|carmelite|christian|catholic|religious|prophet|mother of|father of|patron|jesus|disciple|church|patriarch|cardinal|gospel|founder/i;
const PORTRAIT_CACHE_KEY = 'sanctify.saintPortraits.v3';
let portraitCache = {};
try{ portraitCache = JSON.parse(localStorage.getItem(PORTRAIT_CACHE_KEY)) || {}; }catch(e){}
let portraitsPromise = null;
let portraitRetryAt = 0;

function saintWikiCandidates(s){
  if(SAINT_WIKI[s.title]) return [{ title:SAINT_WIKI[s.title], trusted:true }];
  const core = s.title.replace(/\s*\(.*?\)/g, '').replace(/\s+and companions$/i, '').replace(/^(pope\s+)?(st\.|sts\.|ss\.)\s+/i, '').trim();
  const list = [{ title:'Saint ' + core }, { title:core }];
  if(/^pope/i.test(s.title)) list.push({ title:'Pope ' + core });
  return list;
}

// Candidate Wikipedia articles for any entry. Books and history events move on to the next
// candidate when an article has no picture; saints stop at the first matching article.
function entryWikiCandidates(e){
  if(e.category === 'saint') return saintWikiCandidates(e);
  return (ENTRY_WIKI[e.id] || []).map(title => ({ title, trusted:true, needImage:true }));
}
const HAS_PICTURE = new Set(['saint', 'book', 'history']);

// Looks up to 50 titles in one request; returns { requestedTitle: page or null }
async function wikiLookup(titles){
  const url = 'https://en.wikipedia.org/w/api.php?action=query&format=json&formatversion=2&origin=*&redirects=1'
    + '&prop=pageimages%7Cdescription%7Cpageprops%7Cinfo&inprop=url&piprop=thumbnail&pithumbsize=400&ppprop=disambiguation'
    + '&titles=' + encodeURIComponent(titles.join('|'));
  const r = await fetch(url);
  if(!r.ok) throw new Error('Wikipedia returned ' + r.status);
  const q = (await r.json()).query || {};
  const resolved = {};
  titles.forEach(t => { resolved[t] = t; });
  const follow = list => (list || []).forEach(n => { for(const k in resolved) if(resolved[k] === n.from) resolved[k] = n.to; });
  follow(q.normalized);
  follow(q.redirects);
  const pages = {};
  (q.pages || []).forEach(p => { pages[p.title] = p; });
  const out = {};
  titles.forEach(t => { out[t] = pages[resolved[t]] || null; });
  return out;
}

// Resolves every picture in a handful of batched requests, trying each candidate article in turn
function loadAllPortraits(){
  if(portraitsPromise) return portraitsPromise;
  if(Date.now() < portraitRetryAt) return Promise.resolve();
  portraitsPromise = (async () => {
    let pending = library.filter(e => HAS_PICTURE.has(e.category) && !(e.id in portraitCache) && !(SAINT_ICONS[e.id] && !ICON_FAILED.has(e.id)))
      .map(s => ({ s, cands:entryWikiCandidates(s) }));
    for(let round = 0; pending.length; round++){
      pending.filter(p => !p.cands[round]).forEach(p => { portraitCache[p.s.id] = null; });
      const batch = pending.filter(p => p.cands[round]);
      const next = [];
      for(let i = 0; i < batch.length; i += 50){
        const chunk = batch.slice(i, i + 50);
        const res = await wikiLookup([...new Set(chunk.map(p => p.cands[round].title))]);
        chunk.forEach(p => {
          const c = p.cands[round], page = res[c.title];
          const ok = page && !page.missing && !(page.pageprops && 'disambiguation' in page.pageprops)
            && (c.trusted || SAINTLY_DESC.test(page.description || ''))
            && (!c.needImage || page.thumbnail);
          if(ok) portraitCache[p.s.id] = page.thumbnail ? { src:page.thumbnail.source, page:page.fullurl || '' } : null;
          else next.push(p);
        });
      }
      pending = next;
    }
  })().then(flushWaitingPortraits).catch(() => {
    portraitsPromise = null;   // offline or rate-limited: keep what we have, retry after a minute
    portraitRetryAt = Date.now() + 60000;
    setTimeout(() => { if(portraitWaiting.size) loadAllPortraits(); }, 61000);
  }).finally(() => {
    try{ localStorage.setItem(PORTRAIT_CACHE_KEY, JSON.stringify(portraitCache)); }catch(e){}
  });
  return portraitsPromise;
}

