const ICON_FAILED = new Set();   // icons that would not load fall back to the Wikipedia picture
function saintIcon(id){
  const url = SAINT_ICONS[id], parts = url.split('/');
  const file = url.includes('/thumb/') ? parts[parts.length - 2] : parts[parts.length - 1];
  return { src:url, page:'https://commons.wikimedia.org/wiki/File:' + file, icon:true };
}

// Resolves to the picture, null if there is none, or undefined if the lookup hasn't succeeded yet
function fetchSaintPortrait(s){
  if(SAINT_ICONS[s.id] && !ICON_FAILED.has(s.id)) return Promise.resolve(saintIcon(s.id));
  if(s.id in portraitCache) return Promise.resolve(portraitCache[s.id]);
  return loadAllPortraits().then(() => portraitCache[s.id]);
}

// Frames still showing a placeholder because a lookup failed; filled in once a retry succeeds
const portraitWaiting = new Set();
function flushWaitingPortraits(){
  const els = [...portraitWaiting];
  portraitWaiting.clear();
  els.forEach(el => {
    const s = el.isConnected && library.find(x => x.id === el.dataset.sid);
    if(s) fillPortrait(el, s);
  });
}

function saintInitial(title){
  const core = title.replace(/^(pope\s+)?(st\.|sts\.|ss\.)\s+/i, '').replace(/^(the|a|an)\s+/i, '').replace(/^[^A-Za-zÀ-ÿ]+/, '');
  return core.charAt(0).toUpperCase();
}

function portraitPlaceholder(title){
  return `<span class="portrait-initial notranslate" translate="no">${escapeHtml(saintInitial(title))}</span>`;
}

function fillPortrait(el, s){
  fetchSaintPortrait(s).then(p => {
    if(!el.isConnected) return;
    if(p === undefined){ portraitWaiting.add(el); return; }
    if(!p) return;
    const img = new Image();
    img.alt = p.icon ? 'Icon of ' + s.title : s.category === 'saint' ? 'Traditional image of ' + s.title : 'Illustration for ' + s.title;
    img.decoding = 'async';
    img.onload = () => { el.innerHTML = ''; el.appendChild(img); el.classList.add('loaded'); };
    img.onerror = () => {
      if(!p.icon || ICON_FAILED.has(s.id)) return;
      ICON_FAILED.add(s.id);
      portraitsPromise = null;
      fillPortrait(el, s);
      const cap = el.parentElement && el.parentElement.querySelector('figcaption');
      if(cap){
        cap.innerHTML = '';
        fetchSaintPortrait(s).then(w => { if(w && w.page && el.isConnected) cap.innerHTML = `<a href="${escapeHtml(w.page)}" target="_blank" rel="noopener">Image via Wikipedia ↗</a>`; });
      }
    };
    img.src = p.src;
  });
}

const portraitObserver = ('IntersectionObserver' in window) ? new IntersectionObserver(entries => {
  entries.forEach(en => {
    if(!en.isIntersecting) return;
    portraitObserver.unobserve(en.target);
    const s = library.find(x => x.id === en.target.dataset.sid);
    if(s) fillPortrait(en.target, s);
  });
}, { rootMargin:'300px' }) : null;

function observePortrait(el){
  if(portraitObserver) portraitObserver.observe(el);
  else { const s = library.find(x => x.id === el.dataset.sid); if(s) fillPortrait(el, s); }
}

/* =========================================================
   CHURCH HISTORY TIMELINE
   ========================================================= */
const HISTORY_ERAS = [
  { key:'apostolic', name:'The Apostolic Age', span:'c. 33–100' },
  { key:'early', name:'The Early Church', span:'100–476' },
  { key:'earlymed', name:'The Early Middle Ages', span:'476–1000' },
  { key:'medieval', name:'The High & Late Middle Ages', span:'1000–1492' },
  { key:'reform', name:'Reformation & Catholic Renewal', span:'1492–1789' },
  { key:'modern', name:'Revolution & the Modern Church', span:'1789–present' }
];
let activeEra = 'all';
let historyMarianOnly = false;
let historyCrusadesOnly = false;

function renderHistory(){
  entryListEl.innerHTML = '';
  let all = currentEntries().slice().sort((a,b) => (a.year||0) - (b.year||0));
  if(historyMarianOnly) all = all.filter(e => (e.tags || []).includes('apparition'));
  if(historyCrusadesOnly) all = all.filter(e => (e.tags || []).includes('crusades'));

  const chips = document.createElement('div');
  chips.className = 'patron-filters';
  chips.innerHTML = `<div class="patron-filters-label">Jump to an era:</div>
    <div class="patron-filters-row">
      <button class="patron-chip${activeEra==='all'?' active':''}" data-era="all">All eras</button>
      ${HISTORY_ERAS.map(er => `<button class="patron-chip${activeEra===er.key?' active':''}" data-era="${er.key}">${escapeHtml(er.name)}</button>`).join('')}
    </div>
    <div class="patron-filters-label" style="margin-top:12px">Topic:</div>
    <div class="patron-filters-row">
      <button class="patron-chip${historyMarianOnly ? ' active' : ''}" id="marianToggle" aria-pressed="${historyMarianOnly}">✦ Marian apparitions only</button>
      <button class="patron-chip${historyCrusadesOnly ? ' active' : ''}" id="crusadesToggle" aria-pressed="${historyCrusadesOnly}">✠ The Crusades & military orders</button>
      <button class="patron-chip" data-route="history/popes">The Popes</button>
      <button class="patron-chip" data-route="history/orders">Religious Orders</button>
    </div>`;
  chips.querySelectorAll('.patron-chip[data-era]').forEach(btn => {
    btn.addEventListener('click', () => { activeEra = btn.dataset.era; renderHistory(); });
  });
  chips.querySelector('#marianToggle').addEventListener('click', () => navigate(historyMarianOnly ? 'history/timeline' : 'history/timeline/apparitions'));
  chips.querySelector('#crusadesToggle').addEventListener('click', () => navigate(historyCrusadesOnly ? 'history/timeline' : 'history/timeline/crusades'));
  entryListEl.appendChild(chips);

  const eras = HISTORY_ERAS.filter(er => activeEra === 'all' || er.key === activeEra);
  let shown = 0;
  eras.forEach(er => {
    const items = all.filter(e => e.era === er.key);
    if(!items.length) return;
    shown += items.length;
    const group = document.createElement('div');
    group.className = 'month-group history-era';
    group.innerHTML = `<h3>${escapeHtml(er.name)} <span class="era-span">${escapeHtml(er.span)}</span></h3>`;
    items.forEach(e => {
      const row = document.createElement('div');
      row.className = 'cal-row history-row';
      row.innerHTML = `
        <div class="cal-date">${escapeHtml(e.author || '')}</div>
        <div class="cal-dot" style="--row-color:${(e.tags || []).includes('apparition') ? 'var(--rose)' : 'var(--green)'}"></div>
        <div class="cal-body tl-card">
          <div class="tl-text">
            <div class="cal-name">${escapeHtml(e.title)}</div>
            <div class="cal-note">${escapeHtml(excerptOf(e.content, 170))}</div>
          </div>
          <div class="saint-portrait shape-history history-thumb" data-sid="${e.id}">${portraitPlaceholder(e.title)}</div>
        </div>
      `;
      observePortrait(row.querySelector('.history-thumb'));
      row.addEventListener('click', () => openReadModal(e.id));
      group.appendChild(row);
    });
    entryListEl.appendChild(group);
  });

  if(!shown){
    const div = document.createElement('div');
    div.className = 'empty-state';
    div.innerHTML = `Nothing here matches your search.<br><button class="btn" id="clearFromEmpty">Clear search</button>`;
    entryListEl.appendChild(div);
    document.getElementById('clearFromEmpty').addEventListener('click', () => { document.getElementById('searchInput').value=''; searchTerm=''; activeEra='all'; render(); });
  }
}

function escapeHtml(str){
  return (str||'').replace(/[&<>"']/g, m => ({
    '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'
  }[m]));
}

