const SEASON_ACCENT = { violet:'#5b3f86', white:'#94701a', green:'#3e6b3a', red:'#9b1c1f', rose:'#b04a73' };
const SEASON_ACCENT_DARK = { violet:'#b99be6', white:'#e3c46e', green:'#86bb80', red:'#e8716f', rose:'#e991b5' };
const SEASONAL_THEMES = new Set(['liturgical', 'liturgical-dark']);
function todaysLiturgicalColor(){
  // The Byzantine calendar is defined further down, so on first load in the Eastern edition
  // this can run too early; applyRite() sets the season color again once everything is ready.
  try{
    const name = liturgicalSeason(startOfToday()).colorName;
    return name === 'white and red' ? 'red' : name === 'black' ? 'violet' : name;
  }catch(e){ return 'green'; }
}

