const TLM_GUIDE = [
  { id:'tlm-kinds', name:'Low Mass, High Mass, and Solemn High Mass', icon:'mass', color:'gold', kicker:'Three ways it is celebrated',
    items:[
      ['Low Mass (Missa lecta)', 'Said by the priest with one or two servers. Quiet and prayerful; the people mostly kneel. Hymns may be sung.'],
      ['High Mass (Missa cantata)', 'Sung by the priest with a choir, often with incense. The people stand more often and may sing the responses and the Ordinary in chant.'],
      ['Solemn High Mass', 'Sung with a deacon and subdeacon assisting the priest, the fullest form of the Roman liturgy.'],
      ['Requiem Mass', 'A Mass for the dead in black vestments, with the Dies Irae and no Gloria, Alleluia, or blessing.']
    ] },
  { id:'tlm-year', name:'The 1962 Calendar', icon:'calendar', color:'purple', kicker:'The seasons of the traditional year', items:[
      ['Advent', 'Four weeks of preparation for Christmas. Violet; rose on Gaudete Sunday.'],
      ['Christmastide and the Time after Epiphany', 'From Christmas through the Sundays after the Epiphany. White, then green.'],
      ['Septuagesima', 'The three Sundays before Lent: Septuagesima, Sexagesima, and Quinquagesima. Violet; the Gloria and Alleluia fall silent.'],
      ['Lent and Passiontide', 'From Ash Wednesday. In the last two weeks, from Passion Sunday, crosses and images are veiled.'],
      ['Eastertide', 'From Easter to the octave of Pentecost. White, and red for Pentecost.'],
      ['The Time after Pentecost', 'The long green season of Sundays from Trinity Sunday until Advent.'],
      ['Ember and Rogation Days', 'Days of fasting and prayer at the four seasons, and of prayer for the harvest before the Ascension.']
    ] },
  { id:'tlm-tips', name:'Your First Latin Mass', icon:'compass', color:'teal', kicker:'Tips for newcomers', items:[
      ['Bring a hand missal', 'Many churches lend booklets with the Latin and English side by side. Don’t worry about following every word.'],
      ['Follow the people around you', 'Postures vary from place to place. When in doubt, kneel.'],
      ['Let the silence pray', 'Much of the Mass is said quietly by the priest. Unite your prayer with his.'],
      ['Receiving Communion', 'Kneel at the rail and receive on the tongue. Do not say “Amen.” The usual rules apply: be in a state of grace and keep the one-hour fast.'],
      ['Dress', 'Many people dress in their Sunday best, and many women wear a chapel veil, though it is not required.']
    ],
    note:'The Missal of 1962 is the last edition of the Roman Missal from before the reforms after Vatican II. Since 2021 it may be celebrated with the permission of the diocesan bishop. Ask your parish or diocese where it is offered near you.' }
];
let massStep = null;   // null: the overview; otherwise the step in "follow along" mode
let massForm = null;   // which guide massStep belongs to

function postureBadge(p, note){
  return `<span class="posture posture-${p}" title="${escapeHtml(note || POSTURE_NAME[p])}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${POSTURE_ICONS[p]}</svg>${POSTURE_NAME[p]}</span>`;
}

function latinHtml(text){
  return `<p class="mass-latin notranslate" translate="no" lang="la">${text.split('\n').map(escapeHtml).join('<br>')}</p>`;
}
function renderMass(){
  const tlm = !!(ROUTES[currentRoute] || {}).tlm || isTraditional();
  const form = tlm ? 'tlm' : isEastern() ? 'east' : 'ordinary';
  if(massForm !== form){ massForm = form; massStep = null; }
  const PARTS = tlm ? TLM_PARTS : isEastern() ? LITURGY_PARTS : MASS_PARTS;
  const flat = PARTS.flatMap((s, si) => s.parts.map(p => ({ ...p, section:s.section, si })));
  if(massStep !== null){
    if(massStep >= flat.length){
      logPrayer('mass');
      return renderDevotionDone({ kind:'mass', color:'var(--wine)', emblem:devoMedal(cardArt('chalice')), title:tlm ? 'Deo gratias' : 'Go in peace',
        text:tlm ? 'Ite, missa est.' : 'Thanks be to God.', againLabel:tlm ? 'Back to the Latin Mass guide' : 'Back to The Mass Explained', again:() => { massStep = null; renderMass(); } });
    }
    const p = flat[massStep];
    return renderDevotionStep({
      kind:'mass', color:'var(--wine)', step:massStep, total:flat.length,
      emblem:postureBadge(p.posture, p.note), kicker:escapeHtml(p.section), title:p.name,
      body:`${p.latin ? latinHtml(p.latin) : ''}<p>${escapeHtml(p.what)}</p>${p.note ? `<p class="devo-small">${escapeHtml(p.note)}</p>` : ''}`,
      extra:`<p class="mass-why">${escapeHtml(p.why)}</p>${p.ref ? `<div class="devo-meta">${scriptureLink(p.ref)}</div>` : ''}`,
      track:`<div class="devo-pips always" aria-hidden="true">${PARTS.map((s, i) => `<span class="${i < p.si ? 'done' : i === p.si ? 'current' : ''}">${ROMAN[i]}</span>`).join('')}</div>`,
      go:i => { massStep = Math.max(0, Math.min(i, flat.length)); renderMass(); window.scrollTo({ top:0 }); },
      exit:() => { massStep = null; renderMass(); }, exitLabel:'Back to the overview'
    });
  }
  devoKeys = null;
  let n = 0;
  const forms = isTraditional() ? `<p class="dv-note">The Mass of Paul VI, celebrated in most parishes today, is explained in the <button class="text-link" data-rite-switch="latin">Roman Catholic edition</button>.</p>`
    : !isEastern() ? `
      <div class="lo-tabs mass-forms" role="tablist" aria-label="Form of the Mass">
        <button role="tab" class="lo-tab${tlm ? '' : ' active'}" aria-selected="${!tlm}" data-route="learn/mass"><strong>The Mass today</strong><span>Missal of Paul VI (Novus Ordo)</span></button>
        <button role="tab" class="lo-tab${tlm ? ' active' : ''}" aria-selected="${tlm}" data-route="learn/latin-mass"><strong>The Traditional Latin Mass</strong><span>Missal of 1962 (Vetus Ordo)</span></button>
      </div>` : tlm ? `<p class="dv-note">This is the Latin Mass of the Roman Church. <button class="text-link" data-route="learn/mass">The Divine Liturgy Explained →</button></p>` : '';
  entryListEl.innerHTML = `
    <div class="mass-page">
      ${forms}
      <section class="mass-intro">
        <div>
          <p>${tlm ? TLM_INTRO : massIntroText()}</p>
          <div class="mass-legend">${Object.keys(POSTURE_NAME).filter(p => (isEastern() && !tlm) || p !== 'bow').map(p => postureBadge(p)).join('')}<span class="mass-legend-note">${tlm ? TLM_POSTURE_NOTE : massPostureNote()}</span></div>
        </div>
        <button class="btn primary pill" id="massFollow">Follow along at ${tlm ? 'the Latin Mass' : isEastern() ? 'the Divine Liturgy' : 'Mass'}</button>
      </section>
      <nav class="mass-strip" aria-label="Parts of the Mass">${PARTS.map((s, i) => `<a href="#mass-${i}" class="mass-strip-seg" style="flex:${s.parts.length} 1 auto"><span>${ROMAN[i]}</span>${escapeHtml(s.section)}</a>`).join('')}</nav>
      ${PARTS.map((s, si) => `
        <section class="mass-section" id="mass-${si}">
          <h3 class="mass-section-title"><span class="mass-roman">${ROMAN[si]}</span>${escapeHtml(s.section)}</h3>
          <ol class="mass-list">${s.parts.map(p => { n++; return `
            <li class="mass-part">
              <span class="mass-num">${n}</span>
              <div class="mass-body">
                <div class="mass-head"><h4>${escapeHtml(p.name)}</h4>${postureBadge(p.posture, p.note)}</div>
                ${p.when ? `<div class="mass-when">${escapeHtml(p.when)}</div>` : ''}
                ${p.note ? `<div class="mass-when">${escapeHtml(p.note)}</div>` : ''}
                ${p.latin ? latinHtml(p.latin) : ''}
                <p>${escapeHtml(p.what)}</p>
                <p class="mass-why">${escapeHtml(p.why)}</p>
                ${p.ref ? scriptureLink(p.ref) : ''}
              </div>
            </li>`; }).join('')}</ol>
        </section>`).join('')}
      ${tlm ? `<div class="dv-page tlm-guide">${TLM_GUIDE.map(lsCardHtml).join('')}</div>` : ''}
      <p class="shop-note">${isEastern() ? 'Find a Divine Liturgy near you at <a href="https://masstimes.org/" target="_blank" rel="noopener">MassTimes.org</a>, which also lists Eastern Catholic parishes.' : 'Find Mass times near you at <a href="https://masstimes.org/" target="_blank" rel="noopener">MassTimes.org</a>, and the readings for any day in the Calendar.'}</p>
    </div>`;
  document.getElementById('massFollow').addEventListener('click', () => { massStep = 0; renderMass(); window.scrollTo({ top:0 }); });
  entryListEl.querySelectorAll('.mass-strip-seg').forEach(a => a.addEventListener('click', ev => {
    ev.preventDefault();
    document.querySelector(a.getAttribute('href')).scrollIntoView({ behavior:'smooth', block:'start' });
  }));
}

/* =========================================================
   CATHOLIC GLOSSARY: words of the faith, A to Z
   ========================================================= */
const GLOSSARY = [
  ['Absolution', 'The forgiveness of sins pronounced by a priest in the sacrament of Confession, by the authority Christ gave the apostles.'],
  ['Abstinence', 'Refraining from meat on certain days of penance, such as Ash Wednesday and the Fridays of Lent, for Catholics fourteen and older.'],
  ['Advent', 'The four weeks of preparation before Christmas, a season of joyful waiting for Christ’s coming at Christmas and at the end of time. Its color is violet.'],
  ['Alleluia', 'A Hebrew word meaning “Praise the Lord,” sung before the Gospel and throughout the Easter season, but omitted during Lent.'],
  ['Altar', 'The table on which the sacrifice of the Mass is offered. It is a symbol of Christ, and is kissed by the priest at the beginning and end of Mass.'],
  ['Anointing of the Sick', 'The sacrament in which a priest anoints the seriously ill or elderly with blessed oil, giving them strength, peace, and the forgiveness of sins.'],
  ['Apologetics', 'The reasoned explanation and defense of the Christian faith, from the Greek word for “a defense.”'],
  ['Apostolic Succession', 'The unbroken handing on of the apostles’ mission and authority to the bishops through the laying on of hands.'],
  ['Ascension', 'Christ’s return in His glorified body to the Father, forty days after the Resurrection.'],
  ['Assumption', 'The dogma that the Virgin Mary, at the end of her earthly life, was taken up body and soul into heavenly glory. Defined in 1950 and celebrated on August 15.'],
  ['Baptism', 'The first sacrament, which frees us from original sin, makes us children of God and members of the Church, and opens the way to the other sacraments.'],
  ['Beatific Vision', 'The direct sight of God face to face, which is the perfect happiness of the saints in heaven.'],
  ['Beatification', 'The Church’s declaration that a deceased person lived a holy life and is in heaven, allowing them to be honored as “Blessed.” It is a step toward canonization.'],
  ['Benediction', 'A service of prayer in which the Blessed Sacrament is exposed in a monstrance, adored, and used by the priest to bless the people.'],
  ['Bishop', 'A successor of the apostles who has received the fullness of Holy Orders and shepherds a diocese as its teacher, priest, and pastor.'],
  ['Blessed Sacrament', 'The Eucharist, especially the consecrated Hosts reserved in the tabernacle, in which Christ is truly present.'],
  ['Breviary', 'The book containing the Liturgy of the Hours, the daily prayer of the Church.'],
  ['Canon of Scripture', 'The list of books the Church recognizes as inspired Scripture: 46 in the Old Testament and 27 in the New, 73 in all.'],
  ['Canon Law', 'The body of laws governing the life and organization of the Catholic Church, collected in the Code of Canon Law.'],
  ['Canonization', 'The pope’s solemn declaration that a person is a saint in heaven, worthy of public veneration by the whole Church.'],
  ['Cardinal', 'A senior bishop or priest appointed by the pope to advise him and, if under eighty, to elect a new pope in a conclave.'],
  ['Cardinal Virtues', 'The four moral virtues on which all others “hinge”: prudence, justice, fortitude, and temperance.'],
  ['Catechism', 'A summary of Catholic teaching. The Catechism of the Catholic Church, published in 1992, is the official reference for the whole Church.'],
  ['Catechumen', 'An unbaptized person preparing to enter the Church through Baptism, Confirmation, and the Eucharist.'],
  ['Chalice', 'The cup that holds the wine that becomes the Precious Blood of Christ at Mass.'],
  ['Charism', 'A special gift of the Holy Spirit given for the good of the Church, such as the particular spirit of a religious order.'],
  ['Chrism', 'Olive oil mixed with balsam and consecrated by the bishop, used in Baptism, Confirmation, and Holy Orders.'],
  ['Ciborium', 'A covered vessel used to hold the consecrated Hosts for Communion and for reservation in the tabernacle.'],
  ['Communion of Saints', 'The union of all the faithful in Christ: the saints in heaven, the souls in purgatory, and the Church on earth, who help one another by prayer.'],
  ['Conclave', 'The closed meeting of cardinals in the Sistine Chapel to elect a new pope.'],
  ['Concupiscence', 'The inclination toward sin that remains in us after Baptism as an effect of original sin.'],
  ['Confession', 'The sacrament of Penance and Reconciliation, in which sins committed after Baptism are forgiven through the absolution of a priest.'],
  ['Confirmation', 'The sacrament that completes Baptism, sealing the baptized with the gift of the Holy Spirit and strengthening them to witness to Christ.'],
  ['Consecration', 'The moment at Mass when, by the words of Christ spoken by the priest, the bread and wine become the Body and Blood of Christ.'],
  ['Contrition', 'Sorrow for sin with the resolve not to sin again. Perfect contrition comes from love of God; imperfect contrition from lesser motives such as fear of punishment.'],
  ['Covenant', 'A solemn, binding relationship between God and His people, made with Noah, Abraham, Moses, and David, and fulfilled in the New Covenant in Christ’s blood.'],
  ['Creed', 'A summary statement of the faith, such as the Apostles’ Creed or the Nicene Creed, from the Latin credo, “I believe.”'],
  ['Deacon', 'A man ordained to the first degree of Holy Orders to serve the Church through proclaiming the Gospel, preaching, baptizing, and works of charity.'],
  ['Deposit of Faith', 'The whole of God’s revelation, contained in Sacred Scripture and Sacred Tradition, entrusted to the Church to guard and hand on.'],
  ['Diocese', 'A local Church, usually a geographic area, led by a bishop.'],
  ['Doctor of the Church', 'A title given to saints whose writings have been of special benefit to the whole Church, such as St. Augustine and St. Thérèse of Lisieux.'],
  ['Dogma', 'A truth revealed by God that the Church has solemnly defined and that all Catholics are bound to believe.'],
  ['Doxology', 'A short hymn of praise to God, such as the Glory Be or the conclusion of the Eucharistic Prayer.'],
  ['Easter Triduum', 'The three holiest days of the year, from the evening Mass of the Lord’s Supper on Holy Thursday through Easter Sunday.'],
  ['Ecumenical Council', 'A gathering of the world’s bishops in union with the pope to teach and govern the whole Church. There have been twenty-one, from Nicaea to Vatican II.'],
  ['Ecumenism', 'The work of restoring unity among all Christians.'],
  ['Encyclical', 'A letter from the pope to the whole Church, or to the world, on a matter of faith, morals, or society.'],
  ['Epiphany', 'The feast celebrating Christ revealed to the nations, recalled in the visit of the Magi.'],
  ['Eucharist', 'The sacrament of Christ’s Body and Blood, the source and summit of the Christian life. The word means “thanksgiving.”'],
  ['Evangelization', 'Bringing the Good News of Jesus Christ to others by word and example.'],
  ['Ex Cathedra', 'Latin for “from the chair.” The pope speaks ex cathedra when he solemnly defines a doctrine of faith or morals for the whole Church; such teaching is infallible.'],
  ['Excommunication', 'A serious penalty that excludes a Catholic from receiving the sacraments until they repent and are reconciled. Its purpose is to call the person back.'],
  ['Fasting', 'Limiting food as a form of penance. Catholics aged eighteen to fifty-nine fast on Ash Wednesday and Good Friday.'],
  ['Genuflection', 'Bending the right knee to the floor as a sign of adoration before Christ present in the tabernacle.'],
  ['Grace', 'The free and undeserved gift of God’s own life in us. Sanctifying grace makes us holy; actual grace helps us to act rightly.'],
  ['Holy Days of Obligation', 'Feasts besides Sundays on which Catholics are required to attend Mass, such as Christmas and the Immaculate Conception.'],
  ['Holy Orders', 'The sacrament by which men are ordained deacons, priests, or bishops to serve the Church.'],
  ['Holy See', 'The pope and the central government of the Catholic Church in Rome, from the Latin sancta sedes, “holy seat.”'],
  ['Homily', 'The sermon given by a priest or deacon after the Gospel at Mass, explaining the readings.'],
  ['Host', 'The bread consecrated at Mass, from the Latin hostia, “victim” or “sacrifice.”'],
  ['Icon', 'A sacred image, especially in the Eastern tradition, painted according to ancient rules as a window to heavenly realities.'],
  ['Immaculate Conception', 'The dogma that the Virgin Mary was preserved free from original sin from the first moment of her conception. Defined in 1854 and celebrated on December 8.'],
  ['Incarnation', 'The mystery of the eternal Son of God becoming man in the womb of the Virgin Mary, true God and true man.'],
  ['Indulgence', 'The remission, through the Church, of the temporal punishment due to sins that have already been forgiven.'],
  ['Infallibility', 'The gift of the Holy Spirit that preserves the Church, the pope, and the bishops in union with him from error when they definitively teach on faith and morals.'],
  ['Intercession', 'Praying on behalf of others. We ask the saints to intercede for us, as we ask fellow Christians on earth to pray for us.'],
  ['Laity', 'All the faithful who are not ordained or in religious life, called to make Christ present in the world through family, work, and society.'],
  ['Lectionary', 'The book containing the Scripture readings for Mass, arranged in a three-year cycle for Sundays and a two-year cycle for weekdays.'],
  ['Lent', 'The forty days of prayer, fasting, and almsgiving that prepare for Easter, beginning on Ash Wednesday.'],
  ['Litany', 'A prayer made of a series of invocations and responses, such as the Litany of the Saints.'],
  ['Liturgy', 'The public worship of the Church, above all the Mass, the sacraments, and the Liturgy of the Hours.'],
  ['Liturgy of the Hours', 'The daily prayer of the Church, made up of psalms, readings, and prayers at set hours of the day. Clergy and religious pray it daily, and laypeople are encouraged to join them.'],
  ['Magisterium', 'The teaching authority of the Church, exercised by the pope and the bishops in communion with him.'],
  ['Marriage', 'The sacrament in which a baptized man and woman give themselves to each other for life, as a sign of Christ’s love for the Church.'],
  ['Martyr', 'A person who is killed for their faith in Christ. The word means “witness.”'],
  ['Mass', 'The central act of Catholic worship, in which the sacrifice of Christ is made present and His Body and Blood are received in Communion.'],
  ['Monstrance', 'A vessel, often shaped like a sunburst, used to display the Blessed Sacrament for adoration.'],
  ['Mortal Sin', 'A grave sin committed with full knowledge and deliberate consent, which destroys charity in the heart and must be confessed.'],
  ['Novena', 'Nine days of prayer for a particular intention, modeled on the nine days the apostles and Mary prayed between the Ascension and Pentecost.'],
  ['Original Sin', 'The fallen state into which every human being is born as a result of the sin of Adam and Eve, taken away by Baptism.'],
  ['Parish', 'A community of the faithful within a diocese, entrusted to a pastor.'],
  ['Paschal Mystery', 'Christ’s saving work, accomplished through His Passion, death, Resurrection, and Ascension.'],
  ['Pentecost', 'The descent of the Holy Spirit on the apostles and Mary fifty days after Easter, often called the birthday of the Church.'],
  ['Pope', 'The bishop of Rome, successor of St. Peter, and visible head of the Catholic Church on earth.'],
  ['Purgatory', 'The final purification after death of those who die in God’s friendship but still need to be made perfectly holy before entering heaven.'],
  ['Real Presence', 'The truth that Jesus Christ is truly, really, and substantially present in the Eucharist: Body, Blood, soul, and divinity.'],
  ['Relic', 'An object connected with a saint, such as part of their body or something they used, honored as a reminder of their holiness.'],
  ['Rite', 'A liturgical tradition within the Church, such as the Roman Rite or the Byzantine Rite. There are twenty-four Churches in full communion with Rome.'],
  ['OCIA', 'The Order of Christian Initiation of Adults (formerly RCIA), the process by which adults are prepared to become Catholic.'],
  ['Rosary', 'A prayer on beads in which we meditate on the mysteries of the life of Christ and Mary while praying Hail Marys, Our Fathers, and Glory Bes.'],
  ['Sacrament', 'A visible sign, instituted by Christ, that gives grace. There are seven: Baptism, Confirmation, Eucharist, Penance, Anointing of the Sick, Holy Orders, and Matrimony.'],
  ['Sacramental', 'A sacred sign instituted by the Church, such as holy water, a blessing, or a rosary, that prepares us to receive grace.'],
  ['Sanctuary', 'The area of a church around the altar, where the priest and ministers carry out the liturgy.'],
  ['Scapular', 'Two small pieces of cloth worn over the shoulders as a sign of devotion and consecration, especially to Our Lady of Mount Carmel.'],
  ['Tabernacle', 'The locked box, usually near the altar, in which the Blessed Sacrament is reserved. A burning lamp beside it shows that Christ is present.'],
  ['Theological Virtues', 'Faith, hope, and charity: virtues given by God that unite us directly to Him.'],
  ['Tradition', 'Sacred Tradition is the living transmission of the Gospel handed down from the apostles, which, together with Scripture, forms one deposit of faith.'],
  ['Transubstantiation', 'The change of the whole substance of bread and wine into the Body and Blood of Christ at the Consecration, while their appearances remain.'],
  ['Trinity', 'The central mystery of the Christian faith: one God in three divine Persons, the Father, the Son, and the Holy Spirit.'],
  ['Venial Sin', 'A less serious sin that weakens but does not destroy charity in the soul.'],
  ['Vestments', 'The liturgical garments worn by clergy, such as the alb, stole, and chasuble, whose colors follow the liturgical season.'],
  ['Viaticum', 'Holy Communion given to a dying person, from the Latin for “provision for the journey.”'],
  ['Vocation', 'God’s call to each person: to holiness, and to a particular state of life such as marriage, priesthood, or consecrated life.'],
  ['Traditional Latin Mass', 'The Mass celebrated in Latin from the Roman Missal of 1962, the last edition before the reforms after Vatican II. Also called the Tridentine Mass, the Extraordinary Form, or the Vetus Ordo.'],
  ['Passiontide', 'In the traditional calendar, the last two weeks of Lent, from Passion Sunday through Holy Saturday, when the crosses and images in the church are veiled.'],
  ['Octave', 'The eight days of celebration that follow a great feast, ending on its octave day. Since 1955, only Christmas, Easter, and Pentecost have octaves in the Roman calendar.'],
  ['Cross bottony', 'A cross whose arms each end in three round lobes, like a trefoil. It marks the Traditional Latin edition of Sanctify.'],
  ['Novus Ordo', 'Latin for “new order”: an informal name for the Mass of the Roman Missal of Pope Paul VI (1970), the form of the Mass celebrated in most parishes today.'],
  ['Vulgate', 'St. Jerome’s Latin translation of the Bible, made in the late 4th century, the standard Bible of the Western Church for centuries.'],
  ['Acedia', 'Spiritual sloth: a listless boredom with prayer and the things of God, counted among the capital sins. The desert fathers called it the “noonday demon.”'],
  ['Alb', 'The long white vestment worn by priests, deacons, and servers at the liturgy, recalling the white garment of Baptism.'],
  ['Beatitudes', 'The eight blessings with which Jesus began the Sermon on the Mount (Matthew 5:3–10), beginning “Blessed are the poor in spirit.”'],
  ['Capital sins', 'The seven sins from which others spring: pride, greed, envy, wrath, lust, gluttony, and sloth. Often called the seven deadly sins.'],
  ['Chasuble', 'The outer vestment the priest wears to celebrate Mass, in the color of the day.'],
  ['Cope', 'A long cape worn by clergy for processions, Benediction, and other solemn rites outside Mass.'],
  ['Corporal', 'The square white linen cloth spread on the altar, on which the Host and chalice are placed.'],
  ['Dalmatic', 'The outer vestment of a deacon, a tunic with wide sleeves.'],
  ['Diskos', 'In the Byzantine Liturgy, the paten on a foot that holds the Lamb, the bread to be consecrated.'],
  ['Ektenia', 'A litany of the Byzantine services, led by the deacon, to which the people answer “Lord, have mercy” or “Grant this, O Lord.”'],
  ['Filioque', 'Latin for “and the Son”: the words added in the West to the Nicene Creed, saying that the Holy Spirit proceeds from the Father and the Son. A long point of discussion between East and West. Eastern Catholics usually pray the Creed without it.'],
  ['Holy day of obligation', 'A feast on which Catholics are bound, as on Sunday, to attend Mass and rest from unnecessary work.'],
  ['Lunette', 'The small glass holder that keeps the Host upright in the monstrance.'],
  ['Mitre', 'The tall, pointed liturgical hat worn by bishops and some abbots.'],
  ['Narthex', 'The entrance hall of a church, between the doors and the nave.'],
  ['Nave', 'The main body of a church, where the people gather. The name comes from the Latin for “ship.”'],
  ['Pallium', 'A band of white wool marked with black crosses, worn by the pope and by metropolitan archbishops as a sign of their office and of unity with the pope.'],
  ['Paten', 'The plate, usually of gold or silver, that holds the Host at Mass.'],
  ['Precepts of the Church', 'The least the Church asks of every Catholic: Mass on Sundays and holy days, yearly Confession, Communion in the Easter season, fasting and abstinence, and supporting the Church.'],
  ['Pyx', 'A small round case for carrying the Eucharist to the sick.'],
  ['Sanctuary lamp', 'The lamp or candle that burns day and night near the tabernacle, showing that Christ is present in the Blessed Sacrament.'],
  ['Sedevacantism', 'The view that the Chair of Peter has been empty since the death of Pius XII (or another recent pope), so that later popes are not true popes. The Church rejects it.'],
  ['Stole', 'The long band of cloth that is the sign of ordained ministry, worn by bishops, priests, and deacons.'],
  ['Thurible', 'The censer: a metal vessel hung on chains, in which incense is burned.'],
  ['Triodion', 'The Byzantine service book, and season, of the ten weeks before Pascha, from the Sunday of the Publican and the Pharisee through Holy Saturday.'],
  ['Works of mercy', 'Acts of charity for our neighbor’s bodily needs (the seven corporal works) and spiritual needs (the seven spiritual works).']
].sort((a, b) => a[0].localeCompare(b[0]));
let glossaryQuery = '';

function renderGlossary(){
  const q = glossaryQuery.trim().toLowerCase();
  const terms = GLOSSARY.filter(([t, d]) => !q || t.toLowerCase().includes(q) || d.toLowerCase().includes(q));
  const letters = [...new Set(GLOSSARY.map(([t]) => t[0].toUpperCase()))];
  const groups = {};
  terms.forEach(([t, d]) => (groups[t[0].toUpperCase()] = groups[t[0].toUpperCase()] || []).push([t, d]));
  entryListEl.innerHTML = `
    <div class="glossary">
      <div class="glossary-tools">
        <div class="sf-patron-search"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="M20 20l-4-4"/></svg>
          <input id="glossarySearch" type="search" placeholder="Look up a word…" aria-label="Search the glossary" value="${escapeHtml(glossaryQuery)}" autocomplete="off"></div>
        <nav class="glossary-letters" aria-label="Jump to a letter">${letters.map(l => `<a href="#gl-${l}" class="${groups[l] ? '' : 'off'}">${l}</a>`).join('')}</nav>
      </div>
      <p class="view-count">${plural(terms.length, 'term', 'terms')}</p>
      ${terms.length ? Object.keys(groups).map(l => `
        <section class="glossary-group" id="gl-${l}">
          <h3 class="glossary-letter">${l}</h3>
          <dl>${groups[l].map(([t, d]) => `<div class="glossary-item"><dt>${escapeHtml(t)}</dt><dd>${escapeHtml(d)}</dd></div>`).join('')}</dl>
        </section>`).join('') : '<div class="empty-state">No words match your search.</div>'}
    </div>`;
  const box = document.getElementById('glossarySearch');
  let t = null;
  box.addEventListener('input', () => {
    clearTimeout(t);
    t = setTimeout(() => {
      glossaryQuery = box.value;
      renderGlossary();
      const again = document.getElementById('glossarySearch');
      again.focus({ preventScroll:true });
      again.setSelectionRange(again.value.length, again.value.length);
    }, 200);
  });
  entryListEl.querySelectorAll('.glossary-letters a').forEach(a => a.addEventListener('click', ev => {
    ev.preventDefault();
    const target = document.querySelector(a.getAttribute('href'));
    if(target) target.scrollIntoView({ behavior:'smooth', block:'start' });
  }));
}

