const pf = { month:'', day:'', name:'', work:new Set(), need:new Set(), inspire:new Set(), heritage:new Set(), era:new Set() };
const PF_KEY = 'sanctify.patronFinder';
let pfShown = 12, pfIndex = null;
try{
  const saved = JSON.parse(localStorage.getItem(PF_KEY)) || {};
  ['month', 'day', 'name'].forEach(k => { if(typeof saved[k] === 'string') pf[k] = saved[k]; });
  ['work', 'need', 'inspire', 'heritage', 'era'].forEach(k => { if(Array.isArray(saved[k])) pf[k] = new Set(saved[k]); });
}catch(e){}
function pfSave(){
  try{ localStorage.setItem(PF_KEY, JSON.stringify({ month:pf.month, day:pf.day, name:pf.name,
    ...Object.fromEntries(['work', 'need', 'inspire', 'heritage', 'era'].map(k => [k, [...pf[k]]])) })); }catch(e){}
}

const pfFold = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const pfRegexCache = {};
function pfRegex(words){
  return pfRegexCache[words] || (pfRegexCache[words] = new RegExp('(^|[^a-z])(' + pfFold(words).replace(/[.*+?^${}()[\]\\]/g, '\\$&').replace(/\\\|/g, '|') + ')'));
}
const PF_NAME_STOP = new Set(['of', 'the', 'de', 'del', 'della', 'da', 'di', 'dos', 'das', 'do', 'du', 'von', 'van', 'la', 'le', 'y', 'and', 'companions', 'man', 'god', 'martyrs', 'great', 'younger', 'elder']);
function pfNames(title){
  const core = pfFold(title).replace(/\(.*?\)/g, '').replace(/^(pope\s+)?(st\.|sts\.|ss\.|bl\.|ven\.|saint|blessed|the)\s+/, '');
  const names = [];
  core.split(/,|\band\b/).forEach(part => {
    for(const w of part.trim().replace(/^(st\.|bl\.)\s+/, '').split(/[\s’']+/)){
      if(!w || PF_NAME_STOP.has(w) || /^\d/.test(w)) break;
      if(w.length > 1 && !/^[ivx]+$/.test(w)) names.push(w.replace(/[^a-z-]/g, ''));
    }
  });
  return names;
}
function pfBuildIndex(){
  pfIndex = library.filter(e => e.category === 'saint').map(e => {
    const patron = e.patron || '';
    return { e, info:saintInfo(e.id), patron, phrases:patron.split(/\s*,\s*/).filter(Boolean),
             hay:pfFold(patron + ' | ' + (e.tags || []).join(' | ') + (EASTERN_SAINTS.has(e.id) ? ' | eastern' : '')), names:pfNames(e.title) };
  });
}
function pfNameSet(){
  const n = pfFold(pf.name).trim().split(/\s+/)[0];
  if(!n || n.length < 2) return null;
  const set = new Set([n]);
  PF_NAMES.forEach(g => { const list = g.split(' '); if(list.includes(n)) list.forEach(x => set.add(x)); });
  return set;
}
// The patronage phrase that matched, so the card can say "Patron of nurses" instead of a vague label
function pfWhy(x, words, fallback){
  const re = pfRegex(words);
  const phrase = x.phrases.find(p => re.test(pfFold(p)));
  if(!phrase) return fallback;
  const m = pageLang() === 'en' && phrase.match(/^protection (?:from|against) (.*)/i);
  return m ? 'Protects from ' + m[1] : patronOf(phrase);
}
const pfFlat = groups => groups.flatMap(g => g[1]);
const PF_WORK_ALL = pfFlat(PF_WORK), PF_NEED_ALL = pfFlat(PF_NEED);

function pfScore(x, nameSet){
  let score = 0, hits = 0;
  const why = [];
  const add = (pts, text) => { score += pts; hits++; if(text && !why.includes(text)) why.push(text); };
  if(pf.month && pf.day && (SAINT_FEASTS[`${pf.month}-${pf.day}`] || []).includes(x.e)) add(6, 'Feast day on your birthday');
  if(nameSet && x.names.some(n => nameSet.has(n))) add(5, 'Shares your name');
  PF_WORK_ALL.forEach(([k, label, words, roles]) => {
    if(!pf.work.has(k)) return;
    if(pfRegex(words).test(x.hay)) add(4, pfWhy(x, words, label));
    else if(roles){ const r = roles.split('|').find(r => x.info.roles.includes(r)); if(r) add(2, 'One of the ' + SAINT_ROLE_NAME[r].toLowerCase()); }
  });
  PF_NEED_ALL.forEach(([k, label, words]) => { if(pf.need.has(k) && pfRegex(words).test(x.hay)) add(4, pfWhy(x, words, label)); });
  PF_INSPIRE.forEach(([k, label, words, roles]) => {
    if(!pf.inspire.has(k)) return;
    if((k === 'eastern' && EASTERN_SAINTS.has(x.e.id)) || (roles && roles.split('|').some(r => x.info.roles.includes(r))) || (words && pfRegex(words).test(x.hay))) add(2.5, label);
  });
  PF_HERITAGE.forEach(([k, label, words]) => { if(pf.heritage.has(k) && pfRegex(words).test(x.hay)) add(3, pfWhy(x, words, label + ' heritage')); });
  return { score, hits, why };
}

const pfAsked = () => !!((pf.month && pf.day) || pfNameSet() || pf.work.size || pf.need.size || pf.inspire.size || pf.heritage.size);

function renderPatronFinder(){
  if(!pfIndex) pfBuildIndex();
  pfShown = 12;
  const months = MONTH_NAMES.map((m, i) => `<option value="${i + 1}"${String(i + 1) === pf.month ? ' selected' : ''}>${m}</option>`).join('');
  const days = Array.from({ length:31 }, (_, i) => `<option value="${i + 1}"${String(i + 1) === pf.day ? ' selected' : ''}>${i + 1}</option>`).join('');
  const chip = (q, k, label) => `<button type="button" class="patron-chip pf-chip${pf[q].has(k) ? ' active' : ''}" data-q="${q}" data-k="${k}" aria-pressed="${pf[q].has(k)}">${escapeHtml(label)}</button>`;
  const grouped = (q, groups) => groups.map(([name, items]) => `
        <div class="pf-group"><h4>${escapeHtml(name)}</h4><div class="pf-chips">${items.map(i => chip(q, i[0], i[1])).join('')}</div></div>`).join('');
  const flat = (q, items) => `<div class="pf-chips">${items.map(i => chip(q, i[0], i[1])).join('')}</div>`;
  const wide = window.matchMedia('(min-width: 901px)').matches;
  const section = (q, title, hint, body, open) => `
      <details class="pf-sec"${open && (wide || q === 'work' || pf[q].size) ? ' open' : ''} data-sec="${q}">
        <summary><span class="pf-sec-title">${title}</span><span class="pf-count" data-count="${q}"></span></summary>
        <p class="pf-hint">${hint}</p>${body}
      </details>`;
  entryListEl.innerHTML = `
    <div class="pf">
      <div class="pf-layout">
        <div class="pf-form">
          <section class="pf-sec pf-about">
            <div class="pf-sec-title">About you</div>
            <div class="pf-about-grid">
              <label class="pf-q"><span>Your birthday</span>
                <span class="pf-row"><select data-pf="month"><option value="">Month</option>${months}</select><select data-pf="day"><option value="">Day</option>${days}</select></span></label>
              <label class="pf-q"><span>Your first name</span>
                <input type="text" data-pf="name" autocomplete="given-name" maxlength="40" placeholder="Maria, John, Teresa…" value="${escapeHtml(pf.name)}"></label>
            </div>
          </section>
          ${section('work', 'Your work or calling', 'Choose everything that fits: your job, your studies, your role at home.', grouped('work', PF_WORK), true)}
          ${section('need', 'What you are praying for', 'Choose the needs on your heart, for yourself or for someone you love.', grouped('need', PF_NEED), true)}
          ${section('inspire', 'What you love in a saint', 'Which kinds of holiness draw you?', flat('inspire', PF_INSPIRE), true)}
          ${section('heritage', 'Your heritage', 'Saints from your homeland or your family’s.', flat('heritage', PF_HERITAGE), true)}
          ${section('era', 'When they lived', 'Leave blank for any time, or choose the eras that interest you.', flat('era', PF_ERA), true)}
          <button class="text-link pf-reset" data-act="reset">Clear all answers</button>
        </div>
        <aside class="pf-side" id="pfResults" aria-live="polite"></aside>
      </div>
      <button class="pf-jump" type="button" hidden></button>
      <p class="shop-note">Many people choose a Confirmation saint whose virtues they want to imitate. Read about a few, ask them for their prayers, and see which one becomes a friend.</p>
    </div>`;
  const root = entryListEl;
  root.querySelectorAll('select[data-pf]').forEach(s => s.addEventListener('change', () => { pf[s.dataset.pf] = s.value; pfChanged(); }));
  let t;
  root.querySelector('input[data-pf="name"]').addEventListener('input', ev => { pf.name = ev.target.value; clearTimeout(t); t = setTimeout(pfChanged, 180); });
  root.querySelectorAll('.pf-chip').forEach(b => b.addEventListener('click', () => {
    const set = pf[b.dataset.q], k = b.dataset.k;
    set.has(k) ? set.delete(k) : set.add(k);
    b.classList.toggle('active', set.has(k));
    b.setAttribute('aria-pressed', set.has(k));
    pfChanged();
  }));
  root.querySelector('[data-act="reset"]').addEventListener('click', () => {
    Object.assign(pf, { month:'', day:'', name:'' });
    ['work', 'need', 'inspire', 'heritage', 'era'].forEach(k => pf[k].clear());
    pfSave();
    renderPatronFinder();
  });
  const jump = root.querySelector('.pf-jump'), side = root.querySelector('#pfResults');
  jump.addEventListener('click', () => side.scrollIntoView({ behavior:'smooth', block:'start' }));
  // Show the button only while the results are still further down the page: once they're on screen or scrolled
  // past, it would sit over the page and the footer
  const place = () => {
    if(!side.isConnected){ window.removeEventListener('scroll', place); return; }
    jump.classList.toggle('away', side.getBoundingClientRect().top < window.innerHeight - 90);
  };
  window.addEventListener('scroll', place, { passive:true });
  place();
  renderPfResults();
}

function pfChanged(){
  pfShown = 12;
  pfSave();
  renderPfResults();
}

function renderPfResults(){
  const side = document.getElementById('pfResults');
  if(!side) return;
  ['work', 'need', 'inspire', 'heritage', 'era'].forEach(q => {
    const c = entryListEl.querySelector(`[data-count="${q}"]`);
    if(c) c.textContent = pf[q].size ? pf[q].size + ' chosen' : '';
  });
  const jump = entryListEl.querySelector('.pf-jump');
  if(!pfAsked()){
    side.innerHTML = `<div class="pf-side-head"><h3 class="pf-heading">Saints for you</h3></div>
      <p class="pf-empty">${pf.era.size ? 'Now choose something else, such as your work or a need, to see saints from those times.' : 'Choose a few answers and your saints will appear here.'}</p>`;
    if(jump) jump.hidden = true;
    return;
  }
  const nameSet = pfNameSet();
  const eras = pf.era.size ? new Set(PF_ERA.filter(x => pf.era.has(x[0])).flatMap(x => x[2].split(' '))) : null;
  const all = pfIndex.filter(x => !eras || eras.has(x.info.era)).map(x => ({ x, ...pfScore(x, nameSet) })).filter(r => r.score > 0)
    .sort((a, b) => b.score - a.score || b.hits - a.hits || a.x.e.title.localeCompare(b.x.e.title));
  const shown = all.slice(0, pfShown);
  side.innerHTML = `
    <div class="pf-side-head"><h3 class="pf-heading">Saints for you</h3>
      <span class="pf-total">${all.length ? `${all.length} ${all.length === 1 ? 'match' : 'matches'}` : ''}</span></div>
    ${all.length ? `<div class="pf-results">${shown.map(({ x, why, hits }) => `
      <button class="pf-card" data-open="${x.e.id}">
        <span class="saint-portrait" data-sid="${x.e.id}">${portraitPlaceholder(x.e.title)}</span>
        <span class="pf-card-body">
          <span class="pf-card-title">${escapeHtml(x.e.title)}</span>
          <span class="g-meta">${escapeHtml(feastLabel(x.e))}</span>
          <span class="pf-why">${why.slice(0, 5).map(w => `<span class="patron-tag">${escapeHtml(w)}</span>`).join('')}${why.length > 5 ? `<span class="patron-tag">+${why.length - 5} more</span>` : ''}</span>
        </span>
      </button>`).join('')}</div>
    ${all.length > pfShown ? `<button class="btn quiet pf-more" type="button">Show ${Math.min(12, all.length - pfShown)} more</button>` : ''}`
    : '<p class="pf-empty">No saints match those answers yet. Try choosing a few different ones, or widen the eras.</p>'}`;
  side.querySelectorAll('[data-open]').forEach(b => b.addEventListener('click', () => openReadModal(b.dataset.open)));
  side.querySelectorAll('.pf-card .saint-portrait').forEach(observePortrait);
  const more = side.querySelector('.pf-more');
  if(more) more.addEventListener('click', () => { pfShown += 12; renderPfResults(); });
  if(jump){ jump.hidden = !all.length; jump.textContent = `See your saints · ${all.length}`; }
}

/* =========================================================
   THE BIBLE READER: the Douay-Rheims text, one small chapter file at a time
   ========================================================= */
// bible/<book>/<chapter>.txt holds Challoner's chapter summary on the first line (starting with * when the chapter
// has notes), then one verse per line. bible/<book>/<chapter>.notes.txt holds "<verse>\t<note>" lines.
const BIBLE_BOOKS = [   // [address, entry id, name, Douay-Rheims name, chapters], in the order of the Catholic canon
  ['genesis', 'bib1', 'Genesis', 'Genesis', 50], ['exodus', 'bib2', 'Exodus', 'Exodus', 40], ['leviticus', 'bib3', 'Leviticus', 'Leviticus', 27], ['numbers', 'bib4', 'Numbers', 'Numbers', 36],
  ['deuteronomy', 'bib5', 'Deuteronomy', 'Deuteronomy', 34], ['joshua', 'bib6', 'Joshua', 'Josue', 24], ['judges', 'bib7', 'Judges', 'Judges', 21], ['ruth', 'bib8', 'Ruth', 'Ruth', 4],
  ['1-samuel', 'bib9', '1 Samuel', '1 Kings', 31], ['2-samuel', 'bib10', '2 Samuel', '2 Kings', 24], ['1-kings', 'bib11', '1 Kings', '3 Kings', 22], ['2-kings', 'bib12', '2 Kings', '4 Kings', 25],
  ['1-chronicles', 'bib13', '1 Chronicles', '1 Paralipomenon', 29], ['2-chronicles', 'bib14', '2 Chronicles', '2 Paralipomenon', 36], ['ezra', 'bib15', 'Ezra', '1 Esdras', 10], ['nehemiah', 'bib16', 'Nehemiah', '2 Esdras', 13],
  ['tobit', 'bib17', 'Tobit', 'Tobias', 14], ['judith', 'bib18', 'Judith', 'Judith', 16], ['esther', 'bib19', 'Esther', 'Esther', 16], ['1-maccabees', 'bib20', '1 Maccabees', '1 Machabees', 16],
  ['2-maccabees', 'bib21', '2 Maccabees', '2 Machabees', 15], ['job', 'bib22', 'Job', 'Job', 42], ['psalms', 'bib23', 'Psalms', 'Psalms', 150], ['proverbs', 'bib24', 'Proverbs', 'Proverbs', 31],
  ['ecclesiastes', 'bib25', 'Ecclesiastes', 'Ecclesiastes', 12], ['song-of-songs', 'bib26', 'Song of Songs', 'Canticle of Canticles', 8], ['wisdom', 'bib27', 'Wisdom', 'Wisdom', 19], ['sirach', 'bib28', 'Sirach', 'Ecclesiasticus', 51],
  ['isaiah', 'bib29', 'Isaiah', 'Isaias', 66], ['jeremiah', 'bib30', 'Jeremiah', 'Jeremias', 52], ['lamentations', 'bib31', 'Lamentations', 'Lamentations', 5], ['baruch', 'bib32', 'Baruch', 'Baruch', 6],
  ['ezekiel', 'bib33', 'Ezekiel', 'Ezechiel', 48], ['daniel', 'bib34', 'Daniel', 'Daniel', 14], ['hosea', 'bib35', 'Hosea', 'Osee', 14], ['joel', 'bib36', 'Joel', 'Joel', 3],
  ['amos', 'bib37', 'Amos', 'Amos', 9], ['obadiah', 'bib38', 'Obadiah', 'Abdias', 1], ['jonah', 'bib39', 'Jonah', 'Jonas', 4], ['micah', 'bib40', 'Micah', 'Micheas', 7],
  ['nahum', 'bib41', 'Nahum', 'Nahum', 3], ['habakkuk', 'bib42', 'Habakkuk', 'Habacuc', 3], ['zephaniah', 'bib43', 'Zephaniah', 'Sophonias', 3], ['haggai', 'bib44', 'Haggai', 'Aggeus', 2],
  ['zechariah', 'bib45', 'Zechariah', 'Zacharias', 14], ['malachi', 'bib46', 'Malachi', 'Malachias', 4], ['matthew', 'bib47', 'Matthew', 'Matthew', 28], ['mark', 'bib48', 'Mark', 'Mark', 16],
  ['luke', 'bib49', 'Luke', 'Luke', 24], ['john', 'bib50', 'John', 'John', 21], ['acts', 'bib51', 'Acts of the Apostles', 'Acts', 28], ['romans', 'bib52', 'Romans', 'Romans', 16],
  ['1-corinthians', 'bib53', '1 Corinthians', '1 Corinthians', 16], ['2-corinthians', 'bib54', '2 Corinthians', '2 Corinthians', 13], ['galatians', 'bib55', 'Galatians', 'Galatians', 6], ['ephesians', 'bib56', 'Ephesians', 'Ephesians', 6],
  ['philippians', 'bib57', 'Philippians', 'Philippians', 4], ['colossians', 'bib58', 'Colossians', 'Colossians', 4], ['1-thessalonians', 'bib59', '1 Thessalonians', '1 Thessalonians', 5], ['2-thessalonians', 'bib60', '2 Thessalonians', '2 Thessalonians', 3],
  ['1-timothy', 'bib61', '1 Timothy', '1 Timothy', 6], ['2-timothy', 'bib62', '2 Timothy', '2 Timothy', 4], ['titus', 'bib63', 'Titus', 'Titus', 3], ['philemon', 'bib64', 'Philemon', 'Philemon', 1],
  ['hebrews', 'bib65', 'Hebrews', 'Hebrews', 13], ['james', 'bib66', 'James', 'James', 5], ['1-peter', 'bib67', '1 Peter', '1 Peter', 5], ['2-peter', 'bib68', '2 Peter', '2 Peter', 3],
  ['1-john', 'bib69', '1 John', '1 John', 5], ['2-john', 'bib70', '2 John', '2 John', 1], ['3-john', 'bib71', '3 John', '3 John', 1], ['jude', 'bib72', 'Jude', 'Jude', 1],
  ['revelation', 'bib73', 'Revelation', 'Apocalypse', 22]
];
const BIBLE_BY_SLUG = Object.fromEntries(BIBLE_BOOKS.map(b => [b[0], b]));
const BIBLE_ROUTE = /^library\/bible\/([a-z0-9-]+)(?:\/(\d+)(?:\/(\d+)(?:-(\d+))?)?)?$/;
let bibleRef = null;
const bibleMemo = new Map();

function bibleFetchText(path){
  if(!bibleMemo.has(path)){
    bibleMemo.set(path, fetch(path).then(r => { if(!r.ok) throw new Error(r.status); return r.text(); })
      .catch(err => { bibleMemo.delete(path); throw err; }));
  }
  return bibleMemo.get(path);
}
async function bibleChapter(slug, n){
  const lines = (await bibleFetchText(`bible/${slug}/${n}.txt`)).replace(/\r?\n$/, '').split(/\r?\n/);
  const head = lines[0] || '';
  return { hasNotes:head.startsWith('*'), summary:head.replace(/^\*/, ''), verses:lines.slice(1) };
}
async function bibleNotes(slug, n){
  const notes = {};
  (await bibleFetchText(`bible/${slug}/${n}.notes.txt`)).split(/\r?\n/).forEach(line => {
    const tab = line.indexOf('\t');
    if(tab > 0) (notes[line.slice(0, tab)] = notes[line.slice(0, tab)] || []).push(line.slice(tab + 1));
  });
  return notes;
}

// Psalms follow the Vulgate numbering; this gives the number used by most modern Bibles
function hebrewPsalm(n){
  if(n <= 8 || n >= 148) return String(n);
  if(n === 9) return '9–10';
  if(n <= 112 || (n >= 116 && n <= 145)) return String(n + 1);
  return { 113:'114–115', 114:'116:1–9', 115:'116:10–19', 146:'147:1–11', 147:'147:12–20' }[n];
}
const bibleChapterName = (book, n) => book[0] === 'psalms' ? `Psalm ${n}` : `${book[2]} ${n}`;

// "John 3:16", "jn 3 16-18", "1 Cor 13", "Psalm 22", "3 Kings 19", "Apocalypse 21"
const BIBLE_ABBR = { gen:'genesis', gn:'genesis', ex:'exodus', exod:'exodus', lev:'leviticus', lv:'leviticus', num:'numbers', nm:'numbers',
  deut:'deuteronomy', dt:'deuteronomy', josh:'joshua', jos:'joshua', judg:'judges', jgs:'judges', ru:'ruth', '1sam':'1-samuel', '1sm':'1-samuel',
  '2sam':'2-samuel', '2sm':'2-samuel', '1kgs':'1-kings', '2kgs':'2-kings', '1chr':'1-chronicles', '2chr':'2-chronicles', ezr:'ezra', neh:'nehemiah',
  tob:'tobit', tb:'tobit', jdt:'judith', est:'esther', '1mac':'1-maccabees', '1macc':'1-maccabees', '2mac':'2-maccabees', '2macc':'2-maccabees',
  jb:'job', ps:'psalms', pss:'psalms', psalm:'psalms', prov:'proverbs', prv:'proverbs', eccl:'ecclesiastes', qoh:'ecclesiastes', song:'song-of-songs',
  sg:'song-of-songs', sos:'song-of-songs', songofsolomon:'song-of-songs', wis:'wisdom', ws:'wisdom', sir:'sirach', ecclus:'sirach', is:'isaiah',
  isa:'isaiah', jer:'jeremiah', lam:'lamentations', bar:'baruch', ezek:'ezekiel', ez:'ezekiel', dan:'daniel', dn:'daniel', hos:'hosea', jl:'joel',
  am:'amos', ob:'obadiah', obad:'obadiah', jon:'jonah', mic:'micah', mi:'micah', na:'nahum', nah:'nahum', hab:'habakkuk', zeph:'zephaniah',
  zep:'zephaniah', hag:'haggai', hg:'haggai', zech:'zechariah', zec:'zechariah', mal:'malachi', mt:'matthew', matt:'matthew', mk:'mark', mrk:'mark',
  lk:'luke', jn:'john', jhn:'john', rom:'romans', rm:'romans', '1cor':'1-corinthians', '2cor':'2-corinthians', gal:'galatians', eph:'ephesians',
  phil:'philippians', col:'colossians', '1thess':'1-thessalonians', '1thes':'1-thessalonians', '2thess':'2-thessalonians', '2thes':'2-thessalonians',
  '1tim':'1-timothy', '2tim':'2-timothy', ti:'titus', tit:'titus', phlm:'philemon', philem:'philemon', heb:'hebrews', jas:'james', '1pet':'1-peter',
  '1pt':'1-peter', '2pet':'2-peter', '2pt':'2-peter', '1jn':'1-john', '2jn':'2-john', '3jn':'3-john', rev:'revelation', rv:'revelation',
  apoc:'revelation', revelations:'revelation' };
const bibleKey = s => s.toLowerCase().replace(/\./g, ' ').trim().replace(/^(first|i)\s+/, '1').replace(/^(second|ii)\s+/, '2')
  .replace(/^(third|iii)\s+/, '3').replace(/^(fourth|iv)\s+/, '4').replace(/^(the\s+)?(book|gospel|letter|epistle)\s+of\s+(st\s+|saint\s+)?/, '').replace(/[^a-z0-9]/g, '');
const BIBLE_NAMES = (() => {
  const m = {};
  BIBLE_BOOKS.forEach(b => { m[bibleKey(b[2])] = b[0]; });
  BIBLE_BOOKS.forEach(b => { const k = bibleKey(b[3]); if(!(k in m)) m[k] = b[0]; });   // Douay names such as 3 Kings and Osee
  Object.entries(BIBLE_ABBR).forEach(([k, v]) => { if(!(k in m)) m[k] = v; });
  return m;
})();
function parseBibleRef(text){
  const m = /^\s*(.+?)\s*(\d+)?(?:\s*[:., ]\s*(\d+)(?:\s*[-–]\s*(\d+))?)?\s*$/.exec(text || '');
  if(!m) return null;
  const key = bibleKey(m[1]);
  if(!key) return null;
  let slug = BIBLE_NAMES[key];
  if(!slug){
    const hit = BIBLE_BOOKS.find(b => bibleKey(b[2]).startsWith(key) || bibleKey(b[3]).startsWith(key));
    slug = hit && hit[0];
  }
  if(!slug) return null;
  const book = BIBLE_BY_SLUG[slug];
  const chapter = m[2] ? Math.min(Math.max(1, +m[2]), book[4]) : (book[4] === 1 ? 1 : 0);
  return { slug, chapter, verse:m[3] ? +m[3] : 0, verseEnd:m[4] ? +m[4] : 0 };
}
const bibleRoute = r => `library/bible/${r.slug}` + (r.chapter ? `/${r.chapter}` + (r.verse ? `/${r.verse}` + (r.verseEnd > r.verse ? `-${r.verseEnd}` : '') : '') : '');

const BIBLE_SIZES = [0.94, 1, 1.08, 1.17, 1.28, 1.4];
function bibleNeighbor(book, chapter, step){
  let i = BIBLE_BOOKS.indexOf(book), c = chapter + step;
  if(c < 1){ i--; if(i < 0) return null; c = BIBLE_BOOKS[i][4]; }
  else if(c > book[4]){ i++; if(i >= BIBLE_BOOKS.length) return null; c = 1; }
  return { book:BIBLE_BOOKS[i], chapter:c };
}

function renderBibleReader(){
  const ref = bibleRef || {};
  const book = BIBLE_BY_SLUG[ref.slug];
  if(!book){ navigate('library/bible'); return; }
  const entry = library.find(e => e.id === book[1]);
  const crumbs = document.getElementById('sectionEyebrow');
  if(!ref.chapter){ renderBibleBook(book, entry); return; }
  const n = ref.chapter;
  sectionTitleEl.textContent = bibleChapterName(book, n);
  sectionDescEl.textContent = book[0] === 'psalms' && hebrewPsalm(n) !== String(n)
    ? `Psalm ${hebrewPsalm(n)} in most modern Bibles. The Douay-Rheims follows the numbering of the Latin Vulgate.`
    : book[3] !== book[2] ? `Called ${book[3]} in the Douay-Rheims Bible.` : 'The Douay-Rheims Bible.';
  crumbs.insertAdjacentHTML('beforeend', `<span aria-hidden="true">›</span><button data-route="library/bible/${book[0]}">${escapeHtml(book[2])}</button>`);
  document.title = `${bibleChapterName(book, n)} — Sanctify`;
  store.set('bible.last', { slug:book[0], chapter:n });
  markRead('read.bible', book[0] + '/' + n);

  const prev = bibleNeighbor(book, n, -1), next = bibleNeighbor(book, n, 1);
  const size = store.get('bible.size', 2), notesOn = !!store.get('bible.notes', false);
  const navBtn = (to, dir) => to
    ? `<button class="br-step br-${dir}" data-route="library/bible/${to.book[0]}/${to.chapter}">${dir === 'prev' ? '‹ ' : ''}<span>${escapeHtml(bibleChapterName(to.book, to.chapter))}</span>${dir === 'next' ? ' ›' : ''}</button>`
    : '<span></span>';
  entryListEl.innerHTML = `
    <div class="br" style="--br-size:${BIBLE_SIZES[size] || 1.08}">
      <div class="br-tools">
        <div class="br-pick">
          <button class="br-arrow" ${prev ? `data-route="library/bible/${prev.book[0]}/${prev.chapter}"` : 'disabled'} aria-label="Previous chapter">‹</button>
          <select class="br-book" aria-label="Book">${BIBLE_BOOKS.map(b => `<option value="${b[0]}"${b === book ? ' selected' : ''}>${escapeHtml(b[2])}</option>`).join('')}</select>
          <select class="br-chap" aria-label="Chapter">${Array.from({ length:book[4] }, (_, i) => `<option value="${i + 1}"${i + 1 === n ? ' selected' : ''}>${i + 1}</option>`).join('')}</select>
          <button class="br-arrow" ${next ? `data-route="library/bible/${next.book[0]}/${next.chapter}"` : 'disabled'} aria-label="Next chapter">›</button>
        </div>
        <div class="br-opts">
          <button class="br-opt" data-size="-1" aria-label="Smaller text">A−</button>
          <button class="br-opt" data-size="1" aria-label="Larger text">A+</button>
          <button class="br-opt br-notes-btn" aria-pressed="${notesOn}" title="Bishop Challoner’s notes">Notes</button>
        </div>
      </div>
      <article class="br-page">
        <p class="br-summary"></p>
        <div class="br-text" aria-live="polite"><p class="br-loading">Opening ${escapeHtml(bibleChapterName(book, n))}…</p></div>
      </article>
      <nav class="br-foot">${navBtn(prev, 'prev')}${navBtn(next, 'next')}</nav>
      <p class="br-credit">Douay-Rheims Bible, Challoner revision (1749–1752), in the public domain.</p>
      <div class="br-copybar" hidden><span class="br-copyref"></span><button class="btn quiet" data-copy="text">Copy verses</button><button class="btn quiet" data-copy="link">Copy link</button><button class="br-x" aria-label="Clear selection">×</button></div>
    </div>`;
  const root = entryListEl.querySelector('.br');
  root.querySelector('.br-book').addEventListener('change', ev => navigate(`library/bible/${ev.target.value}/1`));
  root.querySelector('.br-chap').addEventListener('change', ev => navigate(`library/bible/${book[0]}/${ev.target.value}`));
  root.querySelectorAll('[data-size]').forEach(b => b.addEventListener('click', () => {
    const s = Math.max(0, Math.min(BIBLE_SIZES.length - 1, store.get('bible.size', 2) + Number(b.dataset.size)));
    store.set('bible.size', s);
    root.style.setProperty('--br-size', BIBLE_SIZES[s]);
  }));

  const textEl = root.querySelector('.br-text');
  const selected = new Set();
  const copybar = root.querySelector('.br-copybar');
  const rangeLabel = () => {
    const v = [...selected].sort((a, b) => a - b), parts = [];
    for(let i = 0; i < v.length; i++){
      let j = i;
      while(j + 1 < v.length && v[j + 1] === v[j] + 1) j++;
      parts.push(j > i ? `${v[i]}–${v[j]}` : String(v[i]));
      i = j;
    }
    return `${bibleChapterName(book, n)}:${parts.join(', ')}`;
  };
  const updateBar = () => {
    copybar.hidden = !selected.size;
    if(selected.size) copybar.querySelector('.br-copyref').textContent = rangeLabel();
  };
  textEl.addEventListener('click', ev => {
    const v = ev.target.closest('.br-v');
    if(!v || ev.target.closest('a')) return;
    const num = Number(v.dataset.v);
    selected.has(num) ? selected.delete(num) : selected.add(num);
    v.classList.toggle('sel', selected.has(num));
    updateBar();
  });
  copybar.querySelector('.br-x').addEventListener('click', () => { selected.clear(); textEl.querySelectorAll('.sel').forEach(x => x.classList.remove('sel')); updateBar(); });
  copybar.querySelectorAll('[data-copy]').forEach(b => b.addEventListener('click', async () => {
    const v = [...selected].sort((a, b) => a - b);
    const lo = v[0], hi = v[v.length - 1];
    const text = b.dataset.copy === 'link'
      ? location.origin + location.pathname + '#/' + bibleRoute({ slug:book[0], chapter:n, verse:lo, verseEnd:hi })
      : v.map(x => textEl.querySelector(`.br-v[data-v="${x}"] .br-vt`).textContent).join(' ') + ` (${rangeLabel()}, Douay-Rheims)`;
    try{ await navigator.clipboard.writeText(text); b.textContent = 'Copied'; }catch(e){ b.textContent = 'Could not copy'; }
    setTimeout(() => { b.textContent = b.dataset.copy === 'link' ? 'Copy link' : 'Copy verses'; }, 1600);
  }));

  const notesBtn = root.querySelector('.br-notes-btn');
  let chapterData = null;
  const showNotes = async () => {
    textEl.querySelectorAll('.br-note').forEach(x => x.remove());
    if(!store.get('bible.notes', false) || !chapterData || !chapterData.hasNotes) return;
    try{
      const notes = await bibleNotes(book[0], n);
      if(currentRoute !== 'library/bible/read' || bibleRef.slug !== book[0] || bibleRef.chapter !== n) return;
      Object.entries(notes).forEach(([v, list]) => {
        const after = textEl.querySelector(`.br-v[data-v="${v}"]`);
        if(!after) return;
        after.insertAdjacentHTML('afterend', list.map(t => {
          const m = /^(.{1,120}?)\.\.\.\.\s*(.*)$/.exec(t);
          return `<aside class="br-note">${m ? `<b>${escapeHtml(m[1].replace(/[\s,;:]*$/, '').replace(/([A-Za-z0-9’'"])$/, '$1.'))}</b> ${escapeHtml(m[2])}` : escapeHtml(t)}</aside>`;
        }).join(''));
      });
    }catch(e){}
  };
  notesBtn.addEventListener('click', () => {
    const on = !store.get('bible.notes', false);
    store.set('bible.notes', on);
    notesBtn.setAttribute('aria-pressed', on);
    showNotes();
  });

  bibleChapter(book[0], n).then(data => {
    if(currentRoute !== 'library/bible/read' || bibleRef.slug !== book[0] || bibleRef.chapter !== n) return;
    chapterData = data;
    root.querySelector('.br-summary').textContent = data.summary;
    notesBtn.hidden = !data.hasNotes;
    textEl.innerHTML = data.verses.map((t, i) => t ? `<p class="br-v" id="v${i + 1}" data-v="${i + 1}"><sup>${i + 1}</sup><span class="br-vt">${escapeHtml(t)}</span></p>` : '').join('');
    if(ref.verse){
      const hi = Math.max(ref.verse, ref.verseEnd || 0);
      for(let v = ref.verse; v <= hi; v++){ const el = textEl.querySelector(`.br-v[data-v="${v}"]`); if(el) el.classList.add('hl'); }
      const first = textEl.querySelector(`.br-v[data-v="${ref.verse}"]`);
      if(first) requestAnimationFrame(() => first.scrollIntoView({ block:'center' }));
    }
    showNotes();
  }).catch(() => {
    textEl.innerHTML = `<p class="br-loading">This chapter could not be loaded. Check your connection and <button class="text-link" data-route="${bibleRoute(ref)}">try again</button>.</p>`;
  });
}

function renderBibleBook(book, entry){
  sectionTitleEl.textContent = book[2];
  sectionDescEl.textContent = book[3] !== book[2] ? `Called ${book[3]} in the Douay-Rheims Bible.` : (entry ? entry.author.replace(/,\s*/, ' · ') : '');
  document.title = `${book[2]} — Sanctify`;
  entryListEl.innerHTML = `
    <div class="bb">
      ${entry ? `<p class="bb-intro">${escapeHtml(entry.content)}</p>` : ''}
      <button class="btn bb-start" data-route="library/bible/${book[0]}/1">Begin reading ${escapeHtml(book[0] === 'psalms' ? 'the Psalms' : book[2])} →</button>
      <h3 class="bb-heading">${book[0] === 'psalms' ? 'Psalms' : 'Chapters'}</h3>
      <div class="bb-chapters">${Array.from({ length:book[4] }, (_, i) => `<button class="bb-ch" data-route="library/bible/${book[0]}/${i + 1}">${i + 1}</button>`).join('')}</div>
      ${book[0] === 'psalms' ? '<p class="shop-note">The Psalms follow the numbering of the Latin Vulgate, usually one lower than in modern Bibles from Psalm 10 to 147. Each psalm shows its modern number too.</p>' : ''}
    </div>`;
}

// Arrow keys turn the page
document.addEventListener('keydown', ev => {
  if(currentRoute !== 'library/bible/read' || !bibleRef || !bibleRef.chapter || ev.altKey || ev.ctrlKey || ev.metaKey) return;
  if((ev.target.closest && ev.target.closest('input, select, textarea, [contenteditable]')) || readOverlay.classList.contains('open')) return;
  if(ev.key !== 'ArrowLeft' && ev.key !== 'ArrowRight') return;
  const to = bibleNeighbor(BIBLE_BY_SLUG[bibleRef.slug], bibleRef.chapter, ev.key === 'ArrowLeft' ? -1 : 1);
  if(to) navigate(`library/bible/${to.book[0]}/${to.chapter}`);
});

