  triodion:{ name:'Pre-Lenten Sundays', color:'var(--purple)', colorName:'dark', blurb:'The weeks of the Triodion that prepare for Great Lent, from the Sunday of the Publican and the Pharisee to Forgiveness Sunday.' },
  greatlent:{ name:'Great Lent', color:'var(--purple)', colorName:'purple or dark', blurb:'Forty days of fasting, prayer, and almsgiving, beginning on Clean Monday.' },
