function easternSeason(d){
  const y = d.getFullYear(), m = d.getMonth() + 1, day = d.getDate();
  const t = new Date(y, d.getMonth(), day).getTime();
  const P = easterDate(y);
  const between = (a, b) => t >= a.getTime() && t <= b.getTime();
  let key = 'ordinary';
  if((m === 11 && day >= 15) || (m === 12 && day <= 24)) key = 'nativityfast';
  else if((m === 12 && day >= 25) || (m === 1 && day <= 14)) key = 'nativity';
  else if(between(addDays(P, -70), addDays(P, -49))) key = 'triodion';
  else if(between(addDays(P, -48), addDays(P, -9))) key = 'greatlent';
  else if(between(addDays(P, -8), addDays(P, -1))) key = 'holyweek';
  else if(between(P, addDays(P, 49))) key = 'pascha';
  else if(between(addDays(P, 57), new Date(y, 5, 28))) key = 'apostlesfast';
  else if(m === 8 && day <= 14) key = 'dormitionfast';
  return { key, ...EAST_SEASON_INFO[key] };
}
