function isEasternSaint(s){
  const info = SAINT_INFO[s.id];
  return EASTERN_SAINTS.has(s.id) || !info || info.year === null || info.year < 1054;
}
function easternObservancesFor(d){
  const m = d.getMonth() + 1, day = d.getDate();
  const list = EAST_FIXED.filter(e => e.month === m && e.day === day).map(e => ({ ...e }));
  easternMoveable(d.getFullYear()).forEach(e => { if(sameDay(e.date, d)) list.push({ ...e }); });
  (SAINT_FEASTS[m + '-' + day] || []).filter(isEasternSaint).forEach(s => {
    const core = saintCore(s.title).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const re = new RegExp('(^|[^a-z])' + core + '([^a-z]|$)', 'i');
    const hit = list.find(o => o.type !== 'Saint' && re.test(o.name));
    if(hit) (hit.saints = hit.saints || []).push(s.id);
    else list.push({ name:s.title, type:'Saint', note:excerptOf(s.content, 160), saints:[s.id] });
  });
  return list.sort((a, b) => (CAL_TYPE_RANK[a.type] ?? 9) - (CAL_TYPE_RANK[b.type] ?? 9));
}
function easternDayNotes(d, obs){
  const P = easterDate(d.getFullYear());
  const season = easternSeason(d).key;
  const notes = [];
  if(obs.some(o => /strict fast/i.test(o.note || ''))) notes.push('A day of strict fasting.');
  else if(season === 'greatlent' || season === 'holyweek') notes.push('A day of the Great Fast: traditionally, abstain from meat and dairy as you are able and as your Church directs.');
  else if((d.getDay() === 3 || d.getDay() === 5) && season !== 'pascha' && season !== 'nativity') notes.push('Wednesdays and Fridays are traditional days of fasting.');
  if(d.getDay() === 0) notes.push('The Lord’s Day: Catholics are bound to take part in the Divine Liturgy.');
  if(sameDay(d, P) || sameDay(d, addDays(P, -2))) notes.push('Some Eastern Catholic Churches keep Pascha on the Julian date with the Orthodox; check with your parish.');
  return notes;
}
