/* ---------- The Divine Liturgy explained ---------- */
POSTURE_ICONS.bow = '<circle cx="15" cy="5.5" r="2.2"/><path d="M13.5 8 8 12.5l3 1.5M8 12.5V21M8 21h5"/>';
