const FAMOUS_KINDS = [['all', 'All icons'], ['christ', 'Christ'], ['mary', 'The Mother of God'], ['feast', 'Feasts'], ['saints', 'Saints & others']];
let famousKind = 'all';
let famousOpen = null;

function renderFamousIcons(){
  entryListEl.innerHTML = '';
  const wrap = document.createElement('div');
  wrap.className = 'famous-icons';
  if(famousOpen){
    const ic = FAMOUS_ICONS.find(x => x.key === famousOpen);
    const img = FAMOUS_IMG[ic.key];
    wrap.innerHTML = `
      <button class="text-link fi-back" type="button">← All famous icons</button>
      <article class="fi-detail">
        <figure class="fi-figure">${img ? `<img src="${escapeHtml(img.img)}" alt="${escapeHtml(ic.title)}" decoding="async"><figcaption><a href="${escapeHtml(img.page)}" target="_blank" rel="noopener">${img.credit ? `Photo: ${escapeHtml(img.credit)}, via` : 'Image via'} Wikimedia Commons ↗</a></figcaption>` : ''}</figure>
        <div class="fi-body">
          <h2>${escapeHtml(ic.title)}</h2>
          <dl class="fi-facts"><div><dt>Date</dt><dd>${escapeHtml(ic.date)}</dd></div><div><dt>Where</dt><dd>${escapeHtml(ic.place)}</dd></div><div><dt>Made with</dt><dd>${escapeHtml(ic.medium)}</dd></div></dl>
          ${ic.text.split('\n\n').map(p => `<p>${escapeHtml(p)}</p>`).join('')}
          <h3>What to look for</h3>
          <ul class="fi-look">${ic.look.map(l => `<li>${escapeHtml(l)}</li>`).join('')}</ul>
        </div>
      </article>`;
    wrap.querySelector('.fi-back').addEventListener('click', () => { famousOpen = null; renderFamousIcons(); window.scrollTo({ top:0 }); });
  } else {
    const order = FAMOUS_KINDS.map(k => k[0]);
    const list = FAMOUS_ICONS.filter(ic => famousKind === 'all' || ic.kind === famousKind)
      .map((ic, i) => [ic, i]).sort((x, y) => order.indexOf(x[0].kind) - order.indexOf(y[0].kind) || x[1] - y[1]).map(x => x[0]);
    wrap.innerHTML = `
      <div class="patron-filters-row fi-kinds" role="group" aria-label="Kinds of icons">
        ${FAMOUS_KINDS.map(([k, n]) => `<button class="patron-chip${famousKind === k ? ' active' : ''}" data-kind="${k}" aria-pressed="${famousKind === k}">${n}</button>`).join('')}
      </div>
      <div class="fi-grid">${list.map(ic => {
        const img = FAMOUS_IMG[ic.key];
        return `<button class="fi-card" type="button" data-icon="${ic.key}">
          <span class="fi-thumb">${img ? `<img src="${escapeHtml(img.img)}" alt="" loading="lazy" decoding="async">` : ''}</span>
          <span class="fi-title">${escapeHtml(ic.title)}</span>
          <span class="fi-date">${escapeHtml(ic.date)}</span>
        </button>`;
      }).join('')}</div>
      <p class="fi-note">An icon is not simply a picture of a holy person but, as the Eastern Churches say, a window onto heaven: what Scripture says in words, the icon shows in color. See also <button class="text-link" data-open="t60">Holy Icons</button> in Theology.</p>`;
    wrap.querySelectorAll('[data-kind]').forEach(b => b.addEventListener('click', () => { famousKind = b.dataset.kind; renderFamousIcons(); }));
    wrap.querySelectorAll('[data-icon]').forEach(b => b.addEventListener('click', () => { famousOpen = b.dataset.icon; renderFamousIcons(); window.scrollTo({ top:0 }); }));
  }
  entryListEl.appendChild(wrap);
}

/* =========================================================
   THE EASTERN CATHOLIC CHURCHES
   ========================================================= */
const EASTERN_CHURCHES = [
  { trad:'Byzantine (Constantinopolitan) tradition', desc:'The tradition of Constantinople, with the Divine Liturgies of St. John Chrysostom and St. Basil the Great. Fourteen Eastern Catholic Churches follow it.', list:[
    ['Ukrainian Greek Catholic Church', 'Major Archbishop of Kyiv-Halych', 'Ukraine and a worldwide diaspora', 'Ukrainian, Church Slavonic', 'One of the largest Eastern Catholic Churches. It entered full communion with Rome at the Union of Brest (1596), survived as an underground Church under Soviet rule, and returned to public life in 1989.'],
    ['Ruthenian Greek Catholic Church', 'Eparchy of Mukachevo; Byzantine Catholic Metropolia of Pittsburgh (USA)', 'Ukraine (Transcarpathia), United States', 'Church Slavonic, English', 'Joined Rome at the Union of Uzhhorod (1646). Its American branch is known simply as the Byzantine Catholic Church.'],
    ['Melkite Greek Catholic Church', 'Patriarch of Antioch', 'Syria, Lebanon, Israel, Egypt, Jordan, the Americas', 'Arabic, Greek', 'Byzantine Christians of the Middle East in communion with Rome since 1724. "Melkite" comes from the Syriac word for "king," because they followed the emperor’s Council of Chalcedon.'],
    ['Romanian Greek Catholic Church', 'Major Archbishop of Făgăraș and Alba Iulia (Blaj)', 'Romania', 'Romanian', 'United with Rome around 1700 in Transylvania. Outlawed by the communists in 1948; its seven martyred bishops were beatified in 2019.'],
    ['Slovak Greek Catholic Church', 'Metropolitan of Prešov', 'Slovakia', 'Church Slavonic, Slovak', 'Suppressed by the communists in 1950 and restored in 1968. Its martyred bishops Pavol Gojdič and Vasil Hopko are beatified.'],
    ['Hungarian Greek Catholic Church', 'Metropolitan of Hajdúdorog', 'Hungary', 'Hungarian', 'Its great shrine is Máriapócs, where an icon of the Mother of God was seen weeping in 1696, 1715, and 1905.'],
    ['Greek Catholic Church of Croatia and Serbia', 'Eparchies of Križevci and Ruski Krstur', 'Croatia, Serbia', 'Church Slavonic, Croatian, Rusyn', 'Byzantine Catholics of the former Yugoslavia, including Rusyn communities in Serbia.'],
    ['Macedonian Greek Catholic Church', 'Eparchy of the Assumption in Strumica-Skopje', 'North Macedonia', 'Macedonian', 'A small Church that grew out of a nineteenth-century movement of Bulgarian and Macedonian Christians toward union with Rome.'],
    ['Bulgarian Greek Catholic Church', 'Eparchy of St. John XXIII in Sofia', 'Bulgaria', 'Bulgarian', 'Pope St. John XXIII served in Bulgaria as apostolic delegate from 1925 to 1934 and loved these faithful.'],
    ['Italo-Albanian Catholic Church', 'Eparchies of Lungro and Piana degli Albanesi; Abbey of Grottaferrata', 'Southern Italy and Sicily', 'Greek, Albanian, Italian', 'Descendants of Albanians who fled to Italy in the fifteenth century, together with the ancient Greek-rite abbey founded by St. Nilus. They were never separated from Rome.'],
    ['Greek Byzantine Catholic Church', 'Apostolic Exarchate in Greece', 'Greece, Turkey', 'Greek', 'A small community of Greek Catholics, mostly in Athens.'],
    ['Belarusian Greek Catholic Church', 'No bishop of its own at present', 'Belarus and the diaspora', 'Belarusian', 'Heir of the Union of Brest in Belarus, almost destroyed in the nineteenth and twentieth centuries and slowly rebuilding.'],
    ['Russian Greek Catholic Church', 'Two apostolic exarchates (Russia and Harbin), long without a bishop', 'Russia and the diaspora', 'Church Slavonic, Russian', 'Founded at the beginning of the twentieth century. Its first exarch, Bl. Leonid Feodorov, died a martyr for the faith.'],
    ['Albanian Greek Catholic Church', 'Apostolic Administration of Southern Albania', 'Albania', 'Albanian', 'A very small Church that survived the harsh atheist regime of communist Albania.']
  ]},
  { trad:'Antiochene (West Syriac) tradition', desc:'The tradition of ancient Antioch, using the Syriac language of the early Church and the Liturgy of St. James.', list:[
    ['Maronite Church', 'Patriarch of Antioch (Bkerke, Lebanon)', 'Lebanon, Syria, Cyprus, the Americas, Australia', 'Syriac, Arabic', 'Named after the hermit St. Maron (d. 410). The Maronites hold that they have always been in communion with Rome. Their saints include St. Charbel, St. Rafqa, and St. Nimatullah.'],
    ['Syriac Catholic Church', 'Patriarch of Antioch (Beirut)', 'Syria, Iraq, Lebanon', 'Syriac, Arabic', 'Syriac Christians who entered communion with Rome, with their patriarchate stable since 1783. Many were driven from their homes in Iraq and Syria in recent years.'],
    ['Syro-Malankara Catholic Church', 'Major Archbishop of Trivandrum', 'Kerala, India', 'Malayalam, Syriac', 'Formed in 1930 when Mar Ivanios and other bishops of the Malankara Church entered communion with Rome.']
  ]},
  { trad:'Chaldean (East Syriac) tradition', desc:'The tradition of the ancient Church of the East in Mesopotamia and Persia, which carried the Gospel as far as India and China.', list:[
    ['Chaldean Catholic Church', 'Patriarch of Babylon of the Chaldeans (Baghdad)', 'Iraq, Iran, Syria, and a large diaspora', 'Syriac (Aramaic), Arabic', 'Entered communion with Rome in 1553. It has suffered greatly from war and persecution in Iraq.'],
    ['Syro-Malabar Catholic Church', 'Major Archbishop of Ernakulam-Angamaly', 'Kerala, India, and the diaspora', 'Malayalam, Syriac', 'The St. Thomas Christians of India, who trace their faith to the apostle Thomas. One of the largest Eastern Catholic Churches, rich in vocations.']
  ]},
  { trad:'Armenian tradition', desc:'The tradition of Armenia, the first nation to adopt Christianity, around 301.', list:[
    ['Armenian Catholic Church', 'Patriarch of Cilicia (Beirut)', 'Lebanon, Syria, Armenia, and the diaspora', 'Classical Armenian', 'Its patriarchate was established in 1742. Its martyrs include St. Ignatius Maloyan, killed in the genocide of 1915.']
  ]},
  { trad:'Alexandrian tradition', desc:'The tradition of Alexandria, founded according to tradition by St. Mark the Evangelist.', list:[
    ['Coptic Catholic Church', 'Patriarch of Alexandria (Cairo)', 'Egypt', 'Coptic, Arabic', 'Its patriarchate was restored in 1895. It runs many schools and hospitals in Egypt.'],
    ['Ethiopian Catholic Church', 'Metropolitan Archbishop of Addis Ababa', 'Ethiopia', 'Ge’ez, Amharic', 'Its roots include the mission of St. Justin de Jacobis, who adopted the ancient Ge’ez liturgy in the nineteenth century.'],
    ['Eritrean Catholic Church', 'Metropolitan Archbishop of Asmara', 'Eritrea', 'Ge’ez, Tigrinya', 'Became a Church sui iuris in its own right in 2015.']
  ]}
];

function renderEasternChurches(){
  entryListEl.innerHTML = '';
  const wrap = document.createElement('div');
  wrap.className = 'ec-page';
  const total = EASTERN_CHURCHES.reduce((n, g) => n + g.list.length, 0);
  wrap.innerHTML = `
    <p class="ec-intro">The Catholic Church is a communion of ${total + 1} Churches: the Latin Church and ${total} Eastern Catholic Churches, each with its own liturgy, spirituality, and laws, all in full communion with the Bishop of Rome. Catholics may attend the liturgy of any of them and receive the sacraments there. <button class="text-link" data-open="t58">Read more</button></p>
    ${EASTERN_CHURCHES.map(g => `
      <section class="ec-group">
        <h3 class="list-heading">${escapeHtml(g.trad)} <span class="ec-count">${g.list.length}</span></h3>
        <p class="theology-group-desc">${escapeHtml(g.desc)}</p>
        <div class="ec-grid">${g.list.map(([name, head, where, lang, note]) => `
          <article class="ec-card">
            <h4>${escapeHtml(name)}</h4>
            <dl><div><dt>Head</dt><dd>${escapeHtml(head)}</dd></div><div><dt>Where</dt><dd>${escapeHtml(where)}</dd></div><div><dt>Liturgical languages</dt><dd>${escapeHtml(lang)}</dd></div></dl>
            <p>${escapeHtml(note)}</p>
          </article>`).join('')}</div>
      </section>`).join('')}`;
  entryListEl.appendChild(wrap);
}

