let orderGroup = 'all';

function renderOrders(){
  entryListEl.innerHTML = '';
  const wrap = document.createElement('div');
  wrap.className = 'orders-page';
  const groups = ORDER_GROUPS.filter(g => orderGroup === 'all' || g.key === orderGroup);
  wrap.innerHTML = `
    <div class="patron-filters-row" role="group" aria-label="Kinds of orders">
      <button class="patron-chip${orderGroup === 'all' ? ' active' : ''}" data-og="all">All orders</button>
      ${ORDER_GROUPS.map(g => `<button class="patron-chip${orderGroup === g.key ? ' active' : ''}" data-og="${g.key}">${escapeHtml(g.name)}</button>`).join('')}
    </div>
    ${groups.map(g => `
      <section class="ec-group">
        <h3 class="list-heading">${escapeHtml(g.name)} <span class="ec-count">${g.list.length}</span></h3>
        <p class="theology-group-desc">${escapeHtml(g.desc)}</p>
        <div class="ec-grid">${g.list.map(o => `
          <article class="ec-card order-card${g.key === 'military' ? ' military' : ''}">
            <div class="order-head">${ORDER_IMG[o.name] ? `<a class="order-img${/\.(svg|png|gif)$/i.test(ORDER_IMG[o.name][1]) ? ' contain' : ''}" href="https://commons.wikimedia.org/wiki/File:${encodeURIComponent(ORDER_IMG[o.name][1])}" target="_blank" rel="noopener" title="Image via Wikimedia Commons"><img src="${escapeHtml(ORDER_IMG[o.name][0])}" alt="" loading="lazy" decoding="async"></a>` : ''}<h4>${escapeHtml(o.name)}</h4></div>
            <dl><div><dt>Initials</dt><dd>${escapeHtml(o.abbr)}</dd></div><div><dt>Founded</dt><dd>${escapeHtml(o.founded)}</dd></div><div><dt>Founder</dt><dd>${escapeHtml(o.founder)}</dd></div></dl>
            <p>${escapeHtml(o.text)}</p>
            ${o.saints && o.saints !== '—' ? `<p class="order-saints"><strong>Saints:</strong> ${escapeHtml(o.saints)}</p>` : ''}
          </article>`).join('')}</div>
      </section>`).join('')}
    <p class="fi-note">See also <button class="text-link" data-route="history/timeline/crusades">the Crusades and the military orders</button> in Church History, and <button class="text-link" data-open="t76">Consecrated Life</button> in Theology.</p>`;
  wrap.querySelectorAll('[data-og]').forEach(b => b.addEventListener('click', () => { orderGroup = b.dataset.og; renderOrders(); }));
  entryListEl.appendChild(wrap);
}

