const LIBRARY_CATS = new Set(['prayer', 'saint', 'theology', 'history', 'book', 'bible', 'all']);

document.querySelectorAll('.navlink').forEach(btn => {
  const sec = SECTIONS[btn.dataset.cat];
  if(!sec) return;
  btn.style.setProperty('--cat-color', sec.color);
  btn.insertAdjacentHTML('afterbegin', `<span class="nl-icon">${navIcon(sec.icon)}</span>`);
});

updateAccountButton();

function setNavOpen(open){
  document.body.classList.toggle('nav-open', open);
  document.getElementById('navScrim').hidden = !open;
  document.getElementById('menuBtn').setAttribute('aria-expanded', String(open));
}
document.getElementById('menuBtn').addEventListener('click', () => setNavOpen(!document.body.classList.contains('nav-open')));
document.getElementById('navScrim').addEventListener('click', () => setNavOpen(false));
document.addEventListener('keydown', e => { if(e.key === 'Escape' && document.body.classList.contains('nav-open')) setNavOpen(false); });
document.getElementById('brandHome').addEventListener('click', () => goToSection('home'));

// The menu's sections fold open: the one you are in opens by itself, and any you open stay open
const SIDE_GROUPS = { home:['home', 'var(--wine)'], saints:['saint', 'var(--rose)'], pray:['prayer', 'var(--wine)'], history:['history', 'var(--gold)'], library:['book', 'var(--indigo)'], learn:['theology', 'var(--purple)'] };
// Pages whose address starts with something else but live in a section of the menu
const SIDE_GROUP_OF = { today:'home', mine:'home' };
document.querySelectorAll('nav.sidebar .nav-group').forEach(g => {
  const link = g.querySelector(':scope > .group-link'), ul = g.querySelector(':scope > ul');
  if(!link || !ul) return;
  const key = link.dataset.route, [icon, color] = SIDE_GROUPS[key] || ['all', 'var(--wine)'];
  const name = link.textContent.replace(/\s*›\s*$/, '').trim();
  link.textContent = name;
  link.classList.remove('group-label');
  link.style.setProperty('--cat-color', color);
  link.insertAdjacentHTML('afterbegin', `<span class="nl-icon" aria-hidden="true">${navIcon(icon)}</span>`);
  const row = document.createElement('div');
  row.className = 'group-row';
  link.replaceWith(row);
  row.appendChild(link);
  row.insertAdjacentHTML('beforeend', `<button class="group-toggle" type="button" aria-expanded="false" aria-label="Show the ${escapeHtml(name)} pages"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 6l6 6-6 6"/></svg></button>`);
  const body = document.createElement('div');
  body.className = 'group-body';
  ul.replaceWith(body);
  body.appendChild(ul);
  g.classList.add('collapsible');
  g.dataset.group = key;
  row.querySelector('.group-toggle').addEventListener('click', () => {
    const open = !g.classList.contains('open');
    setSideGroupOpen(g, open);
    const saved = store.get('side.open', {});
    saved[key] = open;
    store.set('side.open', saved);
  });
});
function setSideGroupOpen(g, open){
  g.classList.toggle('open', open);
  const t = g.querySelector('.group-toggle');
  if(t) t.setAttribute('aria-expanded', String(open));
  g.querySelectorAll('.group-body button.navlink').forEach(b => { b.tabIndex = open ? 0 : -1; });
}
function syncSideGroups(top){
  const saved = store.get('side.open', {});
  document.querySelectorAll('nav.sidebar .nav-group.collapsible').forEach(g => {
    const here = g.dataset.group === (SIDE_GROUP_OF[top] || top);
    g.querySelector('.group-link').classList.toggle('active', here);
    setSideGroupOpen(g, here || saved[g.dataset.group] === true);
  });
}

