// Older addresses keep working: they open the page at its new address
const ROUTE_ALIASES = {'account/saved':'mine', 'pray/generator':'mine', 'generator':'mine', 'badges':'account/badges', 'history/saints/patron-finder':'saints/patron-finder', 'history/saints':'saints/all', 'history/quotes':'saints/quotes', 'library/saints/patron-finder':'saints/patron-finder', 'library/saints':'saints/all', 'library/quotes':'saints/quotes', 'learn/icons':'history/icons', 'learn/history/popes':'history/popes', 'learn/history/apparitions':'history/timeline/apparitions', 'learn/history/crusades':'history/timeline/crusades', 'learn/history':'history/timeline', 'learn/orders':'history/orders', 'learn/eastern-churches':'history/eastern-churches', 'learn/plans':'library/plans', 'learn/resources':'library/resources', 'resources':'library/resources', 'church':'history', 'saints/icons':'history/icons', 'church/history/apparitions':'history/timeline/apparitions', 'church/history/crusades':'history/timeline/crusades', 'church/history':'history/timeline', 'church/popes':'history/popes', 'church/orders':'history/orders', 'church/eastern-churches':'history/eastern-churches' };
const CAT_ROUTE = {};
Object.entries(ROUTES).forEach(([route, r]) => { if(!(r.cat in CAT_ROUTE)) CAT_ROUTE[r.cat] = route; });
let currentRoute = 'home';   // the ROUTES key, e.g. 'community/post'
let currentPath = 'home';    // the full address, e.g. 'community/post/42'
const POST_ROUTE = /^community\/post\/(\d+)$/;
const PROFILE_ROUTE = /^community\/user\/([A-Za-z0-9_]{3,20})$/;
const WIKI_ROUTE = /^wiki\/(page|edit|history)\/([a-z0-9-]{1,80})$/;
const WIKI_REV_ROUTE = /^wiki\/revision\/(\d+)$/;
let wikiSlugNow = null, wikiRevNow = null;

function routeName(route){
  const r = ROUTES[route];
  return r.name || (SECTIONS[r.cat] && SECTIONS[r.cat].name) || route;
}

// Accepts #/pray/rosary, and older links like #saint or #rosary
function routeFromHash(){
  const h = decodeURIComponent(location.hash.replace(/^#\/?/, ''));
  if(ROUTES[h] || POST_ROUTE.test(h) || PROFILE_ROUTE.test(h) || WIKI_ROUTE.test(h) || WIKI_REV_ROUTE.test(h) || BIBLE_ROUTE.test(h) || BOOK_ROUTE.test(h) || CCC_ROUTE.test(h)) return h;
  if(ROUTE_ALIASES[h]) return h;   // applyRoute moves it to the new address
  if(CAT_ROUTE[h]) return CAT_ROUTE[h];
  return h ? NOT_FOUND : 'home';
}
// An address that isn't a page of the site opens the page-not-found page, which offers a search
const NOT_FOUND = '\u0000404';
function showNotFound(path){
  location.replace('404.html?from=' + encodeURIComponent(path || location.hash.replace(/^#\/?/, '')));
}

function applyRoute(path){
  if(path === NOT_FOUND){ showNotFound(); return; }
  stopSpeaking();
  if(ROUTE_ALIASES[path]){
    path = ROUTE_ALIASES[path];
    history.replaceState(null, '', location.pathname + '#/' + path);
  }
  const post = POST_ROUTE.exec(path);
  forumThreadId = post ? Number(post[1]) : null;
  const prof = PROFILE_ROUTE.exec(path);
  profileName = prof ? prof[1] : null;
  const bib = BIBLE_ROUTE.exec(path);
  bibleRef = bib ? { slug:bib[1], chapter:Number(bib[2]) || 0, verse:Number(bib[3]) || 0, verseEnd:Number(bib[4]) || 0 } : null;
  const bk = BOOK_ROUTE.exec(path);
  bookRef = bk ? { slug:bk[1], section:Number(bk[2]) || 0 } : null;
  const cc = CCC_ROUTE.exec(path);
  cccRef = cc ? parseCccInput(cc[1] + (cc[2] ? '-' + cc[2] : '')) : null;
  const wk = WIKI_ROUTE.exec(path), wr = WIKI_REV_ROUTE.exec(path);
  wikiSlugNow = wk ? wk[2] : null;
  wikiRevNow = wr ? Number(wr[1]) : null;
  let route = wk ? 'wiki/' + wk[1] : wr ? 'wiki/revision' : post ? 'community/post' : prof ? 'community/user' : bib ? 'library/bible/read' : bk ? 'library/books/read' : cc ? 'library/catechism' : path;
  if(!ROUTES[route]){ showNotFound(path); return; }
  const r = ROUTES[route];
  currentRoute = route;
  currentPath = path;
  activeCategory = r.cat;
  activeEra = 'all';
  prayerTopic = 'all';
  theologyGroup = r.group || 'all';
  historyMarianOnly = !!r.marian;
  historyCrusadesOnly = !!r.crusades;
  searchTerm = '';
  searchInput.value = '';
  syncSearchUI();
  setNavOpen(false);
  const top = route.split('/')[0];
  document.querySelectorAll('.topnav-link').forEach(b => b.classList.toggle('active', b.dataset.route === top));
  if(typeof syncSideGroups === 'function') syncSideGroups(top);
  document.querySelectorAll('.tab-link').forEach(b => { const on = b.dataset.route === top; b.classList.toggle('active', on); if(on) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  document.querySelectorAll('.top-action').forEach(b => b.classList.toggle('active', b.dataset.route === top || (b.dataset.route === 'account' && route === 'moderate')));
  document.querySelectorAll('.navlink[data-route]').forEach(b => b.classList.toggle('active',
    b.dataset.route === route || (route.startsWith(b.dataset.route + '/') && !document.querySelector(`.navlink[data-route="${route}"]`))));
  document.title = route === 'home' ? 'Sanctify — A Catholic Repository' : `${routeName(route)} — Sanctify`;
  window.scrollTo({ top:0 });
  render();
  startDropIn();
}

/* ---------- Page entrance: the page fades in as a whole, everything visible at once ---------- */
let dropUntil = 0;
function pageIn(el){
  if(!el) return;
  el.classList.remove('page-in');
  void el.offsetWidth;   // restart the animation
  el.classList.add('page-in');
}
function startDropIn(){
  if(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  if(document.documentElement.getAttribute('data-motion') === 'reduced') return;
  dropUntil = Date.now() + 2500;
  pageIn(document.getElementById('mainHead'));
  pageIn(entryListEl);
}
// A page that shows "Loading…" first fades in again when its content arrives
new MutationObserver(list => {
  if(Date.now() > dropUntil) return;
  if(list.some(m => [...m.removedNodes].some(n => n.nodeType === 1 && (n.matches('.forum-loading') || n.querySelector && n.querySelector(':scope > .forum-loading'))))) pageIn(entryListEl);
}).observe(entryListEl, { childList:true });
function navigate(route){
  const target = '#/' + route;
  // drop any ?q= search from the address once the visitor moves on to a page
  if(location.hash !== target || location.search) history.pushState(null, '', location.pathname + target);
  applyRoute(route);
}

const inPageAnchor = () => { const a = location.hash.slice(1); return !!a && !a.startsWith('/') && !/^read=/.test(a) && !!document.getElementById(a); };
window.addEventListener('popstate', () => { if(!/^#read=/.test(location.hash) && !inPageAnchor()) applyRoute(routeFromHash()); });
window.addEventListener('hashchange', () => {
  if(/^#read=/.test(location.hash)){ const id = decodeURIComponent(location.hash.slice(6)); if(library.some(e => e.id === id)) openReadModal(id); return; }
  if(inPageAnchor()) return;
  if(routeFromHash() !== currentPath) applyRoute(routeFromHash());
});
document.querySelector('.skip-link').addEventListener('click', ev => {
  ev.preventDefault();
  const main = document.getElementById('main');
  main.focus();
  main.scrollIntoView();
});

// Any element with data-route navigates there
document.addEventListener('click', e => {
  const el = e.target.closest('[data-route]');
  if(!el || (el.closest('.theme-menu') && !el.classList.contains('settings-menu-btn'))) return;
  e.preventDefault();
  readOverlay.classList.remove('open');
  navigate(el.dataset.route);
});

const searchInput = document.getElementById('searchInput');
function syncSearchUI(){ searchInput.closest('.searchbar').classList.toggle('has-text', !!searchInput.value); }
searchInput.addEventListener('input', () => { searchTerm = searchInput.value; syncSearchUI(); render(); });
document.getElementById('searchClear').addEventListener('click', () => {
  searchInput.value=''; searchTerm=''; syncSearchUI(); searchInput.focus(); render();
});

/* =========================================================
   READING MODAL
   ========================================================= */
const readOverlay = document.getElementById('readOverlay');
let currentReadId = null;

function openReadModal(id, fetched){
  const e = library.find(x => x.id === id);
  if(!e) return;
  if(e._t && !fetched){ withFullText(e).then(() => openReadModal(id, true)); return; }
  if(e.category === 'saint') markRead('read.saints', id);
  currentReadId = id;
  document.getElementById('readCat').textContent = CAT_LABEL[e.category] || e.category;
  document.getElementById('readTitle').classList.remove('notranslate');
  document.getElementById('readTitle').textContent = e.title;
  document.getElementById('readByline').textContent = e.author || '';
  document.getElementById('readByline').style.display = e.author ? 'block' : 'none';
  const stalePatron = document.getElementById('readPatron');
  if(stalePatron) stalePatron.remove();
  if(e.patron){
    const patronEl = document.createElement('div');
    patronEl.id = 'readPatron';
    patronEl.className = 'patron-line';
    patronEl.innerHTML = `<span class="patron-label">Patron saint of</span>${e.patron.split(', ').map(p => `<span class="patron-tag">${escapeHtml(p)}</span>`).join('')}`;
    document.getElementById('readByline').insertAdjacentElement('afterend', patronEl);
  }

  const paragraphs = (e.content || '').split(/\n\s*\n/).filter(Boolean);
  const bodyEl = document.getElementById('readBody');
  bodyEl.innerHTML = paragraphs.length
    ? paragraphs.map(p => `<p>${escapeHtml(p).replace(/\n/g,'<br>')}</p>`).join('')
    : '<p style="color:var(--ink-soft); font-style:italic;">No text has been added for this entry yet.</p>';

  let intercessionEl = document.getElementById('readIntercession');
  if(intercessionEl) intercessionEl.remove();
  const staleNotable = document.getElementById('readNotable');
  if(staleNotable) staleNotable.remove();
  document.querySelectorAll('#readOverlay .theo-block').forEach(el => el.remove());
  if(e.category === 'theology') document.getElementById('readLinkBox').before(buildTheologyBlocks(e));
  if(e.intercession){
    intercessionEl = document.createElement('div');
    intercessionEl.id = 'readIntercession';
    intercessionEl.className = 'intercession-block';
    intercessionEl.innerHTML = `<h3>Prayer of Intercession</h3><p>${escapeHtml(e.intercession)}</p>`;
    bodyEl.insertAdjacentElement('afterend', intercessionEl);
  }
  const staleQuotes = document.getElementById('readQuotes');
  if(staleQuotes) staleQuotes.remove();
  const quotesEl = e.category === 'saint' ? saintQuotesBlock(e) : null;
  if(quotesEl){
    (document.getElementById('readIntercession') || bodyEl).insertAdjacentElement('afterend', quotesEl);
    quotesEl.querySelector('[data-route]').addEventListener('click', () => readOverlay.classList.remove('open'));
  }
  if(e.notable){
    const notableEl = document.createElement('div');
    notableEl.id = 'readNotable';
    notableEl.className = 'intercession-block';
    notableEl.innerHTML = `<h3>A Well-Known Line</h3><p>${escapeHtml(e.notable)}</p>`;
    (document.getElementById('readIntercession') || bodyEl).insertAdjacentElement('afterend', notableEl);
  }

  const portraitEl = document.getElementById('readPortrait');
  if(HAS_PICTURE.has(e.category)){
    portraitEl.hidden = false;
    portraitEl.innerHTML = `<div class="saint-portrait large${e.category === 'saint' ? '' : ' shape-' + e.category}" data-sid="${e.id}">${portraitPlaceholder(e.title)}</div><figcaption></figcaption>`;
    const frame = portraitEl.querySelector('.saint-portrait');
    fillPortrait(frame, e);
    fetchSaintPortrait(e).then(p => {
      if(p && p.page && currentReadId === e.id){
        portraitEl.querySelector('figcaption').innerHTML = `<a href="${escapeHtml(p.page)}" target="_blank" rel="noopener">${p.icon ? 'Icon via Wikimedia Commons' : 'Image via Wikipedia'} ↗</a>`;
      }
    });
  } else {
    portraitEl.hidden = true;
    portraitEl.innerHTML = '';
  }

  const card = PRAYER_CARDS[e.id];
  const modalEl = readOverlay.querySelector('.read-modal');
  modalEl.classList.toggle('card-mode', !!card);
  modalEl.style.setProperty('--accent', card ? card.accent : 'var(--wine)');
  document.getElementById('readArt').innerHTML = card ? cardArt(card.art) : '';
  document.getElementById('readCat').textContent = card ? 'Prayer Card' : (CAT_LABEL[e.category] || e.category);

  const linkBox = document.getElementById('readLinkBox');
  linkBox.innerHTML = e.link ? `<a href="${escapeHtml(e.link)}" target="_blank" rel="noopener">View source / full text ↗</a>` : '';
  if(e.category === 'book' && BOOK_TEXTS[e.id]){
    linkBox.innerHTML = `<button class="btn" data-route="library/books/${BOOK_TEXTS[e.id][0]}">Read it here</button>` + (e.link ? ` <a href="${escapeHtml(e.link)}" target="_blank" rel="noopener">Source ↗</a>` : '');
    linkBox.querySelector('button').addEventListener('click', () => readOverlay.classList.remove('open'));
  }
  if(e.id === 'b55'){
    linkBox.innerHTML = `<button class="btn" data-route="library/catechism">Open the Catechism here</button> <a href="${escapeHtml(e.link)}" target="_blank" rel="noopener">vatican.va ↗</a>`;
  }
  const bibleBook = e.category === 'bible' && BIBLE_BOOKS.find(x => x[1] === e.id);
  if(bibleBook){
    linkBox.innerHTML = `<button class="btn" data-route="library/bible/${bibleBook[0]}/1">Read ${escapeHtml(e.title)} here</button>`;
    linkBox.querySelector('button').addEventListener('click', () => readOverlay.classList.remove('open'));
  }
  if(card){
    linkBox.innerHTML = `<button class="btn quiet" id="printCardBtn">Print this card</button>`;
    document.getElementById('printCardBtn').addEventListener('click', () => window.print());
  }

  const tagsEl = document.getElementById('readTags');
  tagsEl.innerHTML = (e.tags||[]).map(t => `<span class="tag">${escapeHtml(t)}</span>`).join('');

  renderReadActions(e);
  if(prayerLangsFor(e)) applyPrayerLang(e);
  addRecent(e.id);
  readOverlay.classList.add('open');
}

document.getElementById('readClose').addEventListener('click', () => readOverlay.classList.remove('open'));
readOverlay.addEventListener('click', e => { if(e.target === readOverlay) readOverlay.classList.remove('open'); });

/* =========================================================
   PERSONAL DATA (kept only in this browser)
   ========================================================= */
const memoryStore = {};
const store = {
  get(key, fallback){
    try{
      const v = localStorage.getItem('sanctify.' + key);
      if(v !== null) return JSON.parse(v);
    }catch(e){}
    return key in memoryStore ? memoryStore[key] : fallback;
  },
  set(key, value){
    memoryStore[key] = value;
    try{ localStorage.setItem('sanctify.' + key, JSON.stringify(value)); }catch(e){}
  }
};

function isSaved(id){ return store.get('saved', []).includes(id); }
function toggleSaved(id){
  const saved = store.get('saved', []);
  const i = saved.indexOf(id);
  if(i >= 0) saved.splice(i, 1); else saved.unshift(id);
  store.set('saved', saved);
  updateCounts();
  shareSavedSoon();
  return i < 0;
}
// When a member shows their saved pages on their profile, keep that list up to date
let shareSavedTimer = 0;
function shareSavedSoon(){
  if(!store.get('shareSaved', false) || !Community.user) return;
  clearTimeout(shareSavedTimer);
  shareSavedTimer = setTimeout(() => { api('account/favorites', { method:'PUT', body:{ show:true, ids:store.get('saved', []) } }).catch(() => {}); }, 1500);
}
function addRecent(id){
  const recent = store.get('recent', []).filter(x => x !== id);
  recent.unshift(id);
  store.set('recent', recent.slice(0, 12));
}

function toast(message){
  let el = document.getElementById('toast');
  if(!el){
    el = document.createElement('div');
    el.id = 'toast';
    el.className = 'toast';
    el.setAttribute('role', 'status');
    document.body.appendChild(el);
  }
  el.textContent = message;
  el.classList.add('show');
  clearTimeout(toast.timer);
  toast.timer = setTimeout(() => el.classList.remove('show'), 2200);
}

async function copyText(text){
  try{ await navigator.clipboard.writeText(text); return true; }
  catch(e){
    const ta = document.createElement('textarea');
    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.select();
    let ok = false;
    try{ ok = document.execCommand('copy'); }catch(err){}
    ta.remove();
    return ok;
  }
}

function entryLink(id){ return location.origin + location.pathname + '#read=' + encodeURIComponent(id); }

function entryPlainText(e){
  return [e.title, e.author, '', e.content, e.intercession ? '\n' + e.intercession : '', '', entryLink(e.id)]
    .filter(x => x !== undefined && x !== null).join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function renderReadActions(e){
  const bar = document.getElementById('readActions');
  const saved = isSaved(e.id);
  const canNovena = e.category === 'saint' || e.category === 'prayer';
  const activeNovena = store.get('novenas', []).some(n => n.id === e.id && n.done.filter(Boolean).length < 9);
  bar.innerHTML = `
    <button class="read-action${saved ? ' on' : ''}" data-act="save" aria-pressed="${saved}">${saved ? '★ Saved' : '☆ Save'}</button>
    <button class="read-action" data-act="copy">Copy text</button>
    <button class="read-action" data-act="share">Share</button>
    <button class="read-action" data-act="image">Share as image</button>
    <button class="read-action" data-act="discuss">Discuss</button>
    ${canSpeak ? '<button class="read-action" data-act="listen" aria-pressed="false">🔊 Listen</button>' : ''}
    ${canNovena ? `<button class="read-action" data-act="novena"${activeNovena ? ' disabled' : ''}>${activeNovena ? 'Novena in progress' : 'Start a novena'}</button>` : ''}
    ${prayerLangsFor(e) ? `<span class="lang-toggle notranslate" translate="no" role="group" aria-label="Language">${prayerLangsFor(e).map(([code, label]) => `<button class="lang-btn" data-lang="${code}" aria-pressed="false" lang="${code}">${label}</button>`).join('')}</span>` : ''}`;
  bar.querySelectorAll('.lang-btn').forEach(b => b.addEventListener('click', () => {
    store.set('prayerLang', b.dataset.lang);
    applyPrayerLang(e);
  }));
  bar.querySelector('[data-act="save"]').addEventListener('click', () => {
    const nowSaved = toggleSaved(e.id);
    toast(nowSaved ? 'Saved to My Sanctify' : 'Removed from My Sanctify');
    renderReadActions(e);
    if(activeCategory === 'mine') renderMine();
  });
  bar.querySelector('[data-act="discuss"]').addEventListener('click', () => discussEntry(e));
  bar.querySelector('[data-act="image"]').addEventListener('click', () => shareEntryImage(e));
  const listen = bar.querySelector('[data-act="listen"]');
  if(listen) listen.addEventListener('click', () => {
    const extra = document.getElementById('readIntercession');
    toggleSpeak(listen, e.title + '. ' + document.getElementById('readBody').innerText + (extra ? ' ' + extra.innerText.replace(/^Prayer of Intercession/, '') : ''));
  });
  bar.querySelector('[data-act="copy"]').addEventListener('click', async () => {
    toast(await copyText(entryPlainText(e)) ? 'Text copied' : 'Could not copy');
  });
  bar.querySelector('[data-act="share"]').addEventListener('click', async () => {
    const url = entryLink(e.id);
    if(navigator.share){
      try{ await navigator.share({ title:e.title + ' — Sanctify', url }); return; }catch(err){ if(err && err.name === 'AbortError') return; }
    }
    toast(await copyText(url) ? 'Link copied' : 'Could not copy link');
  });
  const nov = bar.querySelector('[data-act="novena"]');
  if(nov) nov.addEventListener('click', () => {
    startNovena(e.id);
    toast('Novena started — see My Sanctify');
    renderReadActions(e);
  });
}

/* ---------- Share as an image: a story-size card in the reader's own theme ---------- */
function cutText(text, max){
  const t = (text || '').replace(/\s+/g, ' ').trim();
  if(t.length <= max) return t;
  const part = t.slice(0, max), end = Math.max(part.lastIndexOf('. '), part.lastIndexOf('! '), part.lastIndexOf('? '));
  return end > max * 0.5 ? part.slice(0, end + 1) : part.slice(0, part.lastIndexOf(' ')).replace(/[,;:—–-]$/, '') + '…';
}
function wrapLines(g, text, width, maxLines){
  const lines = []; let line = '';
  for(const word of text.split(' ')){
    const test = line ? line + ' ' + word : word;
    if(g.measureText(test).width > width && line){ lines.push(line); line = word; } else line = test;
  }
  if(line) lines.push(line);
  if(lines.length > maxLines){
    lines.length = maxLines;
    let last = lines[maxLines - 1];
    while(g.measureText(last + '…').width > width && last.includes(' ')) last = last.slice(0, last.lastIndexOf(' '));
    lines[maxLines - 1] = last.replace(/[,;:.]$/, '') + '…';
  }
  return lines;
}
function loadImage(src){
  return new Promise((ok, fail) => { const im = new Image(); im.crossOrigin = 'anonymous'; im.onload = () => ok(im); im.onerror = fail; im.src = src; });
}
// card: { kicker, title, byline, body, quote, image }
async function drawShareCard(card, withImage = true){
  const W = 1080, H = 1920;
  const css = getComputedStyle(document.documentElement);
  const v = (n, f) => (css.getPropertyValue(n) || '').trim() || f;
  const page = v('--parchment', '#efe6d0'), paper = v('--parchment-light', '#f6f0dc'), ink = v('--ink', '#2b2118'),
        soft = v('--ink-soft', '#6b5a48'), accent = v('--wine', '#7a2426'), gold = v('--gold', '#a6824a');
  const serif = "'Cormorant Garamond', Georgia, serif", text = "'Source Serif 4', Georgia, serif";
  try{ await Promise.all([document.fonts.load(`700 80px ${serif}`), document.fonts.load(`italic 500 60px ${serif}`), document.fonts.load(`400 40px ${text}`), document.fonts.load(`italic 400 36px ${text}`)]); }catch(e){}
  const c = document.createElement('canvas'); c.width = W; c.height = H;
  const g = c.getContext('2d');
  g.fillStyle = page; g.fillRect(0, 0, W, H);
  const glowG = g.createRadialGradient(W / 2, 420, 40, W / 2, 420, 900);
  glowG.addColorStop(0, accent + '22'); glowG.addColorStop(1, accent + '00');
  g.fillStyle = glowG; g.fillRect(0, 0, W, H);
  const rr = (x, y, w, h, r) => { g.beginPath(); if(g.roundRect) g.roundRect(x, y, w, h, r); else g.rect(x, y, w, h); };
  rr(56, 56, W - 112, H - 112, 44); g.fillStyle = paper; g.fill(); g.lineWidth = 3; g.strokeStyle = gold; g.stroke();
  // The edition's cross and the name
  g.save(); g.translate(W / 2 - 42, 112); g.scale(84 / 64, 84 / 64); g.fillStyle = accent; g.fill(new Path2D(crossPath()), 'evenodd'); g.restore();
  g.fillStyle = soft; g.textAlign = 'center'; g.textBaseline = 'alphabetic';
  g.font = `600 34px ${serif}`; if('letterSpacing' in g) g.letterSpacing = '12px';
  g.fillText('SANCTIFY', W / 2 + 6, 250);
  if('letterSpacing' in g) g.letterSpacing = '0px';
  let y = 330;
  if(card.kicker){
    g.font = `600 26px ${text}`; g.fillStyle = accent; if('letterSpacing' in g) g.letterSpacing = '6px';
    g.fillText(card.kicker.toUpperCase(), W / 2 + 3, y); if('letterSpacing' in g) g.letterSpacing = '0px';
    y += 40;
  }
  // A saint's portrait, in an arch
  if(card.image && withImage){
    const im = await loadImage(card.image);
    const aw = 470, ah = 580, ax = W / 2 - aw / 2, ay = y + 10;
    g.save(); g.beginPath(); g.arc(W / 2, ay + aw / 2, aw / 2, Math.PI, 0); g.lineTo(ax + aw, ay + ah); g.lineTo(ax, ay + ah); g.closePath(); g.clip();
    const s = Math.max(aw / im.width, ah / im.height), dw = im.width * s, dh = im.height * s;
    g.drawImage(im, W / 2 - dw / 2, ay + (ah - dh) * 0.25, dw, dh); g.restore();
    g.beginPath(); g.arc(W / 2, ay + aw / 2, aw / 2, Math.PI, 0); g.lineTo(ax + aw, ay + ah); g.lineTo(ax, ay + ah); g.closePath();
    g.lineWidth = 4; g.strokeStyle = gold; g.stroke();
    y = ay + ah + 40;
  } else y += 30;
  const room = 1920 - 330;   // the footer starts here
  if(card.quote){
    g.font = `italic 500 64px ${serif}`; g.fillStyle = ink;
    const lines = wrapLines(g, '“' + card.quote + '”', W - 220, 11);
    y = Math.max(y + 40, (room - lines.length * 84) / 2 + 120);
    lines.forEach(l => { g.fillText(l, W / 2, y + 60); y += 84; });
    if(card.title){ g.font = `600 40px ${text}`; g.fillStyle = accent; g.fillText('— ' + card.title, W / 2, y + 70); y += 80; }
    if(card.byline){ g.font = `italic 400 30px ${text}`; g.fillStyle = soft; wrapLines(g, card.byline, W - 260, 2).forEach(l => { g.fillText(l, W / 2, y + 60); y += 40; }); }
  } else {
    // Measure first, so a card without a picture can center its text between the header and the address
    const size = card.image ? 34 : 38, lh = Math.round(size * 1.5);
    g.font = `700 76px ${serif}`; const titleLines = wrapLines(g, card.title, W - 220, 3);
    g.font = `italic 400 32px ${text}`; const byLines = card.byline ? wrapLines(g, card.byline, W - 240, 2) : [];
    const head = titleLines.length * 82 + byLines.length * 44 + 66;
    g.font = `400 ${size}px ${text}`;
    const bodyLines = card.body ? wrapLines(g, card.body, W - 240, Math.max(3, Math.floor((room - y - head) / lh))) : [];
    if(!card.image) y = Math.max(y, Math.round((y + room) / 2 - (head + bodyLines.length * lh) / 2));
    g.font = `700 76px ${serif}`; g.fillStyle = ink;
    titleLines.forEach(l => { g.fillText(l, W / 2, y + 66); y += 82; });
    g.font = `italic 400 32px ${text}`; g.fillStyle = soft;
    byLines.forEach(l => { g.fillText(l, W / 2, y + 44); y += 44; });
    y += 36;
    g.strokeStyle = gold; g.lineWidth = 2; g.beginPath(); g.moveTo(W / 2 - 60, y); g.lineTo(W / 2 + 60, y); g.stroke();
    y += 30;
    g.font = `400 ${size}px ${text}`; g.fillStyle = ink;
    bodyLines.forEach(l => { g.fillText(l, W / 2, y + size); y += lh; });
  }
  // The address
  g.font = `600 40px ${text}`;
  const url = 'sanctify.pages.dev', uw = g.measureText(url).width + 90;
  rr(W / 2 - uw / 2, H - 230, uw, 84, 42); g.fillStyle = accent; g.fill();
  g.fillStyle = paper; g.fillText(url, W / 2, H - 175);
  return c;
}
async function shareCardImage(card, name){
  toast(i18n('Making the image…') || 'Making the image…');
  let canvas, blob;
  try{
    canvas = await drawShareCard(card, true);
    blob = await new Promise(r => canvas.toBlob(r, 'image/png'));
  }catch(err){ blob = null; }
  if(!blob){   // a picture that won't load (or can't be drawn) is left out
    canvas = await drawShareCard(card, false);
    blob = await new Promise(r => canvas.toBlob(r, 'image/png'));
  }
  const file = new File([blob], 'sanctify-' + (name || 'card').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 50) + '.png', { type:'image/png' });
  if(navigator.canShare && navigator.canShare({ files:[file] })){
    try{ await navigator.share({ files:[file], title:card.title || 'Sanctify' }); return; }catch(err){ if(err && err.name === 'AbortError') return; }
  }
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = file.name;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 4000);
  toast(i18n('Image saved') || 'Image saved');
}
// The Verse of the Day, on Home and Today
document.addEventListener('click', ev => {
  const b = ev.target.closest('[data-verse-image]');
  if(!b) return;
  ev.preventDefault(); ev.stopPropagation();
  shareCardImage({ kicker:i18n('Verse of the Day') || 'Verse of the Day', quote:b.dataset.text, title:b.dataset.ref, byline:'Revised Standard Version, Catholic Edition' }, 'verse-' + b.dataset.ref);
});
async function shareEntryImage(e){
  await withFullText(e);
  const kicker = i18n(CAT_LABEL[e.category] || '') || CAT_LABEL[e.category] || '';
  let body = e.category === 'prayer' ? (document.getElementById('readBody').innerText || e.content) : e.content;
  body = cutText(body.replace(/\n+/g, ' '), e.category === 'saint' ? 380 : 620);
  let image = null;
  if(e.category === 'saint'){ try{ const p = await fetchSaintPortrait(e); image = p && p.src || null; }catch(err){} }
  await shareCardImage({ kicker, title:e.title, byline:e.author || '', body, image }, e.title);
}

/* ---------- Novenas ---------- */
function isoDay(d){ return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; }
function parseIsoDay(s){ const [y, m, d] = s.split('-').map(Number); return new Date(y, m - 1, d); }
function startNovena(id){
  const novenas = store.get('novenas', []).filter(n => !(n.id === id && n.done.filter(Boolean).length < 9));
  novenas.unshift({ id, start:isoDay(startOfToday()), done:Array(9).fill(false) });
  store.set('novenas', novenas);
  updateCounts();
}
function novenaDayNumber(n){ return Math.min(9, Math.max(1, dayNumber(startOfToday()) - dayNumber(parseIsoDay(n.start)) + 1)); }

/* ---------- My Sanctify page ---------- */
function miniRow(e, extraHtml){
  const row = document.createElement('div');
  row.className = 'mine-row';
  row.innerHTML = `
    <button class="mine-open" data-id="${e.id}">
      <span class="mine-cat">${escapeHtml(CAT_LABEL[e.category] || e.category)}</span>
      <span class="mine-title">${escapeHtml(e.title)}</span>
    </button>${extraHtml || ''}`;
  row.querySelector('.mine-open').addEventListener('click', () => openReadModal(e.id));
  return row;
}

function renderMine(){
  entryListEl.innerHTML = '';
  entryListEl.insertAdjacentHTML('beforeend', homePrayerHtml());
  bindHomePrayer(entryListEl);
  const find = id => library.find(x => x.id === id);

  // Novenas
  const novenas = store.get('novenas', []).filter(n => find(n.id));
  const novSec = document.createElement('section');
  novSec.className = 'mine-section';
  novSec.innerHTML = `<h3 class="list-heading">Novenas</h3>`;
  if(!novenas.length){
    novSec.insertAdjacentHTML('beforeend', `<p class="mine-empty">A novena is nine days of prayer for a particular intention. Open any saint or prayer and choose <strong>Start a novena</strong>.</p>`);
  }
  novenas.forEach((n, idx) => {
    const e = find(n.id);
    const count = n.done.filter(Boolean).length;
    const today = novenaDayNumber(n);
    const box = document.createElement('div');
    box.className = 'novena-card' + (count === 9 ? ' complete' : '');
    box.innerHTML = `
      <div class="novena-top">
        <div><div class="daily-kicker">${count === 9 ? 'Completed' : `Day ${today} of 9`}</div><div class="novena-title">Novena: ${escapeHtml(e.title)}</div></div>
        <button class="btn quiet novena-remove" aria-label="Remove novena">Remove</button>
      </div>
      <div class="novena-days">${n.done.map((d, i) => `<button class="novena-day${d ? ' done' : ''}${i + 1 === today && count < 9 ? ' today' : ''}" data-i="${i}" aria-pressed="${d}" aria-label="Day ${i + 1}${d ? ', prayed' : ''}">${i + 1}</button>`).join('')}</div>
      <div class="novena-foot">
        <button class="read-action novena-pray">${e.category === 'saint' ? 'Pray the prayer of intercession' : 'Pray the prayer'}</button>
        <span class="novena-progress">${count} of 9 days prayed</span>
      </div>`;
    box.querySelectorAll('.novena-day').forEach(b => b.addEventListener('click', () => {
      const all = store.get('novenas', []);
      const target = all.find(x => x.id === n.id && x.start === n.start);
      if(!target) return;
      target.done[Number(b.dataset.i)] = !target.done[Number(b.dataset.i)];
      store.set('novenas', all);
      if(target.done.every(Boolean)){ toast('Novena complete. Deo gratias!'); markRead('read.novenas', n.id + '@' + n.start); }
      renderMine();
    }));
    box.querySelector('.novena-pray').addEventListener('click', () => openReadModal(e.id));
    box.querySelector('.novena-remove').addEventListener('click', () => {
      store.set('novenas', store.get('novenas', []).filter(x => !(x.id === n.id && x.start === n.start)));
      updateCounts();
      renderMine();
    });
    novSec.appendChild(box);
  });
  entryListEl.appendChild(novSec);

  // Prayer intentions
  const intentions = store.get('intentions', []);
  const intSec = document.createElement('section');
  intSec.className = 'mine-section';
  intSec.innerHTML = `
    <h3 class="list-heading">Prayer Intentions</h3>
    <form class="intention-form">
      <input type="text" maxlength="240" placeholder="Who or what would you like to pray for?" aria-label="New prayer intention">
      <button class="btn primary" type="submit">Add</button>
    </form>
    <div class="intention-list"></div>`;
  const listEl = intSec.querySelector('.intention-list');
  const open = intentions.filter(x => !x.answered), answered = intentions.filter(x => x.answered);
  if(!intentions.length) listEl.innerHTML = `<p class="mine-empty">Keep a list of the people and needs you are praying for. When a prayer is answered, mark it and give thanks.</p>`;
  const renderIntention = it => {
    const row = document.createElement('div');
    row.className = 'intention' + (it.answered ? ' answered' : '');
    row.innerHTML = `
      <button class="intention-check" aria-pressed="${!!it.answered}" aria-label="${it.answered ? 'Mark as not yet answered' : 'Mark as answered'}">${it.answered ? '✓' : ''}</button>
      <div class="intention-text">${escapeHtml(it.text)}<span class="intention-date">Added ${escapeHtml(it.added)}${it.answered ? ' · Answered ' + escapeHtml(it.answered) : ''}</span></div>
      <button class="intention-delete" aria-label="Delete intention">×</button>`;
    row.querySelector('.intention-check').addEventListener('click', () => {
      const all = store.get('intentions', []);
      const t = all.find(x => x.id === it.id);
      t.answered = t.answered ? null : startOfToday().toLocaleDateString(undefined, { month:'short', day:'numeric', year:'numeric' });
      store.set('intentions', all);
      if(t.answered) toast('Thanks be to God!');
      renderMine();
    });
    row.querySelector('.intention-delete').addEventListener('click', () => {
      store.set('intentions', store.get('intentions', []).filter(x => x.id !== it.id));
      renderMine();
    });
    return row;
  };
  open.forEach(it => listEl.appendChild(renderIntention(it)));
  if(answered.length){
    listEl.insertAdjacentHTML('beforeend', `<div class="patron-filters-label" style="margin-top:14px">Prayers answered</div>`);
    answered.forEach(it => listEl.appendChild(renderIntention(it)));
  }
  intSec.querySelector('.intention-form').addEventListener('submit', ev => {
    ev.preventDefault();
    const input = ev.target.querySelector('input');
    const text = input.value.trim();
    if(!text) return;
    const all = store.get('intentions', []);
    all.unshift({ id:Date.now().toString(36), text, added:startOfToday().toLocaleDateString(undefined, { month:'short', day:'numeric', year:'numeric' }), answered:null });
    store.set('intentions', all);
    renderMine();
    const again = entryListEl.querySelector('.intention-form input');
    if(again) again.focus();
  });
  entryListEl.appendChild(intSec);

  // Saved and recent
  [['saved', 'Saved', 'Tap ☆ Save on any prayer, saint, book, or article to keep it here.'],
   ['recent', 'Recently Viewed', 'Entries you open will appear here.']].forEach(([key, title, empty]) => {
    const ids = store.get(key, []).filter(find);
    const sec = document.createElement('section');
    sec.className = 'mine-section';
    sec.innerHTML = `<h3 class="list-heading">${title}</h3>`;
    if(!ids.length) sec.insertAdjacentHTML('beforeend', `<p class="mine-empty">${empty}</p>`);
    ids.forEach(id => {
      const row = miniRow(find(id), key === 'saved' ? `<button class="intention-delete" aria-label="Remove from saved">×</button>` : '');
      const rm = row.querySelector('.intention-delete');
      if(rm) rm.addEventListener('click', () => { toggleSaved(id); renderMine(); });
      sec.appendChild(row);
    });
    entryListEl.appendChild(sec);
  });

  entryListEl.insertAdjacentHTML('beforeend', `<p class="mine-privacy">🔒 Your saved items, intentions, and novenas are stored only on this device, in this browser. Nothing is sent anywhere.</p>`);
}

/* =========================================================
   PRAYER TIMER
   ========================================================= */
const timerState = { total:10 * 60, remaining:10 * 60, running:false, endsAt:0, tick:null, wakeLock:null, interval:0 };

function playBell(){
  try{
    const Ctx = window.AudioContext || window.webkitAudioContext;
    const ctx = playBell.ctx || (playBell.ctx = new Ctx());
    if(ctx.state === 'suspended') ctx.resume();
    const now = ctx.currentTime;
    // A soft bell: a few inharmonic partials with a long decay
    [[1, 0.5], [2.76, 0.18], [5.4, 0.1], [8.93, 0.05]].forEach(([mult, gain]) => {
      const osc = ctx.createOscillator(), g = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.value = 392 * mult;
      g.gain.setValueAtTime(0.0001, now);
      g.gain.exponentialRampToValueAtTime(gain * 0.5, now + 0.01);
      g.gain.exponentialRampToValueAtTime(0.0001, now + 4.5 / Math.sqrt(mult));
      osc.connect(g).connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 5);
    });
  }catch(e){}
}

function fmtTime(s){ s = Math.max(0, Math.ceil(s)); return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`; }

async function setWakeLock(on){
  try{
    if(on && 'wakeLock' in navigator && !timerState.wakeLock) timerState.wakeLock = await navigator.wakeLock.request('screen');
    if(!on && timerState.wakeLock){ await timerState.wakeLock.release(); timerState.wakeLock = null; }
  }catch(e){}
}

function timerTick(){
  timerState.remaining = (timerState.endsAt - Date.now()) / 1000;
  if(timerState.interval && timerState.running){
    const elapsed = timerState.total - timerState.remaining;
    const mark = Math.floor(elapsed / (timerState.interval * 60));
    if(mark > (timerState.lastMark || 0) && timerState.remaining > 1){ timerState.lastMark = mark; playBell(); }
  }
  if(timerState.remaining <= 0){
    timerState.remaining = 0;
    timerState.running = false;
    clearInterval(timerState.tick);
    setWakeLock(false);
    playBell(); setTimeout(playBell, 1600); setTimeout(playBell, 3200);
    logPrayer('silence');
    toast('Your time of prayer is complete');
  }
  updateTimerView();
}

function updateTimerView(){
  const face = document.getElementById('timerFace');
  if(!face) return;
  const frac = timerState.total ? timerState.remaining / timerState.total : 0;
  face.textContent = fmtTime(timerState.remaining);
  const ring = document.getElementById('timerRing');
  const c = 2 * Math.PI * 88;
  ring.setAttribute('stroke-dasharray', c.toFixed(1));
  ring.setAttribute('stroke-dashoffset', (c * (1 - frac)).toFixed(1));
  const btn = document.getElementById('timerStart');
  btn.textContent = timerState.running ? 'Pause' : (timerState.remaining < timerState.total && timerState.remaining > 0 ? 'Resume' : 'Begin');
}

function renderTimer(){
  entryListEl.innerHTML = '';
  const verse = dailyPick(DAILY_VERSES, 91, startOfToday());
  const wrap = document.createElement('div');
  wrap.className = 'timer-wrap';
  wrap.innerHTML = `
    <div class="timer-presets" role="group" aria-label="Length of prayer">
      ${[[5, '5 min'], [10, '10 min'], [15, '15 min'], [20, '20 min'], [30, '30 min'], [60, 'Holy Hour']].map(([m, label]) =>
        `<button class="patron-chip${timerState.total === m * 60 ? ' active' : ''}" data-min="${m}">${label}</button>`).join('')}
    </div>
    <div class="timer-dial">
      <svg viewBox="0 0 200 200" aria-hidden="true">
        <circle cx="100" cy="100" r="88" fill="none" stroke="var(--line)" stroke-width="6"/>
        <circle id="timerRing" cx="100" cy="100" r="88" fill="none" stroke="var(--wine)" stroke-width="6" stroke-linecap="round" transform="rotate(-90 100 100)"/>
      </svg>
      <div class="timer-center">
        <div class="timer-face" id="timerFace" aria-live="off">${fmtTime(timerState.remaining)}</div>
        <div class="timer-sub">minutes of prayer</div>
      </div>
    </div>
    <div class="timer-controls">
      <button class="btn primary" id="timerStart">Begin</button>
      <button class="btn" id="timerReset">Reset</button>
    </div>
    <label class="timer-option"><input type="checkbox" id="timerInterval" ${timerState.interval ? 'checked' : ''}> Ring a gentle bell every 5 minutes</label>
    <blockquote class="timer-verse">“${escapeHtml(verse.text)}”<cite>${escapeHtml(verse.ref)}</cite></blockquote>
    <p class="timer-tip">Find a quiet place, put your phone face down, and begin with the Sign of the Cross. When distractions come, gently return to the Lord, perhaps with a short prayer like “Jesus, I trust in you.”</p>`;
  entryListEl.appendChild(wrap);

  wrap.querySelectorAll('[data-min]').forEach(b => b.addEventListener('click', () => {
    if(timerState.running) return toast('Pause the timer to change its length');
    timerState.total = timerState.remaining = Number(b.dataset.min) * 60;
    timerState.lastMark = 0;
    renderTimer();
  }));
  document.getElementById('timerStart').addEventListener('click', () => {
    if(timerState.running){
      timerState.running = false;
      clearInterval(timerState.tick);
      timerState.remaining = (timerState.endsAt - Date.now()) / 1000;
      setWakeLock(false);
    } else {
      if(timerState.remaining <= 0){ timerState.remaining = timerState.total; timerState.lastMark = 0; }
      if(timerState.remaining === timerState.total) playBell();
      timerState.running = true;
      timerState.endsAt = Date.now() + timerState.remaining * 1000;
      clearInterval(timerState.tick);
      timerState.tick = setInterval(timerTick, 250);
      setWakeLock(true);
    }
    updateTimerView();
  });
  document.getElementById('timerReset').addEventListener('click', () => {
    timerState.running = false;
    clearInterval(timerState.tick);
    timerState.remaining = timerState.total;
    timerState.lastMark = 0;
    setWakeLock(false);
    updateTimerView();
  });
  document.getElementById('timerInterval').addEventListener('change', ev => { timerState.interval = ev.target.checked ? 5 : 0; });
  updateTimerView();
}

/* =========================================================
   QUIZ (generated from the repository's own content)
   ========================================================= */
let quizState = null;

function shuffled(list){
  const a = list.slice();
  for(let i = a.length - 1; i > 0; i--){ const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}

function buildQuizQuestions(n){
  const by = cat => library.filter(e => e.category === cat);
  const makers = [];

  // Saint feast days
  const feastOf = s => { const m = /feast days? ([A-Z][a-z]+ \d{1,2})/.exec(s.author || ''); return m ? m[1] : null; };
  const saints = by('saint').filter(feastOf);
  makers.push(() => {
    const s = saints[Math.floor(Math.random() * saints.length)];
    const wrong = shuffled(saints.filter(x => feastOf(x) !== feastOf(s))).slice(0, 3);
    return { q:`Whose feast day is ${feastOf(s)}?`, answer:s.title, options:shuffled([s, ...wrong].map(x => x.title)), id:s.id };
  });

  // Book authors
  const authorOf = b => (b.author || '').split(',')[0].trim();
  const books = by('book').filter(b => /^[A-Z]/.test(authorOf(b)) && !/^(Anonymous|Compiled)/i.test(authorOf(b)));
  makers.push(() => {
    const b = books[Math.floor(Math.random() * books.length)];
    const wrong = shuffled([...new Set(books.map(authorOf))].filter(a => a !== authorOf(b))).slice(0, 3);
    return { q:`Who wrote “${b.title}”?`, answer:authorOf(b), options:shuffled([authorOf(b), ...wrong]), id:b.id };
  });

  // Church history dates
  const events = by('history').filter(h => /^(c\. )?\d{2,4}$/.test(h.author || ''));
  makers.push(() => {
    const h = events[Math.floor(Math.random() * events.length)];
    const wrong = shuffled(events.filter(x => Math.abs(x.year - h.year) > 40)).slice(0, 3).map(x => x.author);
    return { q:`When did this happen: ${h.title}?`, answer:h.author, options:shuffled([h.author, ...wrong]), id:h.id };
  });

  // Books of the Bible
  const SECTION_NAMES = {
    'Old Testament, Pentateuch':'Old Testament: the Pentateuch', 'Old Testament, Historical':'Old Testament: the Historical Books',
    'Old Testament, Wisdom':'Old Testament: the Wisdom Books', 'Old Testament, Prophetic':'Old Testament: the Prophets',
    'New Testament, Gospel':'New Testament: the Gospels', 'New Testament, History':'New Testament: the Acts of the Apostles',
    'New Testament, Pauline Epistle':'New Testament: the Letters of Paul', 'New Testament, Catholic Epistle':'New Testament: the Catholic Letters',
    'New Testament, Apocalyptic':'New Testament: Revelation'
  };
  const sectionOf = b => SECTION_NAMES[b.author];
  const bible = by('bible').filter(b => sectionOf(b) && !['Acts', 'Revelation'].some(t => b.title.startsWith(t)));
  const sections = Object.values(SECTION_NAMES);
  makers.push(() => {
    const b = bible[Math.floor(Math.random() * bible.length)];
    const wrong = shuffled(sections.filter(s => s !== sectionOf(b))).slice(0, 3);
    return { q:`Where in the Bible is the book of ${b.title} found?`, answer:sectionOf(b), options:shuffled([sectionOf(b), ...wrong]), id:b.id };
  });

  // Theology: which teaching does a Scripture passage support?
  const theo = by('theology').filter(t => t.scripture && t.scripture.length);
  makers.push(() => {
    const t = theo[Math.floor(Math.random() * theo.length)];
    const ref = t.scripture[Math.floor(Math.random() * t.scripture.length)];
    const wrong = shuffled(theo.filter(x => x.id !== t.id && !x.scripture.includes(ref))).slice(0, 3).map(x => x.title);
    return { q:`${ref} is a key passage for which topic?`, answer:t.title, options:shuffled([t.title, ...wrong]), id:t.id };
  });

  // The ecumenical councils
  makers.push(() => {
    const c = COUNCILS[Math.floor(Math.random() * COUNCILS.length)];
    const wrong = shuffled(COUNCILS.filter(x => x !== c)).slice(0, 3).map(x => x.name);
    return { q:`Which ecumenical council ${c.quiz}?`, answer:c.name, options:shuffled([c.name, ...wrong]), route:'history/councils' };
  });

  const out = [], seen = new Set();
  for(let tries = 0; out.length < n && tries < n * 20; tries++){
    const q = makers[(out.length + tries) % makers.length]();
    if(q) q.options = [...new Set(q.options)];
    if(!q || seen.has(q.q) || q.options.length < 4) continue;
    seen.add(q.q);
    out.push(q);
  }
  return shuffled(out);
}

function renderQuiz(){
  entryListEl.innerHTML = '';
  const wrap = document.createElement('div');
  wrap.className = 'quiz-wrap';
  const best = store.get('quizBest', null);

  if(!quizState){
    wrap.innerHTML = `
      <div class="quiz-intro">
        <p>Ten questions drawn at random from the saints, books, Church history, the Bible, and theology on Sanctify. Every quiz is different.</p>
        ${best !== null ? `<p class="quiz-best">Your best score: <strong>${best} / 10</strong></p>` : ''}
        <button class="btn primary" id="quizStart">Start the quiz</button>
      </div>`;
    entryListEl.appendChild(wrap);
    document.getElementById('quizStart').addEventListener('click', () => {
      quizState = { questions:buildQuizQuestions(10), i:0, score:0, picked:null };
      renderQuiz();
    });
    return;
  }

  const { questions, i } = quizState;
  if(i >= questions.length){
    const score = quizState.score;
    const newBest = best === null || score > best;
    if(newBest){ store.set('quizBest', score); checkBadgesSoon(); }
    const verdict = score === 10 ? 'Perfect! A true Doctor of the Church.' : score >= 8 ? 'Excellent work.' : score >= 5 ? 'Well done. Keep learning!' : 'Every saint started somewhere. Try again!';
    wrap.innerHTML = `
      <div class="quiz-intro">
        <div class="quiz-score">${score} / 10</div>
        <p>${verdict}${newBest && best !== null ? ' That’s a new personal best!' : ''}</p>
        <button class="btn primary" id="quizAgain">Take another quiz</button>
      </div>`;
    entryListEl.appendChild(wrap);
    document.getElementById('quizAgain').addEventListener('click', () => {
      quizState = { questions:buildQuizQuestions(10), i:0, score:0, picked:null };
      renderQuiz();
    });
    return;
  }

  const q = questions[i];
  const answered = quizState.picked !== null;
  wrap.innerHTML = `
    <div class="quiz-progress"><span>Question ${i + 1} of ${questions.length}</span><span>Score: ${quizState.score}</span></div>
    <div class="quiz-bar"><i style="width:${(i / questions.length) * 100}%"></i></div>
    <h3 class="quiz-q">${escapeHtml(q.q)}</h3>
    <div class="quiz-options">
      ${q.options.map(o => {
        let cls = 'quiz-option';
        if(answered && o === q.answer) cls += ' correct';
        else if(answered && o === quizState.picked) cls += ' wrong';
        return `<button class="${cls}" ${answered ? 'disabled' : ''}>${escapeHtml(o)}</button>`;
      }).join('')}
    </div>
    ${answered ? `
      <div class="quiz-feedback ${quizState.picked === q.answer ? 'good' : 'bad'}">
        <span>${quizState.picked === q.answer ? 'Correct!' : `The answer is <strong>${escapeHtml(q.answer)}</strong>.`}</span>
        <button class="cal-read" id="quizLearn">Learn more →</button>
      </div>
      <button class="btn primary" id="quizNext">${i + 1 < questions.length ? 'Next question' : 'See my score'}</button>` : ''}`;
  entryListEl.appendChild(wrap);

  wrap.querySelectorAll('.quiz-option').forEach(b => b.addEventListener('click', () => {
    quizState.picked = b.textContent;
    if(b.textContent === q.answer) quizState.score++;
    renderQuiz();
  }));
  if(answered){
    document.getElementById('quizLearn').addEventListener('click', () => q.route ? navigate(q.route) : openReadModal(q.id));
    document.getElementById('quizNext').addEventListener('click', () => { quizState.i++; quizState.picked = null; renderQuiz(); });
    document.getElementById('quizNext').focus();
  }
}

/* =========================================================
   FEAST-DAY FINDER (Saints page)
   ========================================================= */
function buildFeastFinder(){
  const box = document.createElement('div');
  box.className = 'feast-finder';
  box.innerHTML = `
    <label class="patron-filters-label" for="feastDate">Find the saints for any day (a birthday, anniversary, or baptism):</label>
    <div class="feast-finder-row">
      <select id="feastMonth" aria-label="Month">${MONTH_NAMES.map((m, i) => `<option value="${i + 1}">${monthLabel(i)}</option>`).join('')}</select>
      <select id="feastDay" aria-label="Day"></select>
    </div>
    <div class="feast-results" id="feastResults"></div>`;
  const monthSel = box.querySelector('#feastMonth'), daySel = box.querySelector('#feastDay');
  const show = () => {
    const m = Number(monthSel.value), d = Number(daySel.value);
    const date = new Date(2024, m - 1, d); // a leap year, so February 29 exists
    const obs = observancesFor(date).filter(o => o.type !== 'Season' && o.month !== 0 && !o.date);
    const res = box.querySelector('#feastResults');
    res.innerHTML = obs.length
      ? obs.map(o => `<div class="today-item${o.saints ? ' linked' : ''}" ${o.saints ? `data-id="${o.saints[0]}"` : ''}><span class="today-dot" style="background:${CAL_TYPE_COLOR[o.type] || 'var(--wine)'}"></span><strong>${escapeHtml(o.name)}</strong> <span class="today-type">(${escapeHtml(o.type)})</span></div>`).join('')
      : `<div class="today-item">No saint in Sanctify has a fixed feast on ${MONTH_NAMES[m - 1]} ${d} yet. Every day is also the feast of many other saints in the Roman Martyrology.</div>`;
    res.querySelectorAll('.linked').forEach(el => el.addEventListener('click', () => openReadModal(el.dataset.id)));
  };
  const fillDays = () => {
    const m = Number(monthSel.value);
    const dim = new Date(2024, m, 0).getDate();
    const keep = Math.min(Number(daySel.value) || 1, dim);
    daySel.innerHTML = Array.from({ length:dim }, (_, i) => `<option value="${i + 1}">${i + 1}</option>`).join('');
    daySel.value = String(keep);
  };
  const t = startOfToday();
  monthSel.value = String(t.getMonth() + 1);
  fillDays();
  daySel.value = String(t.getDate());
  monthSel.addEventListener('change', () => { fillDays(); show(); });
  daySel.addEventListener('change', show);
  show();
  return box;
}

