const TRANSLATED = /\.translate\.goog$/.test(location.hostname);
function currentLanguage(){ return TRANSLATED ? (new URLSearchParams(location.search).get('_x_tr_tl') || 'en') : store.get('lang', 'en'); }
function languageUrl(code){
  const here = location.pathname.replace(/index\.html$/, '') + location.hash;
  if(code === 'en') return SITE_ORIGIN + here;
  const host = new URL(SITE_ORIGIN).hostname.replace(/-/g, '--').replace(/\./g, '-') + '.translate.goog';
  return `https://${host}${location.pathname.replace(/index\.html$/, '')}?_x_tr_sl=en&_x_tr_tl=${encodeURIComponent(code)}&_x_tr_hl=${encodeURIComponent(code)}${location.hash}`;
}
