/* ---------- Settings ---------- */
/* ---------- Offline ----------
   After a first visit Sanctify opens without a connection. Saving for offline fetches everything else a reader
   might open, a few files at a time; the service worker keeps each one as it passes through. */
const offlineCan = () => 'serviceWorker' in navigator && !!navigator.serviceWorker.controller && 'caches' in window;
function offlineFiles(){
  const own = [...document.querySelectorAll('script[src], link[rel="stylesheet"][href]')]
    .map(el => el.getAttribute('src') || el.getAttribute('href')).filter(u => /^(app|lang)\//.test(u));
  return ['index.html', ...own, 'data/hymns.json', 'data/akathist.json', 'data/little-office.json', 'catechism/outline-1.json',
    ...Object.values(TEXT_FILES).map(n => `data/texts/${n}.json`)];
}
async function saveOffline(withBible, progress){
  const files = offlineFiles();
  const chapters = withBible ? BIBLE_BOOKS.flatMap(b => Array.from({ length:b[4] }, (x, i) => `bible/${b[0]}/${i + 1}.txt`)) : [];
  const total = files.length + chapters.length;
  let done = 0, failed = 0;
  const queue = [...files, ...chapters];
  const work = async () => {
    while(queue.length){
      const path = queue.shift();
      try{
        const res = await fetch(path);
        if(!res.ok) failed++;
        // A chapter with notes starts with *; its notes are a file of their own
        else if(path.startsWith('bible/') && (await res.text()).startsWith('*')){
          const notes = await fetch(path.replace(/\.txt$/, '.notes.txt'));
          if(!notes.ok) failed++;
        }
      }catch(e){ failed++; }
      progress(++done, total);
    }
  };
  await Promise.all(Array.from({ length:6 }, work));
  return { total, failed };
}
function offlineSettingsHtml(){
  const last = store.get('offline', null);
  return `<section class="settings-card" id="settingsOffline">
        <h3>${navIcon('book')}Offline</h3>
        <p class="forum-meta">Once you’ve visited, Sanctify opens without a connection. Save the rest too, to read the lives of the saints, Church history, the hymns, the Little Office, and the Akathist anywhere.</p>
        <label class="forum-check"><input type="checkbox" id="offlineBible"${last && last.bible ? ' checked' : ''}><span>Include the whole Bible (about 9 MB)</span></label>
        <div class="forum-form-actions"><button class="btn quiet" type="button" data-save-offline>${last ? 'Update the offline copy' : 'Save for offline use'}</button></div>
        <p class="forum-meta offline-status" aria-live="polite">${last ? escapeHtml(`Saved on ${new Date(last.at).toLocaleDateString(undefined, { month:'long', day:'numeric', year:'numeric' })}.`) : ''}</p>
      </section>`;
}
function bindOfflineSettings(root){
  const btn = root.querySelector('[data-save-offline]');
  if(!btn) return;
  const status = root.querySelector('.offline-status');
  btn.addEventListener('click', async () => {
    if(!offlineCan()){ status.textContent = 'Saving for offline use works once Sanctify has finished setting up. Reload the page and try again.'; return; }
    const bible = root.querySelector('#offlineBible').checked;
    btn.disabled = true;
    const res = await saveOffline(bible, (done, total) => { status.textContent = `Saving… ${done.toLocaleString()} of ${total.toLocaleString()}`; });
    btn.disabled = false;
    if(res.failed){ status.textContent = `${res.failed.toLocaleString()} files couldn’t be saved. Check your connection and try again.`; return; }
    store.set('offline', { at:Date.now(), bible });
    btn.textContent = 'Update the offline copy';
    status.textContent = 'Saved. Sanctify will work on this device without a connection.';
  });
}

function backupData(){
  const data = {};
  for(let i = 0; i < localStorage.length; i++){ const k = localStorage.key(i); if(k && k.startsWith('sanctify.')) data[k] = localStorage.getItem(k); }
  const blob = new Blob([JSON.stringify({ sanctify:1, saved:new Date().toISOString(), data }, null, 1)], { type:'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'sanctify-backup-' + new Date().toISOString().slice(0, 10) + '.json';
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 2000);
  toast(i18n('Your backup was downloaded.') || 'Your backup was downloaded.');
}
