/* =========================================================
   STATIONS OF THE CROSS
   ========================================================= */
const STATIONS_VERSICLE = { v:'We adore You, O Christ, and we bless You,', r:'because by Your holy cross You have redeemed the world.' };
const STATIONS_DATA = [
  { title:'Jesus is Condemned to Death', meditation:'Pilate washes his hands of responsibility and hands Jesus over to be crucified, though he finds no guilt in him. We consider how often we stay silent in the face of injustice simply to avoid discomfort.' },
  { title:'Jesus Carries His Cross', meditation:'Jesus accepts the instrument of his own execution and begins the long walk to Calvary. We ask for the grace to accept the crosses of our own lives without bitterness.' },
  { title:'Jesus Falls the First Time', meditation:'Weakened by scourging and loss of blood, Jesus falls beneath the weight of the cross. We remember that even Christ stumbled, and ask for compassion toward our own weakness and that of others.' },
  { title:'Jesus Meets His Mother', meditation:'Along the road, Jesus encounters Mary, who shares silently in his suffering. We ask Mary to accompany us in our own sorrows as she accompanied her son.' },
  { title:'Simon of Cyrene Helps Jesus Carry the Cross', meditation:'A passerby is compelled to help Jesus bear the cross. We pray for the willingness to help carry the burdens of others, even ones we did not choose.' },
  { title:'Veronica Wipes the Face of Jesus', meditation:'By tradition, a woman steps forward to wipe the face of Jesus. We ask for the courage to offer small mercies even amid a hostile crowd.' },
  { title:'Jesus Falls the Second Time', meditation:'Jesus falls again under the cross\u2019s weight. We consider how repeated failure need not mean abandoning the journey, only rising again.' },
  { title:'Jesus Meets the Women of Jerusalem', meditation:'Jesus tells the weeping women not to weep for him but for themselves and their children. True compassion, he reminds us, looks honestly at our own need for conversion.' },
  { title:'Jesus Falls the Third Time', meditation:'A final fall, nearest to Calvary, where exhaustion is nearly complete. We ask for perseverance in the last, hardest steps of any difficult path.' },
  { title:'Jesus is Stripped of His Garments', meditation:'Jesus is stripped in public humiliation before his execution. We consider the call to strip away pride and attachment to worldly things.' },
  { title:'Jesus is Nailed to the Cross', meditation:'Jesus is nailed to the wood and raised up between two criminals. We meditate on a suffering willingly accepted for love of us.' },
  { title:'Jesus Dies on the Cross', meditation:'Jesus commends his spirit to the Father and dies. We pause in silence before the mystery of a God who dies for his creation.' },
  { title:'Jesus is Taken Down from the Cross', meditation:'Jesus\u2019 body is removed and placed in the arms of his grieving mother. We ask Mary to receive our own sorrows as she once received her son\u2019s body.' },
  { title:'Jesus is Laid in the Tomb', meditation:'Jesus is laid in the tomb, and the stone is rolled shut. We wait in the stillness of Holy Saturday, trusting in the resurrection still to come.' }
];

// Where each station is found in Scripture (null: from tradition), and the verse of the
// Stabat Mater (Edward Caswall's translation) traditionally sung on the way to the next station
const STATIONS_EXTRA = [
  ['Matthew 27:24–26', 'At the cross her station keeping,\nStood the mournful Mother weeping,\nClose to Jesus to the last.'],
  ['John 19:16–17', 'Through her heart, His sorrow sharing,\nAll His bitter anguish bearing,\nNow at length the sword has passed.'],
  [null, 'O how sad and sore distressed\nWas that Mother highly blest\nOf the sole-begotten One!'],
  [null, 'Christ above in torment hangs;\nShe beneath beholds the pangs\nOf her dying glorious Son.'],
  ['Luke 23:26', 'Is there one who would not weep,\nWhelmed in miseries so deep,\nChrist’s dear Mother to behold?'],
  [null, 'Can the human heart refrain\nFrom partaking in her pain,\nIn that Mother’s pain untold?'],
  [null, 'Bruised, derided, cursed, defiled,\nShe beheld her tender Child\nAll with bloody scourges rent.'],
  ['Luke 23:27–31', 'For the sins of His own nation,\nSaw Him hang in desolation,\nTill His spirit forth He sent.'],
  [null, 'O thou Mother! fount of love!\nTouch my spirit from above,\nMake my heart with thine accord.'],
  ['John 19:23–24', 'Make me feel as thou hast felt;\nMake my soul to glow and melt\nWith the love of Christ my Lord.'],
  ['Luke 23:33–34', 'Holy Mother! pierce me through;\nIn my heart each wound renew\nOf my Saviour crucified.'],
  ['Luke 23:44–46', 'Let me share with thee His pain,\nWho for all my sins was slain,\nWho for me in torments died.'],
  ['John 19:38', 'Let me mingle tears with thee,\nMourning Him who mourned for me,\nAll the days that I may live.'],
  ['John 19:40–42', 'By the cross with thee to stay,\nThere with thee to weep and pray,\nIs all I ask of thee to give.']
];
STATIONS_EXTRA.forEach(([ref, stanza], i) => Object.assign(STATIONS_DATA[i], { ref, stanza }));
const STATIONS_COLOR = 'var(--purple)';

let stationsStep = null;   // null: the overview; 14: finished

// The Way of the Cross as a winding road of fourteen stops
function stationsSvg(current){
  const pts = STATIONS_DATA.map((s, i) => ({ x:100 + 50 * Math.sin(i * 0.95), y:26 + i * 38 }));
  let d = `M${pts[0].x.toFixed(1)} ${pts[0].y}`;
  for(let i = 1; i < pts.length; i++){
    const p = pts[i - 1], q = pts[i], my = (p.y + q.y) / 2;
    d += `C${p.x.toFixed(1)} ${my} ${q.x.toFixed(1)} ${my} ${q.x.toFixed(1)} ${q.y}`;
  }
  return `<svg class="stations-svg" viewBox="0 0 200 546" role="img" aria-label="The fourteen stations, showing your place. Select a station to go to it.">
    <path class="ss-road" d="${d}"/>
    ${pts.map((p, i) => `<g class="ss-stop${i < current ? ' done' : i === current ? ' current' : ''}" data-goto="${i}">
      <title>${ROMAN[i]}. ${escapeHtml(STATIONS_DATA[i].title)}</title>
      <circle cx="${p.x.toFixed(1)}" cy="${p.y}" r="14"/>
      <text x="${p.x.toFixed(1)}" y="${p.y + 4}">${ROMAN[i]}</text>
    </g>`).join('')}
  </svg>`;
}

function renderStationsStart(){
  devoKeys = null;
  entryListEl.innerHTML = `
    <div class="devo-start" style="--devo:${STATIONS_COLOR}">
      <article class="devo-card devo-intro">
        <div class="devo-emblem">${devoMedal(cardArt('budcross'))}</div>
        <div class="devo-kicker">Via Crucis</div>
        <h3 class="devo-title">Walk the Way of the Cross</h3>
        <div class="devo-rule" aria-hidden="true"></div>
        <p class="devo-closing">Follow Jesus from Pilate’s judgment to the tomb in fourteen stations. At each one, pray the versicle, meditate on the moment, and offer an Our Father, a Hail Mary, and a Glory Be. A verse of the Stabat Mater carries you on to the next station.</p>
        <div class="devo-actions"><button class="btn primary pill" id="stationsBeginBtn">Begin at the First Station</button></div>
        <p class="devo-small">Traditionally prayed on Fridays, and especially during Lent · about 25 minutes</p>
      </article>
      <h3 class="devo-subhead">Or begin at any station</h3>
      <div class="station-grid">
        ${STATIONS_DATA.map((s, i) => `<button class="station-tile" data-station="${i}"><span class="station-num">${ROMAN[i]}</span><span>${escapeHtml(s.title)}</span></button>`).join('')}
      </div>
    </div>`;
  document.getElementById('stationsBeginBtn').addEventListener('click', () => { stationsStep = 0; renderStations(); });
  entryListEl.querySelectorAll('[data-station]').forEach(b => b.addEventListener('click', () => { stationsStep = Number(b.dataset.station); renderStations(); window.scrollTo({ top:0 }); }));
}

function renderStations(){
  entryListEl.innerHTML = '';
  if(isEastern()) return renderGuided('ephrem');
  if(stationsStep === null) return renderStationsStart();
  const total = STATIONS_DATA.length;
  const again = () => { stationsStep = null; renderStations(); };
  if(stationsStep >= total){
    logPrayer('stations');
    return renderDevotionDone({
      kind:'stations', color:STATIONS_COLOR, emblem:devoMedal(cardArt('budcross')), title:'You have walked the Way of the Cross',
      text:'We adore You, O Christ, and we bless You, because by Your holy cross You have redeemed the world.', againLabel:'Walk the Stations again', again
    });
  }
  const s = STATIONS_DATA[stationsStep];
  const body = `
    <div class="devo-versicle">
      <p><span class="rubric">℣.</span>${escapeHtml(STATIONS_VERSICLE.v)}</p>
      <p><span class="rubric">℟.</span>${escapeHtml(STATIONS_VERSICLE.r)}</p>
    </div>
    <p class="devo-lead">${escapeHtml(s.meditation)}</p>`;
  const extra = `
    <div class="devo-meta">${s.ref ? scriptureLink(s.ref) : '<span class="devo-tradition">From the tradition of the Church</span>'}</div>
    <p class="devo-said">Our Father · Hail Mary · Glory Be</p>
    <div class="devo-stanza"><span class="devo-stanza-label">Stabat Mater</span>${escapeHtml(s.stanza).replace(/\n/g, '<br>')}</div>`;
  const track = `<div class="devo-pips devo-pips-14" aria-hidden="true">${STATIONS_DATA.map((x, i) => `<span class="${i < stationsStep ? 'done' : i === stationsStep ? 'current' : ''}">${i + 1}</span>`).join('')}</div>`;
  renderDevotionStep({
    kind:'stations', color:STATIONS_COLOR, step:stationsStep, total,
    emblem:devoMedal(`<span class="devo-numeral">${ROMAN[stationsStep]}</span>`),
    kicker:`Station ${ROMAN[stationsStep]} of XIV`, title:s.title, body, extra, track,
    aside:stationsSvg(stationsStep),
    go:i => { stationsStep = Math.max(0, Math.min(i, total)); renderStations(); },
    exit:again, exitLabel:'Back to all stations'
  });
}

/* =========================================================
   DIVINE MERCY CHAPLET
   ========================================================= */
const CHAPLET_PRAYERS = {
  opening: 'You expired, Jesus, but the source of life gushed forth for souls, and an ocean of mercy opened up for the whole world. O Fount of Life, unfathomable Divine Mercy, envelop the whole world and empty Yourself out upon us.',
  eternalFather: 'Eternal Father, I offer You the Body and Blood, Soul and Divinity of Your dearly beloved Son, Our Lord Jesus Christ, in atonement for our sins and those of the whole world.',
  forTheSake: 'For the sake of His sorrowful Passion, have mercy on us and on the whole world.',
  holyGod: 'Holy God, Holy Mighty One, Holy Immortal One, have mercy on us and on the whole world.',
  closing: 'Eternal God, in whom mercy is endless and the treasury of compassion inexhaustible, look kindly upon us and increase Your mercy in us, that in difficult moments we might not despair nor become despondent, but with great confidence submit ourselves to Your holy will, which is Love and Mercy itself.'
};

let chapletSequence = null;
let chapletStep = 0;

const CHAPLET_COLOR = 'var(--teal)';

function buildChapletSequence(){
  const seq = [];
  seq.push({ label:'Sign of the Cross', prayer:ROSARY_PRAYERS.cross, at:'cross' });
  seq.push({ label:'Opening Prayer', prayer:CHAPLET_PRAYERS.opening, at:'cross' });
  seq.push({ label:'Our Father', prayer:ROSARY_PRAYERS.ourFather, at:'p-of' });
  seq.push({ label:'Hail Mary', prayer:ROSARY_PRAYERS.hailMary, at:'p-hm1' });
  seq.push({ label:'Apostles’ Creed', prayer:ROSARY_PRAYERS.creed, at:'p-hm2' });
  for(let d = 1; d <= 5; d++){
    seq.push({ label:'Eternal Father', prayer:CHAPLET_PRAYERS.eternalFather, decade:d, at:d === 1 ? 'p-a' : `d${d}-of` });
    for(let j = 1; j <= 10; j++) seq.push({ label:'For the Sake of His Sorrowful Passion', prayer:CHAPLET_PRAYERS.forTheSake, decade:d, bead:j, at:`d${d}-${j}` });
  }
  for(let k = 1; k <= 3; k++) seq.push({ label:'Holy God', note:`${k} of 3`, prayer:CHAPLET_PRAYERS.holyGod, at:'medal', holy:k });
  seq.push({ label:'Closing Prayer', prayer:CHAPLET_PRAYERS.closing, at:'medal' });
  return seq;
}

// "The Hour of Mercy is now" or how long until 3:00 pm
function hourOfMercyText(){
  const now = new Date();
  if(now.getHours() === 15) return 'It is the Hour of Mercy now.';
  const next = new Date(now);
  next.setHours(15, 0, 0, 0);
  if(next <= now) next.setDate(next.getDate() + 1);
  const mins = Math.round((next - now) / 60000), h = Math.floor(mins / 60), m = mins % 60;
  return `The Hour of Mercy begins in ${h ? h + ' hr ' : ''}${m} min.`;
}

function renderChapletStart(){
  devoKeys = null;
  entryListEl.innerHTML = `
    <div class="devo-start" style="--devo:${CHAPLET_COLOR}">
      <article class="devo-card devo-intro devo-mercy">
        <div class="devo-emblem">${devoMedal(cardArt('rays'))}</div>
        <div class="devo-kicker">Jesus, I trust in You</div>
        <h3 class="devo-title">The Chaplet of Divine Mercy</h3>
        <div class="devo-rule" aria-hidden="true"></div>
        <p class="devo-closing">Given by Christ to St. Faustina Kowalska in the 1930s, the Chaplet is prayed on ordinary rosary beads, especially at 3:00 pm, the hour of Christ’s death.</p>
        <p class="devo-pill">${hourOfMercyText()}</p>
        <div class="devo-actions"><button class="btn primary pill" id="chapletBeginBtn">Begin praying</button></div>
        <p class="devo-small">Five decades · about 10 minutes</p>
      </article>
      <details class="devo-howto">
        <summary>How to pray the Chaplet</summary>
        <div class="howto-grid">
          ${rosarySvg(null, null, { big:'✠', small:'Jesus, I trust in You' })}
          <ol>
            <li>Begin with the Sign of the Cross and the opening prayer.</li>
            <li>Pray one Our Father, one Hail Mary, and the Apostles’ Creed.</li>
            <li>On each large bead, pray “Eternal Father, I offer You…”</li>
            <li>On each of the ten small beads, pray “For the sake of His sorrowful Passion…”</li>
            <li>After the fifth decade, pray “Holy God, Holy Mighty One…” three times, then the closing prayer.</li>
          </ol>
        </div>
      </details>
    </div>`;
  document.getElementById('chapletBeginBtn').addEventListener('click', () => {
    chapletSequence = buildChapletSequence();
    chapletStep = 0;
    renderChaplet();
  });
}

function renderChaplet(){
  entryListEl.innerHTML = '';
  if(isEastern()) return renderGuided('trisagion');
  if(!chapletSequence) return renderChapletStart();
  const total = chapletSequence.length;
  const again = () => { chapletSequence = null; chapletStep = 0; renderChaplet(); };
  if(chapletStep >= total){
    logPrayer('chaplet');
    return renderDevotionDone({
      kind:'chaplet', color:CHAPLET_COLOR, emblem:devoMedal(cardArt('rays')), title:'You have prayed the Chaplet of Divine Mercy',
      text:'Jesus, I trust in You.', againLabel:'Pray the Chaplet again', again
    });
  }
  const step = chapletSequence[chapletStep];
  const d = step.decade;
  const kicker = d ? `Decade ${ROMAN[d - 1]} of V` : step.holy ? `Holy God · ${step.note}` : 'Divine Mercy Chaplet';
  const track = step.bead ? devoBeadRow(10, step.bead, `Bead ${step.bead} of 10`)
    : step.holy ? devoBeadRow(3, step.holy, `${step.holy} of 3`) : '';
  const finishedDecades = d ? d - 1 : (step.at === 'medal' ? 5 : 0);
  const pips = `<div class="devo-pips" aria-hidden="true">${[1, 2, 3, 4, 5].map(i => `<span class="${i <= finishedDecades ? 'done' : i === d ? 'current' : ''}">${ROMAN[i - 1]}</span>`).join('')}</div>`;
  renderDevotionStep({
    kind:'chaplet', color:CHAPLET_COLOR, step:chapletStep, total, kicker, title:step.label,
    body:devoParas(step.prayer), track:track + pips,
    emblem:step.bead ? '<span class="devo-ornament"></span>' : devoMedal(cardArt('rays')),
    aside:rosarySvg(step.at, chapletSequence, { big:d ? ROMAN[d - 1] : '✠', small:'Jesus, I trust in You' }),
    go:i => { chapletStep = Math.max(0, Math.min(i, total)); renderChaplet(); },
    exit:again, exitLabel:'Start over'
  });
}

/* =========================================================
   CHAPLET OF THE SACRED HEART
   Thirty-three small beads, one for each year of Christ's life on earth, and six large beads:
   one large and three small on the pendant, then five groups of one large and six small.
   ========================================================= */
const SH_PRAYERS = {
  large: 'O Sweetest Heart of Jesus, I implore that I may ever love Thee more and more.',
  small: 'Sweet Heart of Jesus, be my love.',
  mary: 'Sweet Heart of Mary, be my salvation.',
  closing: 'May the Heart of Jesus in the Most Blessed Sacrament be praised, adored, and loved with grateful affection, at every moment, in all the tabernacles of the world, even to the end of time. Amen.'
};
const SH_COLOR = 'var(--wine)';
let shSequence = null;
let shStep = 0;

const SH_GEOM = (() => {
  const cx = 150, cy = 146, r = 116, gap = 14;
  const beads = [];
  const add = (key, x, y, size) => beads.push({ key, x, y, size });
  add('cross', 150, 420, 'cross');
  add('p-big', 150, 379, 'big');
  [1, 2, 3].forEach(i => add('p-' + i, 150, 368 - i * 19, 'small'));
  const units = [];
  for(let g = 1; g <= 5; g++){
    units.push({ key:`g${g}-big`, w:1.9, size:'big' });
    for(let j = 1; j <= 6; j++) units.push({ key:`g${g}-${j}`, w:1.15, size:'small' });
  }
  const totalW = units.reduce((n, u) => n + u.w, 0);
  let acc = 0;
  units.forEach(u => {
    const a = (90 + gap + (360 - 2 * gap) * (acc + u.w / 2) / totalW) * Math.PI / 180;
    acc += u.w;
    add(u.key, cx + r * Math.cos(a), cy + r * Math.sin(a), u.size);
  });
  add('medal', 150, cy + r + 10, 'medal');
  beads.forEach((b, i) => { b.order = i; });
  return { cx, cy, r, beads, byKey:Object.fromEntries(beads.map(b => [b.key, b])) };
})();

function buildSacredHeartSequence(){
  const seq = [];
  seq.push({ label:'Sign of the Cross', prayer:ROSARY_PRAYERS.cross, at:'cross' });
  seq.push({ label:'Soul of Christ', prayer:prayerText('p24'), at:'cross' });
  const group = (g, big, smalls) => {
    seq.push({ label:'O Sweetest Heart of Jesus', prayer:SH_PRAYERS.large, group:g, at:big });
    smalls.forEach((at, j) => seq.push({ label:'Sweet Heart of Jesus', prayer:SH_PRAYERS.small, group:g, bead:j + 1, of:smalls.length, at }));
    seq.push({ label:'Sweet Heart of Mary', prayer:SH_PRAYERS.mary, group:g, mary:true, at:smalls[smalls.length - 1] });
  };
  group(0, 'p-big', ['p-1', 'p-2', 'p-3']);
  for(let g = 1; g <= 5; g++) group(g, `g${g}-big`, [1, 2, 3, 4, 5, 6].map(j => `g${g}-${j}`));
  seq.push({ label:'Closing Prayer', prayer:SH_PRAYERS.closing, at:'medal' });
  return seq;
}

function renderSacredHeartStart(){
  devoKeys = null;
  const center = { big:'♥', small:'Sweet Heart of Jesus' };
  entryListEl.innerHTML = `
    <div class="devo-start" style="--devo:${SH_COLOR}">
      <article class="devo-card devo-intro">
        <div class="devo-emblem">${devoMedal(cardArt('heart'))}</div>
        <div class="devo-kicker">Sweet Heart of Jesus, be my love</div>
        <h3 class="devo-title">The Chaplet of the Sacred Heart</h3>
        <div class="devo-rule" aria-hidden="true"></div>
        <p class="devo-closing">Devotion to the Sacred Heart of Jesus spread through the Church after Christ’s appearances to St. Margaret Mary Alacoque at Paray-le-Monial between 1673 and 1675. This chaplet honors his Heart on thirty-three small beads, one for each year of his life on earth. It is especially loved on First Fridays and through the month of June.</p>
        <div class="devo-actions"><button class="btn primary pill" id="shBeginBtn">Begin praying</button></div>
        <p class="devo-small">Thirty-three beads · about 10 minutes</p>
      </article>
      <details class="devo-howto">
        <summary>How to pray the Chaplet</summary>
        <div class="howto-grid">
          ${rosarySvg(null, null, center, SH_GEOM)}
          <ol>
            <li>On the crucifix, make the Sign of the Cross and pray the Soul of Christ (Anima Christi).</li>
            <li>On each large bead, pray “O Sweetest Heart of Jesus, I implore that I may ever love Thee more and more.”</li>
            <li>On each small bead, pray “Sweet Heart of Jesus, be my love.”</li>
            <li>After each group of small beads, pray “Sweet Heart of Mary, be my salvation.”</li>
            <li>Begin with the three small beads on the pendant, then pray the five groups of six around the chaplet.</li>
            <li>At the centerpiece, close with “May the Heart of Jesus in the Most Blessed Sacrament be praised, adored, and loved…”</li>
          </ol>
        </div>
        <p class="devo-small">Some chaplets use “Jesus, meek and humble of heart, make my heart like unto Thine” on the large beads instead. Any rosary can be used: pray six small beads in each decade.</p>
      </details>
    </div>`;
  document.getElementById('shBeginBtn').addEventListener('click', () => {
    shSequence = buildSacredHeartSequence();
    shStep = 0;
    renderSacredHeart();
  });
}

function renderSacredHeart(){
  entryListEl.innerHTML = '';
  if(isEastern()) return renderGuided('communion');
  if(!shSequence) return renderSacredHeartStart();
  const total = shSequence.length;
  const again = () => { shSequence = null; shStep = 0; renderSacredHeart(); };
  if(shStep >= total){
    logPrayer('sacredheart');
    return renderDevotionDone({
      kind:'sacredheart', color:SH_COLOR, emblem:devoMedal(cardArt('heart')), title:'You have prayed the Chaplet of the Sacred Heart',
      text:'Sacred Heart of Jesus, I place all my trust in Thee.', againLabel:'Pray the Chaplet again', again
    });
  }
  const step = shSequence[shStep];
  const g = step.group;
  const kicker = g === 0 ? 'The pendant' : g ? `Group ${ROMAN[g - 1]} of V` : step.at === 'medal' ? 'Conclusion' : 'Chaplet of the Sacred Heart';
  const track = step.bead ? devoBeadRow(step.of, step.bead, `Bead ${step.bead} of ${step.of}`) : '';
  const finished = g === undefined ? (step.at === 'medal' ? 5 : 0) : Math.max(0, g - 1);
  const pips = `<div class="devo-pips" aria-hidden="true">${[1, 2, 3, 4, 5].map(i => `<span class="${i <= finished && step.at !== 'cross' ? 'done' : i === g ? 'current' : ''}">${ROMAN[i - 1]}</span>`).join('')}</div>`;
  renderDevotionStep({
    kind:'sacredheart', color:SH_COLOR, step:shStep, total, kicker, title:step.label,
    body:devoParas(step.prayer), track:track + pips,
    emblem:step.bead || step.mary ? '<span class="devo-ornament"></span>' : devoMedal(cardArt('heart')),
    aside:rosarySvg(step.at, shSequence, { big:g ? ROMAN[g - 1] : '♥', small:'Sweet Heart of Jesus' }, SH_GEOM),
    go:i => { shStep = Math.max(0, Math.min(i, total)); renderSacredHeart(); },
    exit:again, exitLabel:'Start over'
  });
}

