const LISTS_EAST = LISTS.map(l => LISTS_EAST_SWAP[l.id] || l);

function lsItemsHtml(items, plain){
  return `<ol class="ls-items${plain ? ' plain' : ''}">${items.map(([t, x, sw]) => `<li><span class="ls-term">${sw ? `<span class="ls-swatch" style="background:${sw}"></span>` : ''}${escapeHtml(t)}</span>${x ? `<span class="ls-x">${escapeHtml(x)}</span>` : ''}</li>`).join('')}</ol>`;
}
function lsCardHtml(d){
  return `
      <section class="dv-card" id="dv-${d.id}" style="--dv:var(--${d.color})">
        <header class="dv-head"><span class="dv-icon">${navIcon(d.icon)}</span><div><div class="daily-kicker">${escapeHtml(d.kicker)}</div><h3>${escapeHtml(d.name)}</h3></div></header>
        ${d.about ? `<p>${escapeHtml(d.about)}</p>` : ''}
        ${d.items ? lsItemsHtml(d.items, d.plain) : ''}
        ${(d.groups || []).map(([g, items]) => `<h4>${escapeHtml(g)}</h4>${lsItemsHtml(items, d.plain)}`).join('')}
        ${d.note ? `<p class="dv-note">${escapeHtml(d.note)}</p>` : ''}
        ${d.source ? `<p class="ls-source">${escapeHtml(d.source)}</p>` : ''}
      </section>`;
}
function renderGuidePage(list, foot){
  entryListEl.innerHTML = `
    <div class="dv-page">
      <nav class="dv-jump" aria-label="On this page">${list.map(d => `<button class="dv-chip" data-dv="${d.id}" style="--dv:var(--${d.color})">${escapeHtml(d.name)}</button>`).join('')}</nav>
      ${list.map(lsCardHtml).join('')}
      ${foot || ''}
    </div>`;
  entryListEl.querySelectorAll('[data-dv]').forEach(b => b.addEventListener('click', () => {
    const el = document.getElementById('dv-' + b.dataset.dv);
    if(el) el.scrollIntoView({ behavior:'smooth', block:'start' });
  }));
}
function renderLists(){
  renderGuidePage(isEastern() ? LISTS_EAST : LISTS,
    '<p class="dv-note">CCC refers to the paragraphs of the Catechism of the Catholic Church. <button class="text-link" data-route="library/catechism">Open the Catechism →</button></p>');
}

